/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20181029-9","meetingId":"h30-cm10","date":"2018年10月29日","dateIso":"2018-10-29","committee":"文教委員会","time":"午前１０時００分～午後 ３時２２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を106件整理しています。","topics":[{"id":"topic-01","title":"第７５号議案、品川区立保育所条例の一部を改正する条例","agenda":"第７５号議案、品川区立保育所条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"完成したときのそれぞれの定員数を教えていただきたいのと、そのあたりの事業者の選定等々はどういう日程になっているのか、その辺を説明を求めました。","respondent":"吉田保育施設調整担当課長","answer":"八潮南保育園の定員につきましては、現在１０２名ですが、それを５名減らす形で９７名になるというのは以前の文教委員会のほうでもご報告しています。八潮北保育園については、平成３４年から民営化いたしますので、平成３２年度に業者を選定する予定としています。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"幼保一体施設のほうについてなのですが、幼稚園部分と保育園部分、それぞれの定数を改めて確認したいので、別々に教えてほしいと求めました。職員はどういうふうな処遇になるのか、ちょっとその辺が全くわからないので、今の考え方でいいですから教えてほしいと求めました。","respondent":"吉田保育施設調整担当課長","answer":"平成３４年から受託した事業者に速やかに移行できるように１年間程度の猶予を考えて今のところ予定しているところです。平成２８年度に一旦、八潮わかば幼稚園を含めまして４園ほどありましたけれども、そちらのほうには説明をいたしております。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっと違うのかなと思ったので、再確認で、それぞれの定数を教えてほしいと求めました。職員は平成３４年度からは他の保育園に異動するということなのですが、そのあたりをどういうふうに区として考えているのかを伺いたいと思います。","respondent":"吉田保育施設調整担当課長、佐藤保育課長","answer":"このようなところを参考にしながら、品川区でどのように行っていくかというところを検討しています。１年あとになりますけれども、平成３２年度に改修した後、平成３５年度から民営化のほうを進めていく予定で進めているところです。 民営化実施時の保育士の採用の関係ですが、現時点での考え方になりますけれども、現行と同様に退職者の数に応じて新規の採用をしていますから、そういった形でやっていきたいと考えております。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"進んでいるわけですから、信頼を持っていただけるような、そういう移行の仕方を強く求めておきたいというふうに思います。でも、本当はとめていただきたいというのが私の本音なのですけれども、今回はしようがないかなと悔しい思いをしながら見ているのですけどね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"わかりました。だけど、しっかりと対応していただきたいということをちょっと悔しい思いも込めながら申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"今もその考えは変わりがないのかどうかお伺いするのが１点です。いつから、どこの保育園が民営化されるのか、改めて伺います。","respondent":"吉田保育施設調整担当課長","answer":"考え方としては、やはり建物がある程度新しくないと、その後受託した業者が修繕に大変苦労するという話がありました。平成３５年から八潮西保育園、平成３６年から一本橋保育園、この４園まで決まっているところです。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"やはり私たちはこの点、ちょっと納得できないのですが、いかがでしょうか。もっときちんと改修してほしい保育園があるのですけれども、どう考えていらっしゃるのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"そこのところに対応するためには、八潮につきましては、これまであまり改修工事等もやってこなかったというところが原因です。確かに建ててから５０年過ぎのものも結構たくさんあるのですけれども、なかなか計画を立てて、ここからやろうというのは難しい状況です。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"何か希望が全然見えないのですけれども、今後５０年もたっているような保育園も含めてどのように考えているのか、１点お伺いしたいです。やはり声がないというのは、やはり今後の状況を親御さんたちにきちんと伝える手だてをとっていただきたいと思うのですが、その点はいかがか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"４園は最初に説明したままで、その後説明がないということなのですけれども、現在いらっしゃる利用者が民営化にかかるような場合がございました。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区の考えはどういうものなのかというのをきちんと区民全体に伝えていくという姿勢を持たない限り、もっと広く知らせてほしいと求めました。これは本当にしていただきたいと思うので、どうか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"周知の方法については、また今後検討してまいるところです。","id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけ確認をさせていただきたいのですが。区も交えて、いわゆる三者でされているのか、その辺の調整方法というのはどのようにされているのか説明を求めました。","respondent":"吉田保育施設調整担当課長","answer":"それからあと、２番目の旧校庭と言われるところですけれども、２,２００m2ほどあります。校庭の使い方については、その辺は区とまた事業者のほうで調整しながら進めてまいりたいと今検討しています。","id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"いわゆる問題がないようにしっかりと、調整というよりも連携というのですかね、それは区のほうも一緒になってやっていただければと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"渡部委員","kind":"質問・要望","question":"何年も使えるわけですから、今も質問でご説明がありましたけれども、必要であれば保育園の改築を進めていただきたい。まだ始まっているわけではないわけですから、これから始まるわけですから、ちょっとその辺の考え方だけ説明を求めました。","respondent":"吉田保育施設調整担当課長","answer":"５園ほどお試し期間といいますか、それでその状況等を鑑みながら今後の方針をどういうふうにしていくかを定めていきたいと考えているところです。それから長期基本計画等で鑑みながら今後の保育のニーズといいますか、その辺のところを調整していければと予定しております。","id":"exchange-012"},{"speaker":"渡部委員","kind":"質問","question":"６００人強でしょうか、逆にここの旧荏原第四中学校跡地は広いですから、何かその辺というのは考えにも上がってこなかったのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"両方とも児童センターがある保育園になりますが、こちらにつきましては、建て替えまでは一時的に児童センターを閉じている形になります。それから、その５年間の中で何ができるかというところで公設民営と建て替えにつきまして、２園ほどの予定を組んできたところです。","id":"exchange-013"},{"speaker":"渡部委員","kind":"質問・要望","question":"承知しております。ここがあるうちに一気に仕掛けられることは仕掛けていただきたいなという要望だけをして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"きちんとやってもらえたので民営化した後も安心して預けることができたというお話を伺ったことがあるので、確認です。もう一つは、旧荏原第四中学校のほうなのですけれども、園児の移動は両方とも４月１日なのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"八潮わかば幼稚園のところに八潮すこやか園ができる、４月１日から稼働させる予定ですので、八潮南保育園は４月１日までに動かします。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"混乱が出るため１カ月日程のずれがあるということですけれども、入園して１カ月で動くので、移動は十分配慮してお願いしたいと思います。給食室ですが、旧荏原第四中学校のほうの保育園の給食室はどうなるのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"この図で言いますと、ピンク色のところの左側のほうに給食室をつくっているところです。そちらのほうで給食の用意を行う予定です。","id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"質問","question":"では、旧荏原第四中学校のほうは、ピンク色の一番左側のところでつくって、そこから外を通って運ぶわけですか。両方に持っていくわけか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"説明が不足して申しわけございませんでした。調理を行いますし、公設民営として建てたほうは、その受託事業者のほうで調理を行うというような状況となります。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"困ったというような状況に対しては、区がしっかりと説明をしていただいて、その件についてどうかというのを一つ伺いたいです。最後に、ここで一、民間委託にしていくということを決断した理由というのは何だったのかをもう一度確認したいと思いますのでお願いします。","respondent":"吉田保育施設調整担当課長","answer":"近隣への配慮や近隣への上手な周知といいましょうか、ご理解をいただきながらこの辺は進めていければと考えているところです。最終的には一定程度の民設民営化によって運営コストを下げるというところを前提に考えております。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"４園は、実施するに当たってのテストと、そういう状況で捉えているということですか。そうであるとしたら、とんでもないと、ちょっとあまりにも無責任だなと私は思いますので、その辺についてどうなのかを確認したいと思います。","respondent":"吉田保育施設調整担当課長","answer":"区のほうとしても苦情への対応、この辺につきましては、今後も進めてまいるところです。そういう中で、そういうところもございまして、財政負担軽減のところからも民間委託を一定程度進めていく必要があると考えております。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"１０億円かかるということの意味がよくわからないので、もう一度説明していただきたいのと、民間活力とコスト削減、この２つがテストとしてやる、この４園の民間委託だと、そういうことでいいのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"１０億円につきましては、例えば一つの保育施設を建て替えるときの大体目安としての金額として申し上げた次第です。区の一般財源の使用を抑えられるという意味では、国の補助金が使えるような民間園というのは、これはある一定程度必要なものと考えております。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"子どもを育てるのに経費を削減することが優先されていいのでしょうか。次回のときでいいのですけれども、ここはきちんとご答弁をほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"つる委員","kind":"質問","question":"過去の質疑を見ると大体１００名定員ぐらいだと、１園当たり、ざっくり１億５,０００万円ぐらいの運営費という考え方ですかね。一番大事な視点はあくまでもそこに登園してくるお子さんをはじめ、何かあわせてそういった取り組みができるのかどうかというのを説明を求めました。","respondent":"佐藤保育課長","answer":"その浮いた財源に関しましては、委員ご指摘のとおり保育の質の担保というのは非常に重要な課題だと考えております。環境、人材、６月補正でいただきましたのびしなプロフェッショナルスクール等を創設して全力で取り組んでまいりたいと考えております。","id":"exchange-022"},{"speaker":"つる委員","kind":"質問・要望","question":"なので、ぜひそのあたりもあわせて積極的な取り組みないし周知等をあわせて行ってほしいと求めました。１億５,０００万円ぐらいの運営費がかかるわけですが、保育園の部分について、何かいい意味での削減効果というのはあるのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"例えばですけれども、保育園と幼稚園が一緒になったことによって、運動会だとかその他の事業とかを一緒にできる、こういったメリットが出てきます。金銭的なメリットのところにつきましては、今後検討の部分です。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"民営化反対、中止をこれからも求め続けていきますので、その点はしっかり言っておきたいと思います。以上、反対をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-02","title":"第７６号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例","agenda":"第７６号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"家庭的保育事業の実態を知りたいので教えてほしいと求めました。まず家庭的保育事業の事業内容をざっくりと教えていただきたいのと、ここでの給食の提供が現状どうなっているのか、具体的に中身を説明を求めました。","respondent":"大澤保育支援課長","answer":"給食の状況ですけれども、今２施設あるうち、１施設は自園調理となっております。もう１施設は、外部の給食事業者からの搬入という形をとっております。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"一つは、外部の給食事業者の搬入と言われましたけれども、どういうところから、どんな給食内容が届けられるのか、あと費用等はどうなっているのか説明を求めました。","respondent":"大澤保育支援課長","answer":"外部搬入ですけれども、離乳食ですとか、アレルギー対応も可能な事業者から、それに対応した内容となっております。費用につきましては、運営費の中からお支払いしているという形になります。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"条例は本来５年以内に自園方式にするように求めているのだと思うのですが、条例が求めている内容をもう一回知りたいのと、現状の中身を説明を求めました。","respondent":"大澤保育支援課長","answer":"区としましても自園調理が原則ということは認識してございまして、そこを変えるつもりはありません。その辺を踏まえまして国に合わせて５年の延長をして、その中で何とか自園調理ができるようにしていただきたいというのが現在の状況です。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"区が支援できるのではないでしょうか。ぜひ区が支援をして、一刻も早く実現をすべきではないかと思っていますけれども、この辺はいかがか尋ねました。","respondent":"大澤保育支援課長","answer":"１事業者については平成２７年度から５年間の経過措置の間に、自園調理にできたということになります。５年延長して、その中で区としてもできる支援はさせていただいて、何とか平成３７年度までには自園調理ができるように支援していきたいと思います。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"できることをするのだったら早くして、これを延長しなくても平成２７年から５年の間に実現できるような中身にしていただきたいなと思います。条例の第７条のところに、連携協力を行う保育所と書いてあるのですけれども、これはどういう意味で、どこがこれに当たるのかを説明を求めました。","respondent":"大澤保育支援課長","answer":"今５年の延長をということでご要望があるのは、維持管理が給食となると厳しいですので、なかなかそこまでは手が回らないと聞いております。財政的な支援もいたしておりますし、具体的に何かご相談があれば話を聞きながら支援していくという形になろうかと思います。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"ぜひここはお願いしたいと思います。連携園は日ごろいろいろな面で連携して支援が何か得られているということなのか、もう少しその中身を説明を求めました。","respondent":"大澤保育支援課長","answer":"連携園につきましては、家庭的保育事業が例えばお休みのときに区立園で預かるとか、そのような連携をしております。３歳以降に入る園を既に決めておりますので、卒園後はそちらの連携園で受け入れるという形になってあります。","id":"exchange-030"},{"speaker":"南委員","kind":"確認","question":"当面、この期間、そういう保育園に対して自園方式に転換していきましょうという働きかけはしてきたのかどうかの確認をしたいと思っているのです。どうしたら改善できるかという方向性、どういうふうに思っておられるのか、そこを確認したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"南委員","kind":"確認","question":"だから、この５年間品川区としてはずっと働きかけをしてきたかどうか、そこのところを一番確認したいと思っているので、今のご答弁では働きかけはしてきているようにも受け取られたのですけれども、ちょっと明確にしたいと考えていますので、もう一度お願いします。","respondent":"大澤保育支援課長","answer":"働きかけというのは具体的にどういうことか、ちょっと今明確になっていないのですけれども、自園調理をしていただきたいということでお願いはしてきておりますが、まだ経過措置の最中ですので、無理やり、強制的にすぐにやるようにというふうには働きかけてはおりません。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"意見","question":"経過措置があるからといって待つのではなく、やはり一刻も早く区が独自で支援して早急に実現すべきであると思っています。先延ばしは許されないと思いますので、反対をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"}]},{"id":"topic-03","title":"第７７号議案、品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例の一部を改正する条例","agenda":"第７７号議案、品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"わかったら教えていただきたいのと、なぜ第３階層の(1)、ここだけなのかというのを教えてください。今区外の支援制度の第３階層の方が対象となりますというご説明だったのですけれども、何人くらいいらっしゃるのか説明を求めました。","respondent":"大澤保育支援課長","answer":"国の改正の趣旨としましては、低所得世帯の経済的負担軽減を図るためとなっていますので、第３階層が対象となっています。区内に今のところ５名対象者がいらっしゃいます。","id":"exchange-034"}]},{"id":"topic-04","title":"第８０号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第８０号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"意見","question":"１点だけ。２の主な改正内容のところについて、この額の変更のみなのかどうか、その１点だけお願いしますとの意見を述べました。","respondent":"篠田学務課長","answer":"今回の改正内容は、それぞれ記載されておりますとおり支給限度額の改正です。","id":"exchange-035"}]},{"id":"topic-05","title":"第７４号議案、平成３０年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第７４号議案、平成３０年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"これからのところについて何校かということを伺いたいのと、工事の実施はいつごろから行われて、そこは教えてほしいと求めました。病後児保育は逆に減っているという関係で、今後、病後児保育はどういうふうになっていくのかというのを改めて確認しておきたいと思います。","respondent":"有馬庶務課長、佐藤保育課長","answer":"今、屋内運動場に設置があるのは戸越台中学校１校のみということで、全ての屋内運動場に設置していきたいというふうに考えております。具体的には次年度予算の編成の中と、今この補正予算である調査結果… 調査に基づいてニーズを埋めるのが我々の使命ですので、そういった方向で進めていきたいと考えております。","id":"exchange-036"},{"speaker":"南委員","kind":"確認","question":"それと、病児保育のほうは、これから３園なので、都合７カ所設置をしていくと、そういうことだという具体的な数字を確認したいです。議事録を確認しないで来てしまったので申しわけないのですけれども、こういう事業を拡大していくときに、その点についての見解を伺いたいと思います。","respondent":"有馬庶務課長、佐藤保育課長","answer":"ただ、浜川小学校については改築計画に入っていますので、今回この校数には入っておりません。それから、この下のほうに書いてある設置の検討委託経費というほうにも、改築が済んでいる学校もあわせて検討はしていくということで。一概に３施設、４施設というのは今現在は言えないところと、まだまだつくっていかなければいけないのかなという認識は持っております。","id":"exchange-037"},{"speaker":"南委員","kind":"質問・要望","question":"できるだけ第１回目のグループ、第２回目のグループというふうにしないで、そういう対応をしていただきたいというふうに思っています。そういうふうに受けとめていいのかどうかというのを確認して終わりたいと思います。","respondent":"有馬庶務課長","answer":"できるだけ早目にということでは考えておりますけれども、現実問題としてもある程度設備、一気に来年の夏というのは現実的には難しいと思っています。できるだけ早期のうちに計画を立てて実行していきたいと考えています。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"補正予算書の１７ページのところに、病児保育施設開設経費助成と書いてあるので、この助成の中身とか割合を教えていただきたいのが１点です。どう区別されていて、保護者とか職員に周知をしているのか、基本的なところを説明を求めました。","respondent":"佐藤保育課長","answer":"１,３５０万円につきましては内装工事費の上限で、その差額の４００万円に関しましては、あわせて１,７５０万円となります。２点目の病後児保育と病児保育の線引きの部分ですけれども、病児保育からだんだん治ってきて、回復期で病後児保育と流れるような運用です。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"骨折とか、そういうのだとわかるのですけれども、病状がどういう段階にあるのかという判断はなかなか難しいと思うのですよね。医師がすぐそばにいる病児保育のほうが安心かなという気がするのですが、その線引き等はどなたが判断するのかというあたりを説明を求めました。","respondent":"佐藤保育課長","answer":"児童連絡票というところで、お医者さんのほうにかかっていただいて、利用可能かどうかという判断をいただいております。委員のご指摘は、そこはまさにちょっと保育士のほうで説明がなかなか行き届かなくて誤解を受けたりする問題もありますので、再度周知をしています。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問","question":"医師にかかるということが前提ということですか、医師にかかった場合に、何か証明とかが必要なのですよね。それにはお金がかるのか、かからないのか、面倒ではないのか等説明を求めました。","respondent":"佐藤保育課長","answer":"病児保育の児童連絡票の関係ですが、医師会のほうにお願いして、無料で出していただいているところです。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"意見","question":"１校およそ幾らぐらいで設計段階から設置までかかるのかというのと、その辺をどう考えていくのか、その辺を聞かせてくださいとの意見を述べました。","respondent":"有馬庶務課長","answer":"設置コストに幾らぐらいかかるかということですけれども、具体的には芳水小学校の工事費を７,９２０万円と計上しています。通常あるものは、それを全部振り分けてクーラーに使っていくというのは、現状では難しいのではないかなというふうに考えております。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いろいろ出されていたので、本当にせっかくついた空調が稼働できるような電源の確保を考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"我々もかねてからこの要望をずっとしてきて、経費内訳の(1)の部分ですけれども、まず１点教えていただきたいです。いわゆる改築中の学校の経費について、事前にもし設置をできていたのなら、どのくらい削減ができたのか説明を求めました。","respondent":"有馬庶務課長","answer":"３、経費内訳の(1)、上のほうからの電気設備と設置検討の絡みですけれども。３番目の設置検討委託というのは、どういう方式で設置ができるかということを改めて検討する中身で、この検討費を計上しています。","id":"exchange-044"},{"speaker":"石田（し）委員","kind":"確認","question":"３段階あるということでいいのか、確認をさせてください。それとも、そのときにはまとめてだからかからないのか、そこを説明を求めました。","respondent":"有馬庶務課長","answer":"設置検討した後、実施設計工事というふうに進むのかというところですけれども、現状からいけばそういうふうな形で進みます。それから、この実施設計が終わった後は、ここは工事で行うつもりでおりますので、工事、工事監理費というのがかかってきます。","id":"exchange-045"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"施設について１０年なり２０年先に何を使っていくのかというのまで見据えて、余分な工事をするというのは私は税金のむだ遣いに値すると思うのです。今後絶対必要となっていくのに、工事に当たっていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"学校屋内運動場について予算書を見ると、一般財源になっているのですけれども、国と都の補助金のところが今後どうなるのか、どうしていくのか説明を求めました。","respondent":"有馬庶務課長","answer":"体育館については今後どうなるのか様子を見ていきたいと思っています。はっきりと屋内運動場についての補助金を計画しているという情報が来ておりますので、今後その概要は見ていきたいと考えています。","id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"質問","question":"急遽といいますか、予算をつけてやっていただいたというのは大変すばらしいことで、その延長上にこれもあると思っています。1)の芳水小学校的な予算の流れで、つまり改修が終わったときには何校か、芳水小学校のように入るという考え方でよろしいのか尋ねました。","respondent":"有馬庶務課長","answer":"鮫浜小学校、これから実施設計の段階で、体育館がいつまで使えるのかというところも見据えながらという形になります。鮫浜小学校は完成まで体育館を使えそうですので、ちょっとその間、簡易型のもので対応していこうかなというふうに考えております。","id":"exchange-048"},{"speaker":"つる委員","kind":"提案","question":"の質疑も伺っているところでありますけれども、都議会の公明党の代表質問で提案して、緊急要望ということで。区内業者を中心として、その工事がしっかりと賄っていけるのかどうか、そのあたりについてはどうか説明を求めました。","respondent":"有馬庶務課長","answer":"東京都のほうからも実際現状の考え方といいますか、そういったものにもしっかり回答して、補助制度活用に向けて努力してまいりたいと考えています。","id":"exchange-049"},{"speaker":"つる委員","kind":"質問・要望","question":"都知事にも要望したのは、小池知事に直接行って、そこでもしっかりお願いしますと言っております。戸越台中学校に設置されていると伺ったので、参考に利用状況というのでしょうか、教えてほしいと求めました。","respondent":"有馬庶務課長","answer":"セントラル方式になっており、スイッチを入れれば使えるという状況になっておりますので、普通教室を入れるタイミングで合わせて使っているのではないかなと思われます。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問・要望","question":"事前にいろいろ確認させていただいた中では、体育館単独というのでしょうか、上層階部分に体育館があるのが７校ぐらいだと思うのですね。８,０００万円、９,０００万円近くかけてやっていくわけですから、この当たりの遮熱についての考え方をちょっと説明を求めました。","respondent":"有馬庶務課長","answer":"ただ、どういうふうにしていくのか、それもあわせて検討していかなければいけないことかなと思います。光熱水費抑制という面からも直していくときにはきちんと対応していきたいというふうに思っております。","id":"exchange-051"},{"speaker":"つる委員","kind":"確認","question":"最後に、１点だけ、２の導入効果の３点目のところに、一般開放における区民スポーツ活動の促進とあるのですね。私も全部確認できているわけではないのですが、ないしそれに当てているところへの冷暖房設備、このあたりの考え方はいかがか尋ねました。","respondent":"有馬庶務課長","answer":"幾つあるかというのはわかりませんけれども、体育館が入って、そこの更衣室もということは当然要望も出てくるかと思います。例えば個別空調で対応できるものなのか、その一体の中でできるものなのか、あわせて検討していきたいと思います。","id":"exchange-052"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひそういったところも細かい配慮になると思いますので、今回の議案は屋内体育館ということでのご説明でしたが、あわせてそこも全体の中でぜひ積極的に検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"}]},{"id":"topic-06","title":"平成３０年陳情第１８号、認可外を含む私立保育所職員に対する品川区独自の処遇改善を求める陳情","agenda":"平成３０年陳情第１８号、認可外を含む私立保育所職員に対する品川区独自の処遇改善を求める陳情","exchanges":[{"speaker":"南委員","kind":"質問","question":"とりわけ新しくできた保育園のいわゆる賃金に関する処遇についてはどのようになっているか、改めてどう認識しているかを伺いたいと思います。とりわけ初任給がどうなのか、３年、５年経過して、その賃金はどのように推移しているのか、具体的な状況をつかんでいたら説明を求めました。","respondent":"大澤保育支援課長","answer":"平成３０年４月が２１万６,０００円、平成３１年４月の平均が、今のところ２１万８,０００円となっています。来年の４月は今のところ２０万５,０００円から２３万５,０００円で、大体どこも５,０００円程度のアップはしているような状況です。","id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"高いといっていいのか、低いのか、その辺の状況も教えてほしいと求めました。区立で働いていただいている職員の皆さんの状況とも比較をすると、どういうふうに見ているのか、その辺も説明を求めました。","respondent":"大澤保育支援課長","answer":"９０％が女性ということで、３０歳から３４歳、勤続年数が５年から９年の方の年収が３６０万円になっております。先ほど申し上げましたように、５割以上が３５０万円の収入になっておりますので、ほぼ同じような状況ではないかというふうに考えております。","id":"exchange-055"},{"speaker":"南委員","kind":"質問","question":"短大卒という３０歳から３４歳の、３５０万円以上というこの方々の年齢というのは、短大卒の３０歳から３４歳というここの年齢とほぼ同じで見ていいということなのか尋ねました。","respondent":"大澤保育支援課長","answer":"保育士の平均年齢が３４歳、平均経験年数が５.５年ですので、ほぼ同じような状況ではないかというふうに考えております。平成２９年度にはここにキャリアアップ補助金で２万１,０００円の増額と国のほうから６,０００円の増額、少しこれよりはよくなっております。","id":"exchange-056"},{"speaker":"南委員","kind":"質問","question":"私はやはり短大卒で先ほど９０％女性で３６０万円と、そこもちょっと伺いたいのと、本当に厳しいところがあります。やはり一般職と比較をして、もしそうであれば正しくないのではないかなと思っているので、そのあたりのことをちょっと伺いたいと思います。","respondent":"大澤保育支援課長","answer":"多分区の職員との差のことをおっしゃっているのかというふうに認識しておりますけれども、今保育士、単純な比較はできないかと思いますが。","id":"exchange-057"},{"speaker":"南委員","kind":"質問","question":"国基準であり、戦後数十年変わっていない基準ですから、やはりこれを改善するのは当たり前だというふうに思っているのです。看護師を０歳に入れている、なぜここに加配をしているのか、それについて伺いたいと思います。","respondent":"大澤保育支援課長","answer":"前年度に比べてかなり園の中でいろいろな保育士、平成３０年度についてはもう少し活用できる園が増えてくるのではないかというふうに考えております。","id":"exchange-058"},{"speaker":"南委員","kind":"質問・要望","question":"４対１に引き上げてほしいと、ぜひとも３歳児のところだけではなく、１・２歳児のところの基準の引き上げもやはりしていただきたい。こちらのほうに引き上げる必要があるのではないかというふうに思うのですけれども、区のこの点についての認識を伺いたいと思います。","respondent":"大澤保育支援課長","answer":"３年以上とか７年以上ということで、なるべく長く働いていただきたいという思いもあって設定しているものだというふうに認識しています。大体平均して８５％なのですけれども、この陳情にあるようなトイレにも行けないほどきついという状況ではないというふうに思っております。","id":"exchange-059"},{"speaker":"南委員","kind":"意見","question":"だから、引き上げをしてほしいというのは当然の要求だというふうに思います。きちんとした底上げが必要だということを強調したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私立保育園職員に対する処遇改善を求めているのですが、それを１点教えていただきたいのと、トータルのところをわかったら説明を求めました。","respondent":"大澤保育支援課長","answer":"区の調査は、私立認可保育園の給与の調査です。平成２９年度は上がった額としては、平均ですけれども、６万６,０００円の見込みとなります。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問","question":"私立認可保育園で平均６万６,０００円の見込みだったということなのですけれども、認可外とか、認可以外のところは調べられていないのでしょうか。実際に手元に幾ら届いたのかというところまで認可外も含めて調査がされているのかどうかというのと、つかんでいたら説明を求めました。","respondent":"大澤保育支援課長","answer":"そういう意味でちょっと給与を全部報告しろというのはかなり難しいことではないかというふうに考えており、調査をかけたことはございません。研修をどのくらい受けているかという人数については、今のところ把握はできていません。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３割というのはなぜ受けていないのか、何か障害があるのかどうか、ちょっとそこを教えていただきたいのが１点です。保育士の配置基準のところなのですか、１５対１というふうに基準でなっているのですけれども、２０対１が１５対１に変わったのではなかったですかね。","respondent":"大澤保育支援課長","answer":"５分の１の人しかだめであるということが緩和されているので、活用するようになるのではないかというふうに見込んでいるところです。東京都として５対１だったのはだいぶ昔、多分平成１８年までです。","id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問・要望","question":"国基準が１歳児は６対１ということで、都基準がなくなったということですかね。６対１が戦後ずっと続いているこの基準を国にも求めなければいけないし、国が変えないのだったら、幼稚園が今３０とか３２対１になっていますかね。","respondent":"大澤保育支援課長","answer":"確かにここに書いてある２０対１、３０対１ではきついというふうには認識していますが、３０人を１人で見ているような園はございません。国基準の３０対１では確かにきついという認識はありますので、それ以上の配置はしているところを確認しております。","id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問","question":"看護師加配とおっしゃったけれども、品川区は看護師が配置されている分、保育士と置きかわっているのではないですか。保育環境にしていく基礎がここの定数にあるので、ぜひここの定数問題というのはずっと言われ続けている中身なので、実際に３０対１……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、国基準が不十分なので、地方自治体に対して、品川区に対してもっと引き上げてほしいと求めているというところを……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはりフランスなど、よその国の例などにぜひ目を向けていただきたいし、保育者の悲願なのですよね。職員の声というのはどういうふうに受けとめているのか、最後に伺います。","respondent":"大澤保育支援課長","answer":"１歳児は１対５、３歳児は１対１５で基準をつくって運営しております。定員分の保育士を配置しておりますので、私は私立園をかなり回っていますけれども、特にものすごくきついというような声は聞いておりません。","id":"exchange-067"},{"speaker":"つる委員","kind":"質問・要望","question":"現場の声、現場の声を伺って、それをしかるべきところに届けていくといったことも大事なのかなとちょっと感想的に思いました。６万６,０００円と、昨年は７万４,０００円が平均ですというご答弁があったのですが、ちょっとその数字だけ確認させてほしいと求めました。","respondent":"大澤保育支援課長","answer":"平成２７年度に３万８,０００円、平成２８年度に３万９,０００円上がっているというのは、平成２４年度が基準になっています。６万６,０００円の見込みですけれども、まだ平成２９年度の集計が終わっていませんので、結果として幾らになるかについては今集計中です。","id":"exchange-068"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう機会があるかどうかはあれですけれども、こうした質疑の中でもそれがわかった段階でまたある程度教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"石田（し）委員","kind":"質問","question":"都レベル、国レベルで必要ですというような声を届けるというのは、どこかのタイミングでやられているのでしょうか。これはいわゆる二つ目の配置基準のところも含めてですが、どのように都と国と話をされているのか、説明を求めました。","respondent":"大澤保育支援課長","answer":"都で待機児童対策協議会等がありますので、そういう場面で意見として出していくことはしております。特に処遇改善IIの研修については、必須だとなかなか難しいということで、それは各自治体から出た意見をもとに平成３４年まで延長されたです。","id":"exchange-070"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そういった部分では積極的に現場の声も含めて届けていただきたいなというふうに思います。さまざまな加算、保育士のいわゆる離職というのがどういうような傾向に来ていて、今後どのようになる見通しを区が持っているのか説明を求めました。","respondent":"大澤保育支援課長","answer":"離職率としては全体的に、下がってきているかなという感触は持っています。園を変わるという意味では、少しこれからの競争の中で、もしかすると高くなってくる可能性があるのではないかというふうに考えています。","id":"exchange-071"},{"speaker":"渡部委員","kind":"質問・要望","question":"もしくは保育士の方々の労働改善といいましょうか、そういう形であたられていて、最後の質問はまさにそうだと思うのです。賃金等に関しても上がってきておりますし、制度に対しましてもそれぞれ国基準プラスアルファをなされているわけですから、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"つる委員","kind":"質問・要望","question":"ほかの委員からの質疑も確認させていただいて、事業者のほうから、逆に保育士からも処遇を改善してほしいという声もありました。保育行政を都道府県を挙げてやっていただきたい部分ではある中で、そういうジレンマを抱えた部分があるのかなというところはあるかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問・要望","question":"認可外を含む私立保育所職員に対する品川区独自の処遇改善を求める陳情ということで、今日の説明からすると、報道で取り上げられたり。保育をしてくださっている職員の方々に対する処遇改善というものを区がしっかりとつかみ、改善をするための努力が求められていると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"区でできることはもちろん全力で取り組んでいただきたいのですが、全体でさらに改善ができるように、その辺はお願いしたいなというふうに思います。今回のこの陳情に関しては、不採択ということで結論を出させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"区独自の加配や先ほどの看護師のお話ですが、その点についても常に検証して、今後に向けて努力は続けていってほしいと求めました。現状の対応については、そういった点では現状の仕組みで区のほうは努力をされているということですので、不採択ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"}]},{"id":"topic-07","title":"平成３０年陳情第１９号、「（仮称）空のはねこども園はたのだい」（旗の台２丁目）の事業者指導等を求める陳情","agenda":"平成３０年陳情第１９号、「（仮称）空のはねこども園はたのだい」（旗の台２丁目）の事業者指導等を求める陳情","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それで、私道についての説明は今の中ではなかったのですけれども、改めて区がどういうふうに認識しているのか、これを伺いたいと思います。どういうふうに区として説明をしてこられたのか、それについてどうなっているのかを１点、とりわけ伺っておきたいと思います。","respondent":"大澤保育支援課長","answer":"私道に関しましては、これまで承諾書の取得に努めるように事業者に依頼してまいりました。私道の持ち主に文書で許可を得る必要があるというふうに明記して説明をしているところです。","id":"exchange-077"},{"speaker":"南委員","kind":"質問","question":"そういう点で説明もしていると、事業者はそれについてどのような対応をこの間にしてきているのか。それについて説明を求めました。","respondent":"大澤保育支援課長","answer":"事業者としては近隣を回って承諾を得るように努力をして、現在のところ、最低限必要な範囲については承諾を得ております。それ以外の部分についても承諾を得るよう区としては依頼しておりますので、事業者のほうは今努力をしているというふうに報告を受けております。","id":"exchange-078"},{"speaker":"南委員","kind":"質問","question":"この点、こういう形で似たような地形のところに開設された保育所があるのかどうかを聞いたのですけれども、その点についてはどうだったでしょうか。答弁がなかったと思うので伺っておきたいと思います。","respondent":"大澤保育支援課長","answer":"その片方が私道でございまして、そちらに公園から５ｍに満たないぐらい私道を通って保育園の出入口があるというような設計になっています。私道を避難経路として設定している園はほかにもございまして、そのときにも承諾書をとっていただいています。","id":"exchange-079"},{"speaker":"南委員","kind":"質問","question":"私が先ほど説明したようなこういう地形、隣がこうなっているという、そういうところで、同じような状況で保育園をつくっているところがあるという認識でいいのか尋ねました。","respondent":"大澤保育支援課長","answer":"同じようなというのは、公園があって、私道があってという意味ではございません。避難経路として私道を使用しているところはあります。","id":"exchange-080"},{"speaker":"南委員","kind":"質問・要望","question":"５０人以下を要望するというふうにここに書いてあるわけですけれども、そういう声について区としてはどういうふうに受けとめているのか。そしてきちんとしたいろいろな条件が備わっている、そういう点で区の見解はどうなのか、改めてそこは伺っておきたいと思います。","respondent":"大澤保育支援課長","answer":"一方で、認可保育所の定員は６０名を基本としておりますので、事業者に対してこれ以上の定員削減を申請することは今の時点では考えておりません。ただし、地域のご要望を鑑みまして、保育事業者からさらなる定員削減の申し出がありました場合は、提案を受け入れる準備はあります。","id":"exchange-081"},{"speaker":"南委員","kind":"質問・要望","question":"課長はこういう平面図をご覧になってどのように考えているのか、そこは教えていただきたいと思っています。６０名としている、その根拠というのはどういうことなのか、改めて伺いたいです。","respondent":"大澤保育支援課長","answer":"認可基準に則していれば、特にこの園がほかと比べて著しく劣っている配置図になっているというふうには認識してございません。先ほども申し上げましたように地域要望がありますので、事業者のほうから６０名以下にしたいという申し出があれば、それは受ける準備はあります。","id":"exchange-082"},{"speaker":"南委員","kind":"質問・要望","question":"ご要望というのを勘案して事業運営をしていくということが一定程度の期間、きちんと区のほうからも一定の指導をする必要があると思います。最後にそこだけ伺って、とりあえずこの関係での質問は、今は終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"南委員","kind":"質問","question":"ですから、それぞれ出入りをするときに、それぞれの保育室を通っていかないといけない。そういう配置でいいのかということを聞きながら、保育室が基準に合うとは、言えないのではないのかということを言いたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点で何回も繰り返しこの問題について質問をしているわけですが、そういう立場で指導をしていただきたいと考えています。答弁が同じであれば、それはそれでいいですけども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"飯沼委員","kind":"質問・要望","question":"こうやって地域の住民の方と保育事業者のトラブルといったらいいのですかね、やはり最初の段階でどうして手が打てなかったのか。その点をお伺いします。","respondent":"大澤保育支援課長","answer":"区はとめられなかったのかというご質問につきましては、子ども・子育て支援制度上、とめられません。基本的な要件を満たしている限り提案を受け付けなければいけないということになっておりますので、それが全ての答えになります。","id":"exchange-086"},{"speaker":"飯沼委員","kind":"質問・要望","question":"相談に来てくださいというようなきちんとした基準とか要項がない品川区にとっては、そこをやはり補充してつくっていくべきであると思っています。あくまでも民と民の問題だというよりも、品川区の責任であると重く受けとめていただきたいのですが、いかがか尋ねました。","respondent":"大澤保育支援課長","answer":"保育所整備に関しましては、品川区においてもきちんと責任を持って住民に説明してくださいということは書面をもって、また対面でご説明をしているところです。","id":"exchange-087"},{"speaker":"飯沼委員","kind":"質問・要望","question":"こういったことで、住民が知らない間にどんどん進んでいる、これってないのではないでしょうか。私はとんでもないことだと思うのですが、事業者参入のときの手続の手順と区がどうかかわってきたのか、今の部分を説明を求めました。","respondent":"大澤保育支援課長","answer":"時系列で申し上げますと、９月の頭には保育園の開設について町会長のほうに事業者からお話をしています。１１月になってから具体的に説明会開催について周知をしたところです。","id":"exchange-088"},{"speaker":"飯沼委員","kind":"質問","question":"私が時系列的に言ったあたりで、住民の方が知らない間に区から都にいろいろ申請とか協議書が提出されているという問題は、事実と違うと思うのですが、この件に関してはどうか尋ねました。","respondent":"大澤保育支援課長","answer":"９月に建設のお知らせについては投函していますので、時期としてずれてはいないというふうに認識しています。","id":"exchange-089"},{"speaker":"飯沼委員","kind":"質問","question":"本来だったらスムーズに行くところも行かないのは当たり前ではないでしょうかね。課長、ちょっとここのところ、事実をきちんと把握しているのかどうか、これは住民の方が怒るのは当然だと私は思うのですけれども、いかがか尋ねました。","respondent":"大澤保育支援課長","answer":"説明会と意見交換会については、それぞれ４回、３回と実施しておりますので、特に事実に反しているというふうに認識してはございません。","id":"exchange-090"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この４回の説明会というのは、１月に入って行われた部分で、住民説明会前の区の手続なのですよ。私はこれを課長に認めていただきたいと思うのですが、いかがか尋ねました。","respondent":"大澤保育支援課長","answer":"説明会をする予定も含まれているはずなので、きちんと説明会をするという報告を受けて、説明会を実際にしていますので。","id":"exchange-091"},{"speaker":"飯沼委員","kind":"質問","question":"説明会を予定しています、これでルールに則っているからいいのですといって進められていること自体に問題があるのではないですかと言っているのです。私が言っていること、おかしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"飯沼委員","kind":"質問・要望","question":"両者のことを一番よく知っているのは区ではないですか。住民への対応のあり方、あと事業者の要件なども明記してほしいというところがありますので、いかがか尋ねました。","respondent":"大澤保育支援課長","answer":"もちろん事業者に対しては電話やメールだけではなく、私自身も１０月までの間に６回にわたり事業者の代表と会って検討を依頼しているところですので。","id":"exchange-093"},{"speaker":"飯沼委員","kind":"質問","question":"やはりこういうところをしっかりとお約束をしていただくことで住民の方がこれから本当に一緒にやっていくという立場に立てるのだと思うのですね。その辺はいかがか尋ねました。","respondent":"大澤保育支援課長","answer":"繰り返しになりますが、要望については、今までも事業者に検討を促してまいりましたし、今後もそれは続けてまいります。","id":"exchange-094"},{"speaker":"飯沼委員","kind":"質問・要望","question":"よその優れた部分は品川区の要項にも取り入れてほしいということに対してぜひお答えをしていただきたいのと、あと最後に定員のことなのですけれども。人数についてもしっかりと話し合いをして、いい方法を編み出していただきたいなと思いますが、２点。","respondent":"大澤保育支援課長","answer":"あくまで集団保育についての重要性を考えてきましたので、近隣要望を鑑みて、今回は定員を下げるという提案があれば受け入れる準備はあります。ただ、４年たつとそうなってきますので、よりよい認可の基準をつくっていきたいということで準備にかかろうとしています。","id":"exchange-095"},{"speaker":"渡部委員","kind":"確認","question":"何か基準が満たされていなかったりというのがあったわけではないということでよいのかという確認を一つと、私道がというのがありました。通園に支障がないという確認をとれていれば、クリアされていない大きな問題というのは見えないのですけれども、何なのか尋ねました。","respondent":"大澤保育支援課長","answer":"休日保育については、事業者のほうが実施せずに開設するというふうに言っています。それは町会長からも、事業者から相談を受けている旨聞いておりますので、最終的には今定員のところかなというふうに私は認識しています。","id":"exchange-096"},{"speaker":"渡部委員","kind":"質問","question":"しっかりと助言をいただいてということはなさっているわけですから、保育園に限らず何だってそうなのかなというふうに感じているのです。答弁は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"一定の住民の方からのご要望というのは運営事業者ものんできたのかなというのが今までの質疑等も含めての流れなのかなというふうに理解をしています。要はそのエリアだから保育園ができるのはどうなのかというようなことが質疑の中であったので、そこをまず確認させてください。","respondent":"大澤保育支援課長","answer":"すぐ近くに認証保育所がありますけれども、今入園をご希望される方も多いので、特にそこで問題が起きるとは思っておりません。隣でつくったりというようなケースもあり、それでも入園の方はいらっしゃいますので、特にそこで問題があるというふうには認識しておりません。","id":"exchange-098"},{"speaker":"石田（し）委員","kind":"確認","question":"これができて問題があるというのではなく、そのエリアにいわゆる保育園ができるのは好ましくないというような質疑があったと思うのです。なので、今までこの地域にあるから問題だというのがあったのかどうかというのを確認したいので、そこを改めて、答えるよう求めました。","respondent":"大澤保育支援課長","answer":"地域的には何も問題ございません。","id":"exchange-099"},{"speaker":"石田（し）委員","kind":"意見","question":"どうしてもそうせざるを得ない部分というのもあるのでしょうし、区としてできる限りそれを今回はやってきていたのかなというように感じています。これは意見ですが、我々としてはそういう認識でおりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-100"},{"speaker":"渡部委員","kind":"意見","question":"結論を出して、態度については不採択です。事業者と住民の方々でさまざま、まだこれから少しお話し合いがあるのかなと思うのですが、区としては十分やるべきことはやっていると思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-101"},{"speaker":"つる委員","kind":"質問・要望","question":"質疑も伺いました。石田しんご委員から確認があって、子どもの発達にとって非常にセンシティブで影響が大きいのかなというのを私自身は懸念しています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"南委員","kind":"質問","question":"保育する責任があるのは区ですから、やはり今後基準などもつくって、責任を果たしていくということが大事であると思っています。ですから、この陳情に対しては採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"地域の方たちの声を聞いていただき、できる限りいわゆる間に入って調整というのは引き続きしていただきたいというのはありますので、ここは見します。態度としては不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今多くの議論を伺って、またこの陳情を出された方々のお考えも読ませていただきました。事業者のほうとつないで説明をしている、あるいは住民の方のお話をつないでいるなど対応していて、今後も要望をつないでいくというお話もありました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"}]},{"id":"topic-08","title":"本定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、文教委員会にかかわる項目","agenda":"本定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、文教委員会にかかわる項目","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"５年という存続を見据えて考えていて、その行方がどういうことなのか、もう少しお伺いしたいなと思っています。６４２人が入れない、そこで今年も一応待機児童が１９人いたわけで、ゼロであると言い切ってしまっていいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/971992?Template=document&Id=4954#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":73452,"voices":295}},{"id":"h30-20181029-5","meetingId":"h30-cm10","date":"2018年10月29日","dateIso":"2018-10-29","committee":"総務委員会","time":"午前１０時００分～午後 ０時２２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件整理しています。","topics":[{"id":"topic-01","title":"平成３０年請願第１５号、固定資産税及び都市計画税の軽減措置の継続","agenda":"平成３０年請願第１５号、固定資産税及び都市計画税の軽減措置の継続","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"これに携わる方というのは、ぜひ次も軽減措置の継続を求める意見書を出してくれということなのですが、過去の総務委員会でいつも質問をしています。なかなかその辺について品川区としてお答えはできないとは思うのですが、品川区の思いはどういうものなのかお聞かせほしいと求めました。","respondent":"伊東税務課長","answer":"それと、恒久的ですけれども、この間、都に毎年このような請願が出て、都で判断して、軽減措置を継続しています。継続、場合によっては廃止など、そういうことも考えているのかなと思っているところです。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"２３区全体にも言えることですが地価は高いですし、それなりに賦課される税金も多いと思いますので、この軽減措置は必要不可欠だと思っています。ぜひ強い発信力で、品川区も東京都に対して意見書を提出してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ品川区としても東京都に対して軽減措置の継続を求めていただきたいと思うのです。小規模非住宅用地に対する減免措置、品川区としても東京都に対して求めていくことが必要ではないかと思うのですが、その点はいかがか尋ねました。","respondent":"伊東税務課長","answer":"この話は区の方にも声が届いている状況です。機会を見まして、東京都にはお話しするということを考えておりますけれども、具体的にいつの時点で、どういう形というのは言えないところです。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"伺ったのは、この３つの軽減措置の継続が必要ではないかということを東京都に伝えることが必要ではないかということですので、改めていかがか尋ねました。","respondent":"伊東税務課長","answer":"お話は伝えると申し上げましたけれども、もともと現状の制度では、東京都が賦課徴収する形になってありますので、こちらからというよりは、周りからのお話が東京都に集まった中で、東京都が判断されるのかなと考えております。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"東京都が判断することだと思いますけれども、だからこそ品川区としても、これを継続してほしいと東京都に要望を上げる必要があると思います。区としても東京都にこのことを伝えていただきたいと、強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"毎年この軽減措置の継続について意見書を求める請願が出ております。路線価が、もう倍以上になっているのではないかなと思うので本当に不思議に感じるのですが、どう思われますか。","respondent":"伊東税務課長","answer":"ただ、もともと地方税法については、国がいろいろと判断して、見直しとか対策はとられてきたところです。国もそれなりに対応すると思いますが、現状ではやはり東京都が２３区の状況というところで、東京都がそれぞれ判断すると思います。","id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"これは東京都の話なので、確かにつらいですよね。チャンスがあれば都に話しを持っていき、先ほどほかの委員からありましたけれども、恒久的な仕組みになればありがたいなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"中塚委員","kind":"意見","question":"第１５号、第１６号、ともに結論を出すということと、採択をして、都に意見書を提出すべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"いながわ委員","kind":"質問・要望","question":"恒久的なものになることがよろしいのではないかなと思いますので、ぜひそういう思いの中で、しっかり東京都に意見書を出してほしいと求めました。採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-02","title":"平成３０年陳情第１５号、正しい公文書の情報管理と開示を求める陳情","agenda":"平成３０年陳情第１５号、正しい公文書の情報管理と開示を求める陳情","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"国の公文書管理法とか、法律もあろうかと思いますので、それをお伺いしたいのです。品川区における公文書管理の正しいあり方を検討する会などの審議体または会議体があるのかどうなのかを、お聞かせほしいと求めました。","respondent":"米田総務課長","answer":"あるいは区内の行政において課題が生じたというときに、一定程度、私どもを中心に検討を行っていく必要があるのだろうと。これは常々行っていく必要があるとは思っておりますが、そういうものです。","id":"exchange-010"},{"speaker":"いながわ委員","kind":"質問","question":"最初の質問で、品川区がそれを遵守してどうこうというのでなく、独自に行っているのかということを聞きたかったのです。要は、「この法令をもとに品川区は文書管理をしていますよ」ということではないということでいいのか尋ねました。","respondent":"米田総務課長","answer":"その中で、一部の自治体では、冒頭ありましたようなリストを公表するというところまで進めているところがあろうかと思います。それを品川区においては文書取扱規程というものに落とし込みながら、あるいは手引等に落とし込みながら、事務を進めているものです。","id":"exchange-011"},{"speaker":"いながわ委員","kind":"質問・要望","question":"どうあるべきかを検討されていて報告書がネット上に出ていましたけれども、その中でどういう方向性が正しいかを、ぜひいろいろ議論していただきたい。ぜひそれは、しっかり管理をしていっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問","question":"保存の仕方と、どういう形できちんとつくっていくべきかということとか、管理のあり方というのがきちんとあったほうがいいのではないかと思いました。私自身ＩＴにすごく疎い中で質問してしまい、質問の趣旨もわかりにくいかもしれませんけれども、。","respondent":"米田総務課長","answer":"そのダメージが大きいということもありますので、その辺のところはよく考えながら、できるものから進めていく。まだ多数残っていると認識はしておりますが、そういうできるところから進めているということで、目標年次は設定できない状況かなと思ってあります。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問","question":"私自身も本当にそれでいいのかなというのは１つあるのですけれども、それから、両方あると思うのです。品川区としてはこう考えているということがあるのかどうか、それについても伺いたいのですが、いかがか尋ねました。","respondent":"米田総務課長","answer":"当然そういうものについては、意思決定が必要になるということになりますので、そういう意思決定の部分が、まず文書管理の根幹なのだろうと思います。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、どういう文書を公文書として管理していこうとしているのかということを、品川区としてどうお考えかを伺ったのです。品川区としてこういうふうに管理していこうというものがあるべきなのではないかなと思いますが、その辺についてはいかがか尋ねました。","respondent":"米田総務課長","answer":"１つ目のほうは、その必要性の中で、データをとり直したということがあるようです。あるいは部の中にもおるわけですので、もしそこの中で対応しきれないようであれば、総務部のご相談を申し上げるという形だろうと思います。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問・要望","question":"今は事故報告のあり方も少し改善していただいたと伺っていますし、８月１９日に陳情が出されていますので、陳情者の方からも伺いました。もしできましたら、今後の方向性について一言ほしいと求めましたが、いかがか尋ねました。","respondent":"米田総務課長","answer":"一定程度の説明責任、説明をきちんと行うということも、あわせて必要だったのではと思います。今までも平成１５年に導入して以来、少しずつですが進めておりますので、陳情にある内容についても研究を行っていく必要があると考えているものです。","id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"意見","question":"紙ベースのものにファイリングシステムを導入されておられると思うのですけれども、今現在から言うと、この現状で私はいいのかなと思います。ＩＴ化に取り組んでいる区からみて、本区は遅れているのか、どうなのかというところを聞きたいと思いますとの意見を述べました。","respondent":"米田総務課長","answer":"２３区ですとか都内の自治体レベルになりますと、今のところ、１０を超えるぐらいという認識をしております。実施されているわけではないと感じているところでありますが、導入することによる課題なども含め、研究を行っていく必要はあるだろうと考えています。","id":"exchange-017"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"本区においては、こういった公文書の管理を求める声というのは、決して私は本区の多くの区民がそれを望んでいるのではないと思うのです。ですから、そういった要望、区民が情報を公開してくれというのは、区に寄せられているのかどうかということをお聞きしたいと思います。","respondent":"米田総務課長","answer":"今のところ、陳情の内容にあるような趣旨での声というものが聞こえてくるということではないと考えています。むしろ、お聞きするケースはほとんどないかということではありますが、その中でも、他自治体の動向等は見きわめる必要があると思います。","id":"exchange-018"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひほかの区の動向を見きわめながら、区としても研究をいろいろしていただきたい。これは要望であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"事実の確認として、なぜ区民に異なるものが示されたのか、その原因と対策についてお聞きします。いずれにしても、しっかりとした文書管理システムを構築していくことが急がれていると思いますけれども、あわせて伺いたいと思います。","respondent":"米田総務課長","answer":"それから、一定程度適切な範疇であるという認識がありながらも、いま一度確認をとるという中での体制を構築していると所属から聞いているものです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう意味で公文書の取り扱いに関する各所管への指示や研修や対応というのは、総務課が所管しているのか、確認させてほしいと求めました。そこが今後の課題ではないのかなと思うのですけれども、その点、いかがか尋ねました。","respondent":"米田総務課長","answer":"及びこれを実施するよう努めなければならないということがございまして、自治体もこの趣旨にのっとってということは十分把握しております。その中で、先ほど来申し述べている文書事務の改善だったり、一定のＩＴ化というものについても考えながら、進めていくものです。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"この高い志の中で文書管理を行っていく、そうした意識をそれぞれの課に根付かせていく責任が、総務課には求められていると思うのです。具体的に研修やシステムの構築など、何を進めていくのか、伺いたいと思います。","respondent":"米田総務課長","answer":"文書事務を学びたい者向けの研修であったりということを実施して、文書の取り扱い方、そういう研修だったり事務の手引等で伝えているつもりです。この辺については今後も深めていきたいと考えております。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的には言いませんけれども、そういう意味では、今、体系的にできているとは言い難いと指摘をさせてほしいと求めました。ぜひ改善をしていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですから、今、一歩一歩徐々に公文書管理、情報開示を進めていると思いますが、私は徐々に、慎重にやってほしいと求めました。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今回の陳情の趣旨からいいますと、区としてもオープンデータ化などをしていますし、現在これで私は十分だと思っています。これから先はＩＴ化を加速というか、調査研究をしていただいて、前向きに検討していただきたいということで、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"みなさんのやりとりを伺わせていただいて、現状と、また今後の対応ということも確認をさせていただきました。今後また区民の方が情報公開される文書を求められた場合には、それから開示期間もまたご検討いただきたいということをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"中塚委員","kind":"意見","question":"本日結論を出すということと、私は採択でお願いしたいと思います。このことは、区政の発展のためにも、とても大事な指摘だと思いますので、採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"いながわ委員","kind":"質問・要望","question":"では、こういう１つのご指摘ということで受けとめるのであれば、そういうことをしっかりやるべきではないかなというのがあります。しかしながら、ＩＴ化をするとかそういうのは、先ほどもありましたけれども、時期尚早ということで、不採択にさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"須貝委員","kind":"質問・要望","question":"区も少しずつ、こういうご意見に対して少しでも近づけるように、私はやってほしいと求めました。今回に関しては、本日結論を出すということと、私はこの件に関して、今回の陳情には不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"先ほども質問させていただきましたけれども、一言。そうすると、少なくともＩＴ化はその業務をやりやすくする１つの手段であると考えますと、私は採択をすべきと主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-03","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"ただ、それは、なかなかその場で、どう判断するか難しいと思います。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"いながわ委員","kind":"意見","question":"品川区役所の施設整備課が所有している自動二輪車、原動機付自転車ではなく、自動二輪車を所有しているのかどうなのか。そういうのは全くないのかどうなのかだけを、詳しくではなくていいので、お願いしますとの意見を述べました。","respondent":"小林施設整備課長","answer":"自動二輪につきましては、おっしゃるとおり自動二輪車でございまして、施設整備課が所有しているものです。全額保険にて出捐していますが、自動二輪車については区施設営繕事務費で処理しております。","id":"exchange-032"},{"speaker":"いながわ委員","kind":"質問・要望","question":"最近、専決処分として、こういった事故の報告が多く見受けられるので、別に施設整備課というよりは、品川区全体で交通事故がないようにお願いしたい。これは１つの課がどうこうではなく、その辺はしっかり指導していくべきではないかなと思いますので、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]},{"id":"topic-04","title":"品川区総合庁舎に設置されている免震オイルダンパー","agenda":"品川区総合庁舎に設置されている免震オイルダンパー","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"そういう思いの中でこの装置を設置しているわけですから。なぜこういうことが実際に起きたかというのは、本当に行政を欺いて商品を納品してきたわけですから、許されないことではないのかなと思うのです。","respondent":"立木経理課長","answer":"行政としての、例えば業者の指名停止であるとかという行政処分などの何らかの対応というのは、行政として検討していくべきだろうと考えております。今後の対応としては、一応、データ改ざんがあった製品につきましては、全数交換という方針が同社から出ております。","id":"exchange-034"},{"speaker":"いながわ委員","kind":"質問・要望","question":"そうなると、今度は地面と庁舎をつないでいるアンカーがあるわけではないですか。という話もあったのではないですかということも地域から聞くので、そういうのを払拭するためのことをやってほしいと求めました。","respondent":"立木経理課長","answer":"製品出荷前に製品のばらつきを検査する工程で、数値上のデータの変更だけで出荷してしまったという、完全に製品そのものに対してのデータ改ざんです。","id":"exchange-035"},{"speaker":"いながわ委員","kind":"質問","question":"免震オイルダンパーに負荷がかかるということは、アンカーの部分が４カ所でとまっていましたけれども、そこにも当然負荷がかかるわけではないですか。そっちは全然かえなくて大丈夫ということでいいのか尋ねました。","respondent":"立木経理課長","answer":"もともと私どもの設計会社で当初見込んでいた性能の品物が入ることによって、報道の資料から推察するとなっています。どれくらいデータに乖離が、誤差が出ているのかというのを含めて、再度構造計算をしないといけないという状況にはなっていると思います。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"日常的には区民の生活を支え、災害時には防災の拠点となる、その庁舎に設置した免震オイルダンパーのデータが不正に改ざんされた。もっと強い態度で対応していく必要があるだろうし、私は看過できない抗議すべき事案だと思うのですけれども、そこはいかがか尋ねました。","respondent":"立木経理課長","answer":"そこの部分は今後、業者に対応をきちんと求めていくという姿勢は変わっておりませんので、そういった姿勢で臨んでいく所存です。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"そういうことをしっかりと態度表明するべき事案だと思うのです。本会議の質問に対する答弁の中で、許されないという態度表明が必要ではないかと思うのですけれども、改めていかがか尋ねました。","respondent":"立木経理課長","answer":"委員おっしゃられるとおり、本当に許されることではないと考えておりますので、抗議の部分に関しましては、また内部で検討させていただきたいと思います。","id":"exchange-038"},{"speaker":"須貝委員","kind":"質問","question":"オイルでシリンダーが動くわけですから、できると言ってつくった以上、私はますます信じられないのかなと思います。あの場所で修理できるのですかというのが逆に疑問で、一旦オイルを全部抜いて、中のシリンダーを全部外してやるのかもしれない。","respondent":"小林施設整備課長","answer":"施工につきましては、４カ所のうち、本当に１カ所なのか、その１カ所がどこなのか、それによって施工方法が変わってくると思うのです。今後その改ざんがあったというところがどこなのか、それによって元請業者と打ち合わせをして、早期に取りかえを行いたいと考えております。","id":"exchange-039"},{"speaker":"須貝委員","kind":"質問・要望","question":"施設整備課においても、品川区全体においても、まさか寝耳に水で、こんなことは考えられない状況です。本当にそれだけ多くの区民の方が心配されていると思いますので、できるだけ早期にいい方向に向かうように努力してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"全国で１,０００件あって、製品が１万個ある中で、早急に施工会社と設計会社と協議しながらやっていただきたいということがあります。まだ回答は出ていないと思うのですけれども、改めてもう一回、今後の予定等を知らせてほしいと求めました。","respondent":"立木経理課長","answer":"既に設計会社、施工会社とも打ち合わせを始めております。そういった中で、できるだけ早期に交換の方向でいけるように調整を進めてまいりたいと思います。","id":"exchange-041"},{"speaker":"吉田委員","kind":"質問","question":"今まで皆さんのご質問を伺っていて、契約関係でいうと、区は直接ではないから、直接の損害賠償が難しいということなのですか。その辺の契約関係がどうなっているのか、説明を求めました。","respondent":"立木経理課長","answer":"こちらの工事に関しましては、区の起工書をもとに、その工事を行ってもらうということで、その中で使う製品というものも決まってきております。それをＫＹＢ社から納品を受けて設置するというのは、４社での話になると思いますので、やっていきたいと考えています。","id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういうことかと思いますが、一応、もともとの性能を満たすものを品川区として施工業者に求めていたわけですよね。その辺のことも含めて、それから安全性の検証等というのは、どこに対して、どういうふうにやっていくことを求めているのか、あわせて説明を求めました。","respondent":"小林施設整備課長","answer":"現在、この４基の免震オイルダンパーにつきましては、経理課からＫＹＢ社に対して確認中です。どういうふうに施工するのか、それは早期にわかり次第、検討に入りたいと思います。","id":"exchange-043"},{"speaker":"吉田委員","kind":"質問・要望","question":"客観性を担保するため、まるきり違う第三者によって確認した上で、厳しく追及していただきたいなと思います。これについては要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"}]},{"id":"topic-05","title":"今定例会の一般質問に係る所管質問でありますが、今定例会の一般質問中、総務委員会にかかわる項目","agenda":"今定例会の一般質問に係る所管質問でありますが、今定例会の一般質問中、総務委員会にかかわる項目","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"項目の正式名称を忘れてしまったのですけれども、藤原議員が質問なさった、さきほどの陳情にもかかわることで、公文書についてです。ご答弁がなかったように認識しているのですけれども、その辺について改めて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/147246?Template=document&Id=2120#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":33547,"voices":114}},{"id":"h30-20181030-6","meetingId":"h30-cm10","date":"2018年10月30日","dateIso":"2018-10-30","committee":"区民委員会","time":"午前１０時００分～午後 １時５４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"特定非営利活動法人日本移植支援協会「細谷恵介くん基金」からの寄附","agenda":"特定非営利活動法人日本移植支援協会「細谷恵介くん基金」からの寄附","exchanges":[{"speaker":"田中委員","kind":"質問","question":"この文化スポーツ振興基金の中に、それとも新たにわかるように、文化スポーツ振興基金の中の「細谷恵介くん基金」という名目が残るのかということ。寄附者の思いが伝わる使われ方で、表面にわかるように使われるのかということを聞きたいのですけれども、いかがか尋ねました。","respondent":"池田スポーツ推進課長","answer":"今回は「細谷恵介くん基金」からの寄附ということになりまして、基金の中に入るということになってあります。こちらの基金の１,０００万円を活用した事業につきましては、「細谷恵介くん基金」からの基金を利用してということでＰＲをするつもりでおります。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、ご説明にあったとおり、基金に積み立てていくというお話でしたけれども、その後にどう活用していこうという考えがあれば、教えてほしいと求めました。","respondent":"池田スポーツ推進課長","answer":"私どもで今の時点で考えることでは、例えば、もしくは障害者スポーツの普及支援の教室に冠をつけるなどといったことを考えているところではあります。まだ具体的なところにつきましては、決まったものはありませんが、今後考えていきたいと考えているところであります。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ本人の意向が活かされるような形で使ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"この報告書を読み取ると、まずは候補者を決めて、人材育成をして、支援としては資金調達が求められていると感じました。区の報告書と現在の分析と課題を伺います。","respondent":"山崎商業・ものづくり課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"この後継者塾は複数回受けることはできるのでしょうか。１回受けて、全てを完全に身につけるということも難しいのかなと思うのですが、伺います。","respondent":"山崎商業・ものづくり課長","answer":"過去にカリキュラムを実施して、再度というニーズがあれば、それはいろいろ柔軟に考えていきたいなと思っています。今年は弟さんが受けられたという事例もありますので、さまざまなニーズに応じて柔軟に対応していこうと考えています。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"事業承継にも多少かかわってまいりますけれども、この間、共産党としては、店舗のリフォーム助成というものを求めております。この事業承継も含めて、リフォーム助成が全体的にも必要だと思いますけれども、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"今日、ご説明申し上げました平成３０年度の(5)に、事業承継設備投資助成というものがあります。ただ、個人の会社なり、店舗のリフォーム助成も対象にしているということでスタートを切っているところです。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"インボイスも含めた消費税増税の問題について、区の見解を伺います。今回、区長選挙で区長が公契約条例を検討すると言われておりましたけれども、現在の状況を伺います。","respondent":"山崎商業・ものづくり課長","answer":"こうしたさまざまな対策をもって、消費税関連については、区としても適正に対応してまいりたいと考えるところです。そうした区全体としての検討の流れの中に、さまざまな中小企業のお声などを届けることに努めてまいりたいと考えています。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"公契約条例については、産業部門としてはどういったことを伝えているのか伺いたいと思います。反対、中止の態度を示していくということも必要かと思いますが、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"そうした行政としての公正な中の効率的な契約方法の検討の中で、私どもの部門としましては、区内産業の活性化ということで仕事をしております。工夫ができる部分があればお願いしたいという立ち位置で検討のほうには参加させていただけたらなと思っているところです。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"この報告書から見ますと、後継者塾や融資あっ旋を求められているところで、対応されているなという認識は持っております。さらにこれが進むように、区内経済を活性化させるということで取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"おくの委員","kind":"質問","question":"関連して、この事業承継セミナーや後継者塾。訪問相談を受けられた方の感想を伺っていらっしゃれば、どういうものが挙がっておられるかお聞きできればと思います。","respondent":"山崎商業・ものづくり課長","answer":"今まで自分が会社の経営者として基本的に考えるべきことが広がった、あるいは、ふだん感じない領域での考えの幅が広がったということ。区がこの事業を行っているという信頼と重ね合わせて、受けていただいた方は、非常に好意的なご意見がほぼほぼ多数を占めているという状況です。","id":"exchange-010"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、言ってみれば、ワンストップ的な窓口の役割を果たし始めているというイメージ、理解でよろしいのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"継ぐ人もなかなかいないので、Ｍ＆Ａの手法などの場合は、そうした専門のルートに回すという交通整理の役割のほうがイメージとしては近いかなと考えています。","id":"exchange-011"},{"speaker":"おくの委員","kind":"質問・要望","question":"確かにワンストップで済むような単純な問題ではないですよね。求められていることだと思いますので、できるだけ多くの方に知らせて、充実したものにしていってほしいとは思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"大倉委員","kind":"質問・要望","question":"少し教えていただきたいのですが、どのくらい行かれているのかなというのがわかれば教えていただきたい。今この中でされているのかというところを説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"委員がおっしゃられたようなマッチングが区内企業者同士や区内企業の健全な継続を担保するために成立できたらすばらしいなと思うところではあります。先々、委員がおっしゃったような、情報が整理された上でのマッチングができればいいなと思っているところです。","id":"exchange-013"},{"speaker":"大倉委員","kind":"質問","question":"その辺も、区外の業者との承継の方法や手法というのは、この事業承継センター株式会社が持っている情報でやっていくということなのでしょうか。廃業のほうも、数で言うとどのくらいあったのかなというのを説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"もともと中小企業支援は製造業の登録事業所がメインですけれども、データベースを持っています。区のさまざまな助成金で新技術開発支援を行ったなど、しっかり整理させていただいて、将来的にはそういう方向を目指したいと思っているところです。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問・要望","question":"アピール不足であったり、これだけ手厚い施策があるにもかかわらず、これを求めている方のニーズの問題も出てくると思うのです。その辺について、分析と今後の課題をどのようにしていくのか教えていただけますか。","respondent":"山崎商業・ものづくり課長","answer":"１万８,０００事業所の中で、このところを中心に事業承継支援事業については、当面フォーカスを合わせていくということで考えているところです。そういう関係を構築しながら、しっかりやってまいりたいなと思うところです。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問・要望","question":"ああいう資金と並行して借りられるのかというあたりについて、特に括弧書きにも何も書いていないけれども、信用保証協会が出ていないではないですか。やはり信用保証協会ですよねという思いがあるので、オーケーを出さなければ融資されないわけですから、その辺についてはいかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"事業承継支援資金につきましては、事業承継にかかる各企業の計画書などをつくっていただくことが前提で、この融資の適用になります。そういうこともありますので、区では直接、事業承継設備投資ということで、補助の支援メニューもあわせてつくっているです。","id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"そこもちゃんと考えていって、どうせここまで手厚くやっていくのだったら、その辺のことも考えていかないといけないと思う。行政としての限界はあるのですけれども、最後にその辺についてはいかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"そうした意味では、必ずしも信用保証協会の保証がなくても融資を実行していただいている連絡協議会の信用金庫も現実にはあります。地域経済を盛り上げる一員としての役割が、この事業をスタートする前よりは着実に協力をいただいて増えているのは事実です。","id":"exchange-017"},{"speaker":"浅野副委員長","kind":"質問","question":"経営者に育てていくというのは１つの大きな目標と伺っておりますけれども、後継者世代の仲間づくりのようなことも進めていくということなのです。これは、実際に今どのような形で実績として上がっているのか教えてほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"それで、今年の１月に昨年度分が修了した後に、後継者ですから、一定程度３０代、４０代の方が主です。こうしたことを今年度、さらなる次世代のたくましい経営者が品川区の中で１人でも多く育っていっていただくことを目指したいなと思うところです。","id":"exchange-018"},{"speaker":"浅野副委員長","kind":"意見","question":"長く連携をとりながら、品川区の発展に寄与できるような人材を育ててほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/374422?Template=document&Id=2824#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":20412,"voices":59}},{"id":"h30-20181030-7","meetingId":"h30-cm10","date":"2018年10月30日","dateIso":"2018-10-30","committee":"厚生委員会","time":"午後１０時００分～午後 ３時１４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件整理しています。","topics":[{"id":"topic-01","title":"平成２９年度指定管理者の管理に対するモニタリング評価の結果","agenda":"平成２９年度指定管理者の管理に対するモニタリング評価の結果","exchanges":[{"speaker":"石田（ち）委員","kind":"提案","question":"事業計画書で提案した事業等の実施状況というのが書かれていますし、事務費、人件費はこれだけなのかというのもすごくわかりやすく出ていました。私たちもさらに見やすく、そしてどういう事業がされているのかというのが大もとからわかってくると思いますので、いかがか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"それは検討を引き続きしていきたいとは思っておりますが、まず、いろいろな経過を経てこの形で今おさまっているというのがあります。それはおそらくこの委員会で説明する時間的な問題、ボリューム的な問題等がまずひとつにあろうと思います。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"薬の事故何件という形で、どのような事故があったのかということでまた質問が細かくなっていってしまうので、これは１つこの総括シートへの要望です。やはりあざができてくるというお話も私たちは聞いたりもしているので、そういった虐待という面からどうなっているのかを伺いたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"虐待を担当している支援係というのがありますので、きちんと対応しているということで、日々行われているです。これはたとえの例なのですけれども、例えば薬の飲み忘れが１個残っていたということについては、その施設内できちんと対応したということで済ませて。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"私たちも質問はしますけれども、しなくてもわかるような形にしてもらうと、事業者としてもスムーズだろうなと思いました。ちょっとお話を伺いに行ったときに、今の職員体制と離職率というのが出ていたらわかるのですけれども、どうなっているのかお聞きしたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"ただ１年以上たちまして、記載されているとおり、今安定しているというのはそういうことを指しております。離職率の考え方なのですけれども、例えば有資格者も含めてどのぐらいいるかというあたりを中心に、我々のほうもしっかりチェックをしています。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはり別の事業所で内容も違うわけですから、あと、ここは世話人を再委託していたということで大変な問題になったかと思うのです。それが全くここには記載がないですけれども、その後どうなっているのか伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"１点目、どのような表記がわかりやすいか等々、今後検討をしていきたいと考えています。区としては解消すべくきちんと指導をしておりまして、今年度中には解消するというような回答をいただいております。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"最後に、４５ページの高齢者住宅、ここで先ほど課長からも説明があったのですけれども、どこの高齢者住宅も改善したいところに老朽化を挙げています。区の施設が老朽化をしてきているのですけれども、区としてはどのようにお考えなのか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"高齢者住宅は一様にやはり老朽化が進んでおりまして、こちらの対応というのが全ての高齢者住宅についても課題と捉えております。区全体の改修計画の考え方とも整合性をとり、そして居住者の方に迷惑とならないように、計画的に進めていきたいと考えています。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり老朽化というのをどうにかしたいという思いでいると思いますので、そこは丁寧にやってほしいと求めました。それと、これも全部の高齢者住宅が言っているのですけれども、被害というのは高齢者住宅で出てしまっているのか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"ただ、こちらはちゃんと管理業務を法人にお願いをしておりまして、その辺の問題意識というのはいつも法人側とは共有をしています。ですので、これからも、例えばハード的に防犯カメラ等設置できないかといったこともあわせて検討していきたいと考えています。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"意見","question":"やはり高齢者を狙った犯罪というのが本当に後を絶たないと思っていますので、また手口もいろいろ多様化しているので、こうした高齢者住宅と銘打っているとやはり高齢者が集まっているところとなってくるので、そこの住民への対策等々はさらにやっていただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"確認","question":"全体的な確認なのですけれども、それが平成２９年度でも同じものが出ているというのはあるものなのかというのをちょっと確認します。先ほどお話の中で、その中でやはりまだ改善がされていなかったときにどういう指摘をしているのか、その辺のチェック体制を確認させてください。","respondent":"寺嶋高齢者福祉課長","answer":"例えば１つとしては、あり方の検討とか効果的な策の取り組みということを一緒に考え、区も一緒になって改善に向けて支援しています。もちろんご家族にその拘束のこともちゃんとご説明した上で、それについては翌年度もやはり挙がってくることになります。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その後区としてそことの折衝、このモニタリングが終わった後に現状どうなっているのか、その辺のチェックは普段とられているのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"細かく言うと２名のうち１名が産休に入ってしまったという個別の事情がありまして、その後の補充はきちんと対応できていると。今回のシートに関してはそういう状況でありますが、ご質問の趣旨に関しては、きちんと区のほうは中間も確認をしております。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"どこもうまく区と連携をとって運営ができるように、またこれからもよろしく。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"こんの委員","kind":"質問・要望","question":"必要だ、こういうシートが上がってくる前に改善を求めたり要望したりということが日常行われているのか、そこら辺の状況はどのような状態でしょうか。それぞれ指定管理者との関係があると思うのですけれども、どうか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"できないのご説明を含めて、やはりちょっと話し合ってみてくださいといった対応をすることは、毎月のようには来ております。事業所連絡会等を使って、こういった事例があったので、ほかの施設でも情報共有してくださいというご案内を定期的に行なっております。","id":"exchange-011"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひご対応いただきながら、指定管理者と進めていただきたいと、これは要望です。管理者独自で考えてマニュアルなどをつくったりされているのか、その辺はどのような状況か尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"施設の中でさらにプラスで独自に取り組んでいただいていることはありますけれども、あと家族の方と連絡がとれる状況をうまくつくるということ等につきましては、個別に施設ごとにご案内をしていると聞いております。","id":"exchange-012"},{"speaker":"こんの委員","kind":"質問・要望","question":"高齢者施設をお伺いしましたので、先ほど自分で助けを求められるようにしようとしているということですが、お伺いしたいと思います。","respondent":"宮尾高齢者地域支援課長、松山障害者福祉課長","answer":"高齢者住宅における災害時の対応等避難に関してですが、委員おっしゃるとおり、管理人が同じ建物にいる施設といない施設とあります。災害時の対応に差があってはいけないことだと捉えておりますので、管理人が同居する… お１人だというところで、どこで、どうしてほしいのかというのを電話で言える練習を繰り返し行っているです。","id":"exchange-013"},{"speaker":"こんの委員","kind":"質問・要望","question":"結構誰にどう助けを求めていいかというのがあって、どうしたらいいかという判断が非常に難しいので、その点をもう一回確認させてください。そこら辺はされているのか尋ねました。","respondent":"宮尾高齢者地域支援課長、松山障害者福祉課長","answer":"不在の期間にもよりますけれども、必ず何らかの形で居住者の方が緊急時に連絡がつくような体制をとるようにということは、実際に求めております。区のほうに届けをしてもらって、その場合… 委員ご指摘のヘルプカードの活用の仕方も、同じように訓練に含めておりまして、その他電話は、災害用伝言ダイヤル１７１にかける練習をしているです。","id":"exchange-014"},{"speaker":"こんの委員","kind":"質問・要望","question":"この利用者への説明、また周知というのは、常日ごろ必要かなと思います。災害時の要望というのはかなり挙がっていると思いますので、その点、ぜひよろしくお願いしたいと思います。","respondent":"松山障害者福祉課長","answer":"ご利用者とご家族への説明、周知についてですけれども、区のほうにもそのお声というのは入ってきておりますし、必要なことだと認識をしております。","id":"exchange-015"},{"speaker":"こんの委員","kind":"質問・要望","question":"そこら辺の区民の方のいろいろな課題や思いや要望というところを区としても捉えていただきながら、進めていただきたいというのが要望です。待機者がかなりいる中で、稼働率がなぜ１００％いっていないのか、この数字はどのように見たらいいのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"入退所のあったときに翌日から速やかに入れるということはないので、どうしても空白期が出てしまう可能性があります。例えばそういった場合に利用率は１００を切っていくということが、一番大きな理由として挙げられます。","id":"exchange-016"},{"speaker":"こんの委員","kind":"質問","question":"区としても、ぜひそういったことで稼働率が１００％行かない理由はわかりましたけれども、その点もよろしくお願いしたいと思います。何かご答弁ありましたらお願いします。","respondent":"寺嶋高齢者福祉課長","answer":"入院前の状況をよく把握して、速やかな対応に努めるといったコメントをしていた法人もありました。ショートステイが１００％を超えてたりしているようなものは、引き続き有効に活用できるように各法人とも力を合わせていきたいと思います。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"サービスセンターの指定管理者で再委託というのはどのようなものがあるのかということを一つ教えてください。８ページのところに、やはり４番のところなのですが、胃ろうの方を受け入れてくれていてすごく助かるというお話を伺っているのです。","respondent":"寺嶋高齢者福祉課長","answer":"ここを変えたという、この４ページの一番上に「食事の改善を図るために業者を変更し」という記述があると思うのですけれども。８ページのこちらは胃ろう等医療対応なのですけれども、医療対応について必ずしも必須という形での配置は義務づけられてはいないのですけれども。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"有料利用件数というのが５４５件と書かれているのですけれども、これはミニデイということで考えてよいのでしょうか。実際にお話も伺っている部分もありましてお伺いしたいのですけれども、虐待を疑った調査というのは、そういう告発があって調査はされたのか。","respondent":"宮尾高齢者地域支援課長、寺嶋高齢者福祉課長","answer":"管理運営委託料の３,７００万円余に関してですが、こちらはやはり従事する人件費が一番大きくなってきております。そのほか、例えば小破修繕費用としての委託料ですとか… 入れ替わりも若干当初は多かったということで、対応の仕方の共有ができていなかったというのを反省点として挙げているというところがあります。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"虐待ということではなかったということで、そういう事故ももう起こさないようにという対策がとられるという判断ということでよろしいでしょうか。そこら辺の需要との関係と、送迎はどこでも行ってもらえるのかというあたりもちょっと教えていただけたらと思います。","respondent":"寺嶋高齢者福祉課長","answer":"送迎につきましては、おそらく一部には希望が少なく、その場では通らなかったというようなお声も区のほうに届いたことはあります。やはり段階的に受付をしていった関係で、初年度かなり低く出ているのは、その両方が重なってこういった数字になっていると聞いております。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それぞれどのぐらいになっているのかということ、利用率はここにあるのですけれども、それを教えていただけたらと思います。かたや５５ページの心身障害者福祉会館のところでは、その理由というのは、そこら辺のところも教えてほしいと求めました。","respondent":"寺嶋高齢者福祉課長、松山障害者福祉課長","answer":"特に区のほうには寄せられてなく、逆にほかの施設の記述の中にも、そういった意味では活用をうまくしていると区のほうでは捉えております。これも先ほど申し上げたとおりですけれども、今現在… それから、対応方針のところで書かせていただいたのですが、やはりアピール不足であろうという分析をしております。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それから戸越と、これは来年総合支援施設ができた場合はこちらはそっくりそのまま戻るとここはもう空くという形になっていくのでしょうか。委託料が、それぞれ指定管理ということになっていますので、単独で幾らかというのがわかったら教えていただけたらと思います。","respondent":"松山障害者福祉課長","answer":"もう一つ、西大井のほうですが、ちょっと申し訳ありません。それをわかりやすくできるかどうかについては、今後検討してまいります。","id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それから職員の方が両方とも見るような、でもそれぞれ委託ということなので、今後ぜひ別々に出していただけたらということで要望をしておきます。それをもう既に７月から確保していると、１０月からスムーズに体制がとれるような形での配慮をぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"若林委員","kind":"質問","question":"２３ページの八潮南特別養護老人ホームの改善が必要な事項に、いわゆるホームのほうが９４.８％ということで、それほど低いとは思えないのです。その上でさらに収支状況の改善というのは、どのようにしたら、どういうことをやったら改善するのかという何か手立てがあるのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"法人だけではなかなか考えは進まないので、どういったことが将来的にこの施設で収支改善が可能であるかと、今まさに検討している最中です。その結果を踏まえて、将来的にどういう方策が一番いいのかというところは出していきたいと考えているところです。","id":"exchange-024"},{"speaker":"若林委員","kind":"質問","question":"３１ページの小山地域密着型多機能ホームの一番下の改善が必要とされたというところで「利用者中心のケアが徹底できている」と。ただ、その「近隣以外の区内・都内等での発信の機会を作ることができていない」という、これはどういう意味か尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"認知症に対する対応も非常に効果が出ているという特徴のある地域密着ホームなのですけれども、もっと広く自分たちの取り組みを発表するような働きかけをして、広めていきたいということも踏まえての記述だと言っております。","id":"exchange-025"},{"speaker":"若林委員","kind":"質問","question":"区の公のサービスの向上ということから見ると、わざわざモニタリングの記述に入れるようなことなのでしょうか。それを区外とか都外に、それは事業者としての企業理念としてはわかるような気もしますけれども、どうなのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"いわゆる職員のモチベーションを高めるといったところについてやっていきたいという考えも踏まえての記載ということで、ひとつ離職防止も含めた取り組みとして、自分たちはこれだけのことをやっているのだということを広く発信していきたいという表れの記載になっているものです。","id":"exchange-026"},{"speaker":"若林委員","kind":"意見","question":"そういう意味では公の施設として、しっかり管理委託料をいただきながら施設の充実等を図るという意味で理解をいたしました。これはさっきもあったけれども、品川区の介護施設の受け入れ方針として何か変わったことがあるのかなとちょっと、うがっているかもしれませんがとの意見を述べました。","respondent":"寺嶋高齢者福祉課長","answer":"介護度改善の事業というのは平成２５年からやっておりまして、１段階上がると２万円とかという形でやっている事業があります。その部分の改善については、おそらくその事業の中で区のほうにしっかり報告をして共有ができているという認識のもとに。","id":"exchange-027"}]},{"id":"topic-02","title":"障害者包括支援相談体制の構築検討委託事業者の選定","agenda":"障害者包括支援相談体制の構築検討委託事業者の選定","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"この検討を進めていくということ自体を障害者当事者の皆さんに説明はされてきたのでしょうか。ここでヒアリングというのが事業内容のところで出てくるのですけれども、この検討そのものを進めていくという説明はされたのか、伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"こちらの検討を進めていくことにつきましては、地域自立支援協議会、あるいは７団体の会長のほうにはもうお伝えさせていただき、これから皆様が相談しやすい体制をつくっていきますので、ぜひヒアリングにご協力くださいということで、ご承諾いただいております。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"障害者手帳をお持ちの方の中で、団体に入っていない方はどのぐらいいるのでしょうか。団体といっても、そしてその検討を進めていくに当たっても、もう少し広く進めていきますというのをお知らせする方法は考えていないのか尋ねました。","respondent":"松山障害者福祉課長","answer":"これから検討を進めるということなので、もちろんさまざまなお声は頂戴したいと考えています。拠点相談支援センターの相談員は、そのお声につきましては、それぞれの拠点相談支援センターを通じていただく予定になっております。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私はより広く聞いていくべきだと、それをやはり実行していってほしいと思うのですけれども、そこにも今回聞いていくということなのでしょうか。それと、障害者手帳を持っていて団体に入っていない方の割合というのは、わかれば教えていただきたいのですけれども。","respondent":"松山障害者福祉課長","answer":"障害福祉計画策定に当たりまして、お声を聞いているのは７団体を含めまして１０団体ということになっております。ただ、そしてそれを地域自立支援協議会の相談支援部会の中でもそのご意見を踏まえて検討させていただきまして、検討していくという予定です。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"なので、そういったところにもぜひ声を聞くべきではないかと思いますので、そこはぜひ検討してほしいと求めました。２カ月に１回ということだったり、あと成果報告書を求めているのですけれども、スケジュールなどが決まっていれば教えていただきたいのです。","respondent":"松山障害者福祉課長","answer":"１１月の前半で在宅介護支援センター等へヒアリングをさせていただき、１１月の後半から拠点相談支援センター、そして当事者の方々。その中間で、地域自立支援協議会に報告をすることになっており、また、成果報告書については、３月末を予定しております。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"今ある先ほど言った進捗状況とか業務内容、成果報告書は、地域自立支援協議会に全部報告はされていくのですか。厚生委員会にも報告等はあるのか、聞かせてください。","respondent":"松山障害者福祉課長","answer":"もちろん厚生委員会へのご報告は中間報告ということでさせていただきたいと考えています。地域自立支援協議会の皆様方にもご報告し、お諮りし、そこでご意見をいただければと考えています。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問","question":"この間の一般質問のときに、鈴木ひろ子議員がこの障害者包括支援相談体制のことについて質問したときに、伺います。","respondent":"松山障害者福祉課長","answer":"相談支援部会ですので、拠点相談支援センターにいらっしゃる相談員の方々、それから現在指定をとっております民間の事業者の方々となっております。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。こうした検討を進めた上で、この事業を進めていこうという決定をするのは地域自立支援協議会ということでいいのか尋ねました。","respondent":"松山障害者福祉課長","answer":"地域自立支援協議会につきましては、地域自立支援協議会が決定権を持つというよりは協議をする場でありますので、区が決定していきたいと考えています。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"地域自立支援協議会との話し合いの中で、お互いによしとなった段階で進めていくということで、地域自立支援協議会が難色を示しているもとで進んでいくというものではないということか尋ねました。","respondent":"松山障害者福祉課長","answer":"相談支援体制につきましては、どのような具体的な体制にしたら一番いいのかというところはじっくり一緒に検討していければと考えています。地域で相談しやすい体制というのが、具体的にどうするかというところの体制は、皆様のお知恵を拝借しながら進めていきたいと考えています。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問","question":"応募資格の１番に品川区の福祉現場の状況に精通していることとあるのですけれども、この間品川区に何か精通している部分があったのでしょうか。そこを説明を求めました。","respondent":"松山障害者福祉課長","answer":"やはり現場の地域包括支援センターの状況も、在宅介護支援センターに対する新たな取り組みの可能性ですとか、そういったかなり品川区の実情。人材配置につきましても、在宅支援センターの特性を考えると、きちんと品川区のことを踏まえている会社だと認識しています。","id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、ではアドバイス等は受けていたけれども、直接計画を立てたり、そういうことはこの間はしてこなかった事業者であるということか尋ねました。","respondent":"松山障害者福祉課長","answer":"ほかの地方自治体の地域福祉計画ですとか、障害者福祉計画ですとか、介護福祉計画のほうには策定支援をしている実績等はありますが、品川区の場合につきましては、計画の策定には携わってはおりません。","id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"障害者団体の１０団体ということだったのですけれども、具体的に７団体以外の３団体というのがどこなのか、教えていただけないか尋ねました。","respondent":"松山障害者福祉課長","answer":"それから障害者福祉を考える会。この４団体で、あと、広く全般的にさまざまな区が把握している障害者団体にはご意見を頂戴したいと考えています。","id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"先ほど相談支援専門員のきちんとした障害者の知識を持った人の配置が必要だろうという提案があったということだったのですけれども、区としては。今、ただ在宅介護支援センターの場所で一緒にやるみたいな形になるというイメージなのか、ちょっとそこら辺のところも説明を求めました。","respondent":"松山障害者福祉課長","answer":"在宅介護支援センターの相談員の配置というのも、その可能性があるのかどうかも含めての検討ということをしていきたいと考えています。研修期間があって、まだまだどういう体制がいいのかというのも含めまして、皆様のご意見を伺いながら検討していくということです。","id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もう来年の４月から在宅介護支援センターに３カ所つけて始まるという、それありきではないというところの確認だけ、ちょっとお願いしたいと思います。","respondent":"松山障害者福祉課長","answer":"４月にその人材が確保できたとしても、ただ初めての試みということで相談については丁寧に進めていきたいと考えていますので、４月からすぐに始まるということではございません。","id":"exchange-040"},{"speaker":"若林委員","kind":"質問","question":"実際、３月末策定を目指してということで、スケジュール的に教えてください。１２月以降、そこからどのように３月末、そこら辺の区の考え方を説明を求めました。","respondent":"松山障害者福祉課長","answer":"１２月に予定しております地域自立支援協議会の全体会、構築検討ということで、ある程度スピードを上げて検討していきたいと思っています。第２回目の地域自立支援協議会におきましては、どのような役割をお互いにしていくのかということを丁寧に進めていきたいと考えております。","id":"exchange-041"}]},{"id":"topic-03","title":"品川区立心身障害者福祉会館の運営事業者の選定","agenda":"品川区立心身障害者福祉会館の運営事業者の選定","exchanges":[{"speaker":"石田（ち）委員","kind":"意見","question":"実質１事業者ということで決まっているのですけれども、この２事業者だけで、しかも１事業者が辞退してしまうというこの品川区の現状は何でなのか。〔「それを言ってもしようがない」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問","question":"なので、品川区の事業に魅力がないのかと思ってしまうのですけれども、なぜなのかというのを区としても考えたほうがいいのではないかというぐらい、これしか来ないという思いが私はしているのですけれども、そこら辺はどのようにお考えか尋ねました。","respondent":"松山障害者福祉課長","answer":"実はこの辞退された事業者も、実際に説明会あるいはその後の現場の施設見学にも来まして、提案書ぎりぎりまでやり取りはございました。提案書のぎりぎりの８月３１日に、本当にその事業者も人材確保にぎりぎりまで頑張ったけれども、確保できなかったというのが事実のところです。","id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"提案","question":"私はさらに新たなことを提案するような事業者が来てほしいということなのかなと思ったのですけれども、新たな機能、体制はどのようにされるのか。そこはどうなのか伺いたいと思いますとの意見を述べました。","respondent":"松山障害者福祉課長","answer":"委員ご指摘の医療的な部分につきましては、看護師、あるいは医師の配置というのをご提案をいただいております。医師につきましては、これまで月１回ということでしたけれども、週に１回ということでご提案いただいているところです。","id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"提案","question":"どのような人員体制でというところまではまだ決まっていなくて、看護師と医師が週１回という提案をされているというところでわかりました。要は今までの事業者だけれども、適材適所ではなかったという思いが区にはあったのか、そこら辺を伺いたいと思いますとの意見を述べました。","respondent":"松山障害者福祉課長","answer":"障害者団体への対応等、その障害種別、あるいはその方に合わせたそれぞれの対応というのが必要になってきます。こちらの条件というのを課した理由というのは、本当に荏原地区の地域生活支援拠点としての機能拡大というのが大きなところです。","id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この選定会議の選定委員のメンバーを教えていただきたいのと、リハビリ機能の強化と、今までは医療的ケアの必要な人はいなかったわけですね。看護師も何人ぐらいか、医療的ケアが必要な人の受け入れの人数とかもわかったら教えてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"看護師においてももう既に２名配置しておりますので、重度の方に対しても既に支援ができている看護師がもう前もって整備をしているです。それから、リハビリ機能の強化ということで、確かに理学療法士等の、専門職も当然増やす予定です。","id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"学識経験者がどういう方なのかということと、学識経験者以外のメンバーも、こういうのは公表されているものだと思いますのでちょっと教えてください。そこのところも教えてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"以前からリハビリに見識の深い方ですので、非常によく現場も知っているということです。今、配置する人数や人件費部分にもかかわってくるものだと思いますので、今後予算に向けて精査をしていくということになろうかと思います。","id":"exchange-047"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"今までこういうふうに条件を付した上での選定というのはあまり記憶にない気がするのですけれども、あったものなのかどうなのかということを１つ。その辺のところがそうなっているかということと、あと、第三者も入ってそのところがされているのかということの確認だけお願いしたいと思います。","respondent":"松山障害者福祉課長","answer":"それから、国の手引きに準拠した研修ですけれども、先ほどの説明資料の中の（４）の法人として中期経営計画を立てということで。１番目に過去の法人内の虐待事件を教訓に、それから障害特性の理解に基づいた支援と環境の提供、利用者ニーズを中心に据えた支援を進めると。","id":"exchange-048"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１事業者しか来なかったということで、ぜひ区もしっかりと支援に入っていただいて、人権が守られるような中身を充実させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"こんの委員","kind":"確認","question":"確認は、こういう機能はついていますかという確認をしたいのですけれども、終わりましたという記録を残す機能はついているのでしょうか。そういう機能はこのアプリにはあるのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"今２カ月から予防接種が始まりますけれども、終わりましたというのを今度保護者の方が入れていただくと、それも記録として残ります。それをプリントアウトすれば、同じように持っていくことができるという機能になっております。","id":"exchange-050"},{"speaker":"若林委員","kind":"確認","question":"都の発表の内容と同じ内容のものなのかという確認です。ということは、都の助成、補助金で全部賄って、区の単費での支出はないのかという確認をします。","respondent":"鷹箸保健予防課長","answer":"今、先ほどご説明させていただいた中で、（１）妊娠を予定または希望する女性を東京都ではこれまで包括補助の対象としておりまして。東京都は、これまで区では既に対象としていた同居者も、今後１１月１日以降、包括補助の対象にするというふうに変更になってあります。","id":"exchange-051"},{"speaker":"石田（ち）委員","kind":"質問","question":"この対象拡大の前と後で、どれぐらい対象人数が増えるか、大枠でそういう想定はあるのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"見込みとしては当初１,２００件だったところを、１,８５０件ぐらいに増えると見込んでいたところですが、今の見込みでは概ね２,２００件ぐらい。","id":"exchange-052"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"具体的に抗体検査の予算というのが、検査とそれから予防接種それぞれ今年幾らぐらいになるのかというところだけ説明を求めました。","respondent":"鷹箸保健予防課長","answer":"抗体検査１件当たりが６,２４２円、予防接種が１万５０２円となっておりますので、それを掛けた額ということで、もともとの予算が１,２００万円ぐらいだったところ、対象拡大後は２,４００万円足らなくなるので、３,６００万円ぐらいかかるということを予想しております。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/731730?Template=document&Id=3522#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":73394,"voices":149}},{"id":"h30-20181030-8","meetingId":"h30-cm10","date":"2018年10月30日","dateIso":"2018-10-30","committee":"建設委員会","time":"午前１０時００分～午後 ０時５０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件整理しています。","topics":[{"id":"topic-01","title":"体験型環境学習施設の整備","agenda":"体験型環境学習施設の整備","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"なぜ今回、そういうのがよくわからないと思って、そこをまずお伺いしたいのと思います。やはり少し遊べるような現状ではあるわけですから、その辺には配慮していただきたいと思うのですが、いかがか尋ねました。","respondent":"小林環境課長、溝口公園課長","answer":"１点目ですが、先ほどもご説明しましたとおり、学びへの需要の高まりというところがあるかと考えております。１つは体験というところを１つの機運として設置して、この施設の建設、施設について検討ができたというところがスタートです。 今後、どのような形で建物が建つのか検討が進んで行くと思います。環境課と連携しながら、さらに深度化していき、区民の方により親しまれる公園施設といったものをつくっていきたいというふうに考えております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"どのような意見交換の場を設けて、またそれがどのくらい反映されたのか伺いたいと思います。それと、こみゅぷら八潮に移って今活動しているわけですが、将来的にはこの施設などに入ったりするのかというところはどうなのかお伺いします。","respondent":"小林環境課長","answer":"１点目のＮＰＯとの意見交換ですが、この施設に関することだけではなく、センターの運営等について定期的な会議を持たせていただいております。２点目ですが、基本的には環境に関する類似の施設ですので、最終的には戸越公園に集約されると考えております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"関心も高いということもありますし、私はこういった区民の皆さんや子どもたちの関心を高めるものになると思うのですけれども、いかがでしょうか。この点もお伺いします。","respondent":"小林環境課長","answer":"その深度化を図った後に、プロポーザルで提案を受けて、それに合わせた展示を実際に展示していくと考えるところです。その中身、またマイナスなイメージをあまり持たれないようなこととして取り組んでいただけるような工夫は進めてまいりたいと考えております。","id":"exchange-003"},{"speaker":"安藤委員","kind":"意見","question":"今、現状どうなっているのか、そういった視野を広げた展示というのをぜひ意識をしていただければというふうに思っています。これは意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"筒井委員","kind":"質問・要望","question":"活動していっていただきたいと考えておりますけれども、子どもたちにどうやってこの施設に来ていただくのか、説明を求めました。","respondent":"小林環境課長","answer":"こういった施設が今現在、社会科見学ではどう使われているか、どのぐらいの学年が対象なのかということを意見交換をしながら進めているところです。","id":"exchange-005"},{"speaker":"筒井委員","kind":"質問・要望","question":"先ほど、温暖化などの話も出ましたけれども、施設に太陽光発電やほかの再生可能エネルギーを利用した機器の導入などは考えておられないのでしょうか。ポイント制とか、そのつなぐということで、どのようなことをお考えになっているのか尋ねました。","respondent":"小林環境課長","answer":"今、委員からご提案のありました太陽光につきましても、しっかり検討はしていく予定です。１つの情報発信ができるように、ホームページなどを含めて、各課連携を図りながら検討を進めている最中です。","id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"スタンプカードとか、楽しみながら品川区の施設を回っていただけるような仕組みづくりというのは一つおもしろいかと思うのですけれども、その辺のお考えなどはいかがか尋ねました。","respondent":"小林環境課長","answer":"先ほど申し上げました、先ほどは指導主事の話もございましたが、こういった施設の関係者と意見交換の場を設けてあります。どういった形が回遊性として楽しめる方法なのかということにつきましては、引き続き検討に努めてまいりたいと考えております。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"幾つかお伺いをしたい点があるのですけれども、私が個人的に１つ確認をさせていただきたいのですけれども、キャッチコピーですね。これについて、どういうものをイメージされているのか、確認の意味でお伺いをしたいと思います。","respondent":"小林環境課長","answer":"そのにぎわいの１つとしまして、それ以外のにぎわいの創り方等につきましては、引き続き検討を続けてまいりたいと考えております。来てもらうためににぎわいを創出していくことについて深めていきたいと考えております。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１回、２回ぐらい行ったらもう飽きてしまうような設備で、そういった検討を図っていただきたいというのが要望です。環境問題というのはやはりどうしても漠然としてしまうのですが、ぜひその点のコンセプトをとり入れてほしいと求めましたが、いかがか尋ねました。","respondent":"小林環境課長","answer":"その中で得たアンケート結果など、区民の方の意識を見定めた上で、その辺についての検討は進めてまいりたいと考えております。環境の分野、非常に取り組みやすい分野の１つかと我々も認識しています。","id":"exchange-009"},{"speaker":"大沢委員","kind":"意見","question":"その辺をどう子どもたちに説明をされていくのかで、それとも形なのかというところで、どのような連携をとっていくのか。それと、八潮にあります環境情報活動センター、これはまさにフィールドワークの際たるものでありますが、その辺との連携をどのようにとっていくのかとの意見を述べました。","respondent":"小林環境課長","answer":"もう１点、その中に統合していくことを今考えておりまして、それまで八潮については存続していくところです。そういった講座については今現在も進めているところでございまして、八潮がある間は引き続き講座は運営していきたいと考えているところです。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"あくまでも箱についてお尋ねをしなければいけないのですけれども、学校と称するもの全てだと思うのですけれども、どういう範囲の学校まで考えてらっしゃるのか尋ねました。","respondent":"小林環境課長","answer":"そういったところで、まずは区内全体全てというところで学校の範囲を考えております。で、他区との連携というのも非常に重要かと思っているところですが、まずは区内全域のところはしっかりと考えていきたいと考えております。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問・要望","question":"今後の動き次第だとは思うのですけれども、そのあたりも視野に入れながら検討されていくような目線もお持ちだと思うのですけれども、そのプランを確認させてほしいと求めました。","respondent":"小林環境課長","answer":"周辺の学校との連携というところですが、学校だけではなく、産学民との連携というのは非常に重要だと考えています。企画展示をするようなスペースも検討しているところでございまして、交流できる展示の場とか、この施設の中で位置づけできるかと考えております。","id":"exchange-012"},{"speaker":"大沢委員","kind":"質問","question":"その辺はできるものなのでしょうか、できないものなのでしょうか、都と区の教育に関する連携はできるものなのですか。説明を求めました。","respondent":"小林環境課長","answer":"１つは、エコフェスティバルの中で、ボランティアとしても会場にお越しいただいている状況です。例えば大崎高校で何か環境と絡めて発表できるようなものも含めて、その展開についてはうまく連携を図れればというふう考えております。","id":"exchange-013"},{"speaker":"松永副委員長","kind":"質問","question":"３つ目が、駐車・駐輪スペース等はあるのかどうか。４つ目が、区民への周知、また、現地まで行くサイン表示はどのように考えているのか、説明を求めました。","respondent":"溝口公園課長、小林環境課長","answer":"環境学習施設ということで今回ご報告させていただいているところです。公衆便所があるところが予定されているところですが、また公衆便所、今後検討していきたいと考えているところです。まず１つは、そこで活用されないような時間帯については、地域センターと同じような形で貸し出しは考えていきたいと考えているところです。","id":"exchange-014"},{"speaker":"松永副委員長","kind":"質問・要望","question":"ご存じのように、そこを道路課と連携して、安全なルートを確保できるような道順ですか。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-02","title":"平成３０年度ウォームビズキャンペーンの実施","agenda":"平成３０年度ウォームビズキャンペーンの実施","exchanges":[{"speaker":"横山委員","kind":"意見","question":"先ほども１点、スモールステップでどういう方でもやろうと思って、こういうやり方はすごくすばらしいと思いました。どういった情報が区民に効果的に届いて、それが１人１人の行動を変えていく、その考え方をお知らせくださいとの意見を述べました。","respondent":"小林環境課長","answer":"こういった１つ１つの項目をタイムリーにその時期に合わせて何か発信することができないか、そういったところについても検討を進めている最中です。引き続き検討を進めてまいります。","id":"exchange-016"}]},{"id":"topic-03","title":"大井町駅前パブリックスペース設計コンペティションの結果","agenda":"大井町駅前パブリックスペース設計コンペティションの結果","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"２２７の提案作品がついているので、区としては、この反響の大きさの理由をどのように考えているかという点についてお伺いします。４点目は、これからのトイレのあり方について提案と書いているのですけれども、その辺のご説明をお願いしますとの意見を述べました。","respondent":"溝口公園課長","answer":"少し説明が足りなくて申しわけありませんが、他にも私の記憶の限り、ちらほら区民の方が来ていたです。よく男女共用のトイレが１つ建っていたりとか、そういったことも含めて、今回評価しての最優秀賞の受賞になったと考えております。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後に質問なのですけれども、そこにある程度区としての選定の考えというのが全くないというわけにはいかないと思います。区としてはどういうことを、それをどのように審査に反映させたのかという点だけ、最後に説明を求めました。","respondent":"溝口公園課長","answer":"つくっておしまいではありませんので、また安全・安心という、公衆トイレはそういったところも大事になってくると思います。お金がかかり過ぎるのも、そういったところも含めて、この提案なら行けるという形のものをもって最優秀作品という形に決定させていただいたものです。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"提案","question":"そういうもののご提案がされているというところで、これは本当に工事が間に合うのかということが１つと、予算は区の単費でやるのですかね。","respondent":"溝口公園課長","answer":"先ほども少しご説明をさせていただいたところですが、来年の１月まで、まず設計に入らせていただきます。ただ今回、その部分については、今後しっかりと予算組みをしていきながら対応していきたいと考えております。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"どういったことなのかということと、あとは高さが違うのは、これはデザイン的なものと捉えてよろしいのか尋ねました。","respondent":"溝口公園課長","answer":"説明が悪くて申しわけありません。あらゆるジェンダーが安心して使えるジェンダーフリートイレという形でのコンセプトを説明しているところの中で、図面上は一時的に、今回の提案。","id":"exchange-020"}]},{"id":"topic-04","title":"立会川における高潮発生時の避難基準","agenda":"立会川における高潮発生時の避難基準","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"当時はどういった基準で、避難勧告まで出されたのだと思うのですけれども、そういった発令をしていたのか伺いたいのが１点です。高齢等により、この垂直避難ができない世帯というのが、今回の対象地域の中にどれぐらいあると把握されているのか伺いたいと思います。","respondent":"持田河川下水道課長","answer":"２点目、２階以上への避難が難しい方というところですが、避難所も開設していこうという考えです。４時間前とか５時間前とかという段階で、避難所を開設して、このような形の基準化というものをしたものです。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"区として動線を把握しておかないと、まずはそういった把握に努めていくべきだと思いますけれども、いかがでしょうか。少なくとも、土砂災害と同じように説明会は開くべきなのではないかと思うのですけれども、いかがか尋ねました。","respondent":"古巻防災課長","answer":"そういったものがある程度周知というか、認識していただけるような何か取り組みをしていく必要があるのかというふうには思っております。説明会も含めまして、さまざまな検討をして、きちんと周知が行き渡るように取り組みを進めていきたいと考えております。","id":"exchange-022"},{"speaker":"横山委員","kind":"質問","question":"情報が個別に届くように周知を行うということで記載されているのですけれども、こちらのエリアの中に浜川小学校等があります。いらっしゃるのかと思うのですが、そのあたりはどのような想定をされていて、どういった形で周知を行っていく予定か尋ねました。","respondent":"古巻防災課長","answer":"そのあたりは教育委員会と十分に連携をしましてということで、教育委員会を通じてになるのか、しっかりと周知を進めていきたいと思います。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"質問","question":"注意水位Ｔ.Ｐ.＋１.２０、警戒水位がＴ.Ｐ.＋１.５０、３０センチ刻みということでいいのですかね。警戒水位で避難する方は今いないということを一般質問で、なかなか、何か基準のようなものがあってこういうふうにされたのかというのがまず１点です。","respondent":"持田河川下水道課長","answer":"これはＴ.Ｐ.＋１.８７になればすぐさまということではないのですが、これが１つの溢水、浸水が発生する目安であろうかと思います。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問","question":"私も防災ラジオを平成２４年に買って置いてあるのですが、かなり優秀で、各地の防災訓練の朝のお知らせが全部入るようになっている。それと、交換と言うか対応の時期というのはどのようにお考えになっているのか、非常に大事なことだと思いますので、お伺いしたいと思います。","respondent":"古巻防災課長","answer":"ＦＭの放送も始まりますし、そういったことで、こちらとの兼ね合いも含めて検討を具体的にしていく時期なのかというふうに思っております。大体、それぐらいの時期ということで考えていただければと思います。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問・要望","question":"確か平成２４年に導入されたときに、私は実費で８,０００円出して買いましたけれども、その点も含めてお考えいただきたいと。ここは、ただ単にＦＭ放送が流れるということで代替できるのかというところも、そこはしっかりと検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-05","title":"平成３０年度区内一斉防災訓練の実施","agenda":"平成３０年度区内一斉防災訓練の実施","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"その教室を確認するというような内容になっておりましたけれども、体育館の避難所の開設というのはどのような位置づけになっているのでしょうか。伺います。","respondent":"冨澤災害対策担当課長","answer":"各避難所におおむね１０名前後の職員が参集をいたしまして、避難所の防災区民組織の皆様と一緒に設営・運営を行うものです。各避難所、教室が割り当てられると思いますので、そこにそれぞれが散っていただくような使い勝手をしています。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"もう少し、品川区のほうでもイニシアチブをとって、もう少し実践的な訓練内容を追加できないかという思いがあります。ぜひそういったことを実行できるように、品川区としてもイニシアチブをとるべきではないかと思いますが、いかがか尋ねました。","respondent":"冨澤災害対策担当課長","answer":"各避難所のやはり考えがございまして、また、去年と違うような内容をやっていこうという形で検討しています。さまざまなご提案を差し上げて、ぜひとも訓練内容を充実したものにしていけるように、今後とも検討してまいりたいと思います。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"確認","question":"これは、とりあえずの説明などがあったのですけれども、そういう方たちも今回はこの指定されているところにはいらっしゃるということなのでしょうか。私も毎年出ていますけれども、ここについて確認をさせてください。","respondent":"冨澤災害対策担当課長","answer":"いろいろこういった学校や、医療救護所になりますけれども、それと連携した訓練については今回は想定はしておりません。合わせて医療関係者のご参加につきましても、基本的には、今の段階では参加の話は聞いてございません。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"提案","question":"私も城南小学校に毎年伺って、町会の一員として参加をしております。ご提案はするというお話があったのですが、やはり提案がないと、それを知らないわけですからとの意見を述べました。","respondent":"冨澤災害対策担当課長","answer":"今、委員からご指摘がありました新しいメニューの提示ですけれども、今後、区としてもいろいろなメニューを考えながら、各避難所連絡会の中でご提示をしてまいりたいと考えております。","id":"exchange-030"},{"speaker":"大沢委員","kind":"質問","question":"都の防災アドバイザー派遣事業については、今回も派遣が予定されているのでしょうか。今年度についてはこれはどうなっているのか、今年は行われないのか、そこのところを説明を求めました。","respondent":"冨澤災害対策担当課長","answer":"以前ございましたが、今年度につきましては、その予定はございません。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"これは実際に品川区で最後に防災訓練が行われたのが今年３月４日のスクエア荏原なのですけれども、わかる範囲で、間仕切りシステムを実際に導入して行われる場所というのはあるのか尋ねました。","respondent":"冨澤災害対策担当課長","answer":"今現在、各避難所連絡会の中で、今年度どういう訓練をしようかということでまとめている状況です。これから１１月末ぐらいに私どものほうに情報が入ってくる予定ですので、この訓練をやるのかどうかもはっきりしていない状況です。","id":"exchange-032"},{"speaker":"筒井委員","kind":"提案","question":"各避難所の避難所連絡会のお考えであるとか、ほかの委員の方からもありましたけれども、区からもご提案を積極的にやっていただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"}]},{"id":"topic-06","title":"所管事務調査を一括して議題に供します。 本日の所管事務調査は、水辺の利活用","agenda":"所管事務調査を一括して議題に供します。 本日の所管事務調査は、水辺の利活用","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"報告事項(6)も舟運社会実験ということで、それぞれについて、費用が幾らなのか伺いたいと思います。この事業の目的について、改めてもう少し説明を求めました。","respondent":"持田河川下水道課長、稲田都市開発課長","answer":"目黒川のライトアップにつきましては、金額は主に１,０００万円ぐらいという形でのライトアップ事業という予定です。こちらにつきましては、常設のライトアップを今後やっていく中での１つの社会実験という位置づけで考えております。 そちらのほうに大崎エリアマネージメントが事務局の１つというところでやっておりまして、廃油を集めて使う発電機を借りるお金など、そういったものに対して４００万円ほどの補助金を出しております。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"では、合わせて１,４００万円ぐらいということになるのでしょうか。もう少し伺わせていただきたいのと、今後、区としてさらなる水辺活用に向けての規制緩和などを活用していく考えがおありなのかどうか伺います。","respondent":"持田河川下水道課長、稲田都市開発課長","answer":"そういった水辺を利用する方々の協議会を設置いたしまして、その協議会の活動に対して都として支援するといった位置づけでございまして。こういった地域の自主的な取り組み、主体的な取り組みを支援するというのが… ただ、そちらの金額については、申しわけありません。私のほうで把握しておりません。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"なかなか、名古屋にも視察に行きましたが、かなり苦労しているようなことが見受けられました。ここに(7)で書いていますけれども、これを改善させていくためにはどういったことが必要なのかという点についてお考えがあれば説明を求めました。","respondent":"持田河川下水道課長","answer":"協議会を設置したりということもありますので、そういった部分で、お住まいの方への配慮ということもしっかり考えていきたいと考えています。何とか事業化する中で、目黒川エリアを優先できないかというところも含めて、そのような要望をしていきたいと考えています。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"確認","question":"そこのところのスタンスをお伺いしたいのと、どんどんこういうことを２３区、こういうところでどんどんやっていきなさいよというスタンスなのか。私どもは今までやはり、議会での勉強会等でさんざん言われてきたので、そこについての現在の感触についてお伺いしたいと思います。","respondent":"持田河川下水道課長","answer":"この水辺の活性化というものを、観光のほうと、また我々河川下水道課のほうで合わせた形でしっかり進めていければいいなというふうに考えております。今、こういった部分につきましては、都のほうとしても協力姿勢にあるというふうに考えております。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問・要望","question":"民間主導ですから、これは広域連携をしていかないと、品川区だけでやっていってもだめだと思います。どちらかというと役所同士のやりとりがあったほうがよかったのかななどと思ったものですから、こういう思いで今日は質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"横山委員","kind":"確認","question":"細かい部分も含めて確認の意味も込めて、この間、とても生活に身近な存在だったという話もお聞きしてまいりました。３点目になるのですけれども、そこの住民に水辺をどう近く感じさせるかという、お答えできる範囲でお願いいたします。","respondent":"持田河川下水道課長","answer":"そういった中で天王洲というのが１つの魅力として高いということも、そういった区としての強みというものはより生かしていきたいと考えております。そういった中で、水辺のエリアをまず考えながら、品川区全体でそういった貴重な財産を生かしていきたいと考えております。","id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"昼間に舟で通られていると思うのですけれども、ライトアップにあわせて夜間に舟を出すということを考えなかったのでしょうかということ。２点お伺いします。","respondent":"持田河川下水道課長","answer":"これから時間をかけてやってまいりますが、常設のライトアップをしながら、水辺の光を増やしていきたいと考えております。今年度も少し聞くところによりますと、この１１月、１２月に合わせた形の夜間クルーズというものも一応予定しているというふうには聞いております。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問・要望","question":"あれはせっかく待合所を置いたわけですから、水上タクシーの誘致ということをぜひやっていただきたいのですけれども、ＳＵＰですね。水上タクシーは、品川区も天王洲と京浜運河、そのスタンドアップパドルと水上タクシーについてのお考えはいかがか尋ねました。","respondent":"持田河川下水道課長","answer":"今後、どういった形で使われていくのかというのは、まさに区のほうで検討しているところです。そういった使われ方、またはそういった使い方の利用例などにつきましても、合わせて検討していきたいと考えております。","id":"exchange-041"},{"speaker":"筒井委員","kind":"質問","question":"水上タクシーなどはどのようになりますか尋ねました。","respondent":"持田河川下水道課長","answer":"どういった舟を考えていくかというところは、これから桟橋の整備に合わせてその使い方、ルールのようなものについても合わせて検討していきたいと考えております。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"その点はいかがでしょうかということと、長期的な対策とともに、短期的で即効性のある対応策というのはないのでしょうか。ぜひやっていただきたいのですけれども、今の区のお考えはいかがか尋ねました。","respondent":"持田河川下水道課長","answer":"それ以上のものというのは今のところ検討していなかったこともありますが、今後検討していきたいと考えています。品川区のほうも検討会に参加していますが、浚渫するとか、少しでも水質をよくしていくような継続した取り組みというのが大事だと考えております。","id":"exchange-043"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"９月３０日の台風で、避難場所を、品川区から提供していただけるのでしょうか。それについて、これは深夜、夜間であってもしっかりと対応していただけるのか、確認させてください。","respondent":"古巻防災課長","answer":"深夜、区のほうでは災害対策本部ということで関連の職員が詰めておりますので、ご連絡いただいた時点で何らかの対応をすることは可能かと思います。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"確認","question":"安全を確認をして、その間は１時間ぐらい外で待機をして、消防署からは品川区の災害対策本部の連絡先を渡されたと言っていました。そこについて、私もこれからそういうことをご案内する上で、必要なことなので確認をさせてください。","respondent":"古巻防災課長","answer":"なかなか対応というのは難しい面もありますけれども、何らか退避できるような場所については考えて、そういうような形でよろしくお願いします。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"意見","question":"わかりました。品川区は責任を持って、区民の方の住居と言うか、避難場所の確保はお願いをしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"横山委員","kind":"質問","question":"この台風第２４号の対応についてのご報告なのですけれども、少し見えにくい部分も含めてなのですけれども、出ていたりするのでしょうか。防災課さんのほうで何か、相談の件数が何か増えているですとか、もしありましたら説明を求めました。","respondent":"古巻防災課長","answer":"どういった準備を進めればいいのか、考え方と言うか、そういったところをきちんとお知らせする情報提供ができればと思います。何か医療的なご相談でありますとか、そういったところにつきましては、適切な窓口をご案内するようになろうかと思います。","id":"exchange-047"},{"speaker":"横山委員","kind":"質問・要望","question":"未確認の情報ですとか、そうしたところもご配慮いただいて、さまざまな部門と連携をして対処していただければと考えています。今年は重なっているということもありまして、そのあたりのご配慮をいただけたらと思いますので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"被害のところで７２件、８件という数字があるのですが、お伺いしたいと思います。それと、個人の住宅の被害、そういったものはどう把握するのか尋ねました。","respondent":"古巻防災課長","answer":"公園課といったところ、あとは警察・消防へ聞き取りをして、被害の状況を把握しているところです。これは１００％は難しく、場合によって罹災証明が必要になってくることは考えられますので、そういった形での把握をしているという状況です。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問","question":"１００％は難しいということなのですけれども、今回、一定程度は民間の住宅のこういった物的被害というのも、件数としては把握しているということでよろしいのか尋ねました。","respondent":"古巻防災課長","answer":"これはあくまでも区が対応して、例えば道路とか、区有の敷地で何か対応が必要になったものという件数とご理解いただければと思います。樹木に関してもそうですけれども、実際に区のほうで対応した件数というふうにご理解いただければと思います。","id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/146532?Template=document&Id=4248#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":59100,"voices":165}},{"id":"h30-20181030-9","meetingId":"h30-cm10","date":"2018年10月30日","dateIso":"2018-10-30","committee":"文教委員会","time":"午前１０時００分～午後 ３時１８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を75件整理しています。","topics":[{"id":"topic-01","title":"平成３０年度移動教室実施結果","agenda":"平成３０年度移動教室実施結果","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"事故もなく終了したということで大変よかったと思うのですが、１つ、ざっくりでいいのですが、小学校と中学校の移動教室の中身を教えてほしいのと、参加できなかった児童・生徒の方がどのぐらいいるのかと、その理由がわかったら教えてほしいと求めました。","respondent":"篠田学務課長","answer":"あるいは登山、ハイキングということで、雄国山等のハイキング等を実施しています。一部、イスラムの方などは宗教上の理由で神社仏閣に参拝ができないということで、ご欠席された方がいらしたというのを聞いております。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"参加できなかった児童・生徒の方への後のフォローなど、何か具体的にされていることがあったら説明を求めました。","respondent":"篠田学務課長","answer":"例えば、お子様同士で現地の思い出、状況を話し合ったり、場合によってはお土産などを買われていったりされる方もいらっしゃるとはお聞きしています。教師も寂しい思いをしないような形でフォローしていると聞いております。","id":"exchange-002"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"２点お伺いします。１点目が、参加されているお子様の中で、いわゆる財政的な支援を受けている生徒はどのぐらいいるのか、わかる範囲で教えていただきたいです。","respondent":"篠田学務課長、大関教育総合支援センター長","answer":"財政的支援のほうをお答えいたします。移動教室に関しましては、小学校で５,７００円、中学校で６,３００円と就学援助が支給されますので、そういった方々がやはり該当するのかなです。 貸し出しのＰＨＳ・携帯等は対応しますが、管理職が持っておりますので、子どもたちに具体的に何か持たせるなどというケースはこれまでございません。","id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"小学校、中学校ともに教えていただきたいのが１つ。時期的にここと一緒ではなくて、また学年全部で行くのかもしれませんけれども、マイスクールのほうの宿泊についてご説明ほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"教員のほうがまず手厚くなって、それ以外にさらに足りない部分をということで支援員が行く、お子さんの実態に応じながら支援しています。やはり日光に行っておりまして、日ごろの適応指導教室などとはまた違った様子などを見ながら、家庭との共有の学習材料の一つとしています。","id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"いろいろ大変なこともあるので、今やられているのですけれども、ぜひさらに充実してほしいと求めました。こちらも続けていただきたいのですが、またその一方で、事故などないように十分注意してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"つる委員","kind":"確認","question":"別紙２にもあるので確認ですが、移動は、バスでするということでよろしいのか尋ねました。","respondent":"篠田学務課長","answer":"移動教室の移動は全てバスを使ってあります。","id":"exchange-006"},{"speaker":"つる委員","kind":"質問・要望","question":"大会組織委員会ですか、２年後の東京オリンピックでのバス使用に関してということで報道があって、学務課長もそこに出演されていました。林間学園については、どういう手だてが考えられるのかという現状のところを教えていただきたいのと、現段階の手だてを教えてほしいと求めました。","respondent":"篠田学務課長","answer":"実際にこの時期に実施するのが、おおよそ１,５００人前後のお子さんに影響が出てくるだろうということで、現在検討を進めているところです。２泊３日で実施しているものを１泊２日にしたら、さまざまな形での検討というのは、これから進めていこうと考えております。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問・要望","question":"かなり早い段階で調整しなくてはいけないというのがあるのでしょうから、それから林間学園という、いろんな日常とは違う学びの場というのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"平成３２年度に１年生になる方、学区域が変わるわけですから、そういう点できちんと理解していただくという作業が大変重要なのだろうと思うのです。その辺は具体的に現実的にどういうふうな体制をとろうとしているのか、まずそこをお尋ねしたいと思います。","respondent":"若生学校制度担当課長","answer":"これから入られる１年生、要は１年生で言いますと就学前の保護者といったところへの周知が非常に重要になってくると、私どもも考えてあります。なおかつ、個々に、それから保育園・幼稚園の職員の皆様にきちんとご理解いただけるように周知をしていく予定です。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"ここのところはどういうふうに捉えているのかを伺いたいのと、来年のちょうど今ごろの時期に、教育委員会に問い合わせが殺到すると思うのです。きちんと不安を払拭して入学していただくということが一番大事ですので、そういうこともどういうふうに捉えているか、その辺も伺いたいと思います。","respondent":"若生学校制度担当課長","answer":"それと、校長や学校の現場の職員の方々からＰＴＡの役員の皆様等にもきちんと周知させていくような対応をとっていく予定です。区への問い合わせへの対応等についてですが、そういったことも含めまして、きちんとこれは対応できるような対処をとってまいりたいと考えています。","id":"exchange-010"},{"speaker":"南委員","kind":"意見","question":"２３区の中でも廃止している状況がある中で、やはり矛盾というか問題というか、そういうところを感じないではいられないと私は思っています。これは意見として申し上げておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこのところの重要性をしっかり捉えていただきたいと思うのですけれども、具体的にどんな説明をして意見を聞かれているのでしょうか。出向いていくとか、そのぐらいしていい中身であると思っているのですが、内容の説明と意見を聞くという調整をどうされていくのかを説明を求めました。","respondent":"若生学校制度担当課長","answer":"そういったところで、地域への説明というところでも一定程度、ご理解を得ていきたいと考えているところです。ご説明の仕方につきましては、ご説明、ご意見を伺ってまいりたいと考えております。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはりわからない、いろいろ質問が出たから来てほしいと言われたら、ぜひ出向いていって説明もしてほしいと求めました。検討した結果、評価的にはさらに難しくなっているのではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは要望で終わります。以上、質問は３点です。","respondent":"篠田学務課長、若生学校制度担当課長","answer":"特別の事情があれば、いわゆる指定校変更でお受けして、検討していくという形で対応しています。今回の見直しに当たりましても、その部分に関しましては、特別、変更する予定は今のところはないものです。連携は荏原第一中学校とのつながりが強いというところで、地域とお話しする中で、どういった対応が可能かというところも考えてまいりたいと思います。","id":"exchange-014"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"初めてそこに入学するのですから、それを、年度途中だからといってだめだというのはどうなのでしょうか。一定の理解はできるのですけれども、例えば、空きがある中で選択させないというのはどうなのか尋ねました。","respondent":"篠田学務課長","answer":"指定校変更で今、対応しているということで、実際になかなか条件が厳しいというのは、確かにご指摘のとおりです。今後どういった形で対応できるのかというのは研究していく必要はあるのかなとは考えているところです。","id":"exchange-015"},{"speaker":"渡部委員","kind":"質問","question":"平成３２年というすばらしいタイミングでできるのですから、年度途中、学校選択にしていいのではないかと思います。そこだけ「検討します」と言ってほしいのですが。","respondent":"篠田学務課長","answer":"確かに非常に重要な課題であるということは認識しています。今後、こういった部分がどういった形で対応できるのかどうかということも含めて研究していく必要はあるかと思います。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問・要望","question":"すぐわかるのですけども、普通の住んでいる人は、隣接校がどこかわからないですから。実はもう、準備が実は平成３２年に間に合わないのではないかなどと不安を抱いてしまったのですけれども、その辺をちょっと詳しく説明を求めました。","respondent":"若生学校制度担当課長","answer":"平成３２年度から実施していくには、もう本当に４月に入ってからすぐにパンフレット等も浸透させて、確実に周知してまいりたいと考えています。","id":"exchange-017"},{"speaker":"渡部委員","kind":"質問・要望","question":"保護者みずからが理解しようと動いてもらわないと、なかなか動けないと思いますので、ありとあらゆる手段をぜひ考えていってほしいと思います。これから１０年も２０年も多分この仕組みでいけるような仕組みなのだと思いますので、平成３２年には新しい形で進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"つる委員","kind":"質問・要望","question":"本当に大変で」と、私のところに「どうしたらいいのでしょうか、何とかならないのですか」とその方が相談に来たというようなことがありました。「それはちょっと丁寧ではないな」という感があったものですから、経過措置がちゃんとある等というのも含めてやっていただきたいと思っています。","respondent":"若生学校制度担当課長","answer":"学区域の小学校のほうの変更の対象となる、特にマンションを購入される予定の世帯の方、きちんとやはり周知する必要があると考えています。そういったところを通じて、直接、対象となる方についても周知できるような形を考えてまいりたいと思います。","id":"exchange-019"},{"speaker":"つる委員","kind":"質問・要望","question":"やはりそういう選択の意味でも、しっかりとそういう情報がきちんと、今ご答弁いただいたような形で行き渡るようにぜひやっていただきたい。これは２０２０年、平成３２年４月というところに、そこだけはお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ちょっと確認で、パンフレットは４月からといいますけれども、委員会等に伝わるのでしょうか。そういったこともあり得るということは、ぜひ確認しながら、そのときにお伝えしてほしいと求めました。","respondent":"若生学校制度担当課長","answer":"これは来年度、制度が施策として決定した後に、法令上の整備をしていこうと考えています。そういったことはきちんと周知できるような形で、資料、パンフレット等に盛り込んでいきたいと考えております。","id":"exchange-021"},{"speaker":"高橋（し）委員","kind":"質問","question":"ですから、決定というのは施策等の決定で決定ということなのですけど、それは教育委員会として決めると。ですから、そこのところがちょっとわからないのですみません。","respondent":"若生学校制度担当課長","answer":"決定するというのは、教育委員会として決定していくということで、教育委員会の審議の中で、今年度中に制度を決定するといった手続きをとるです。","id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"意見","question":"それが今年度中ということで。それで、決定はしていないけども、説明とか、そういうのはしていくということですよねとの意見を述べました。","respondent":"篠田学務課長","answer":"要は、教育委員会の権能として学区域の設定等がありますので、そちらは最終的に、今回、原案を出させていただいて、地域に対してご説明をする。今まであったものをこうしますというのを、最終的に教育委員会の権能として決定していくといったことが今年度中に行われるです。","id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"質問","question":"そういう時にそれはもう一度、こちらに出てくるのでしょうかということなのです。原案はこうでしたけれども、ここを少し変えて、教育委員会で決めていきますというお話をしていただけるのかというところをお伺いしたいです。","respondent":"篠田学務課長","answer":"基本的には、権能としては教育委員会の権能ですけれども、当然、文教委員会のこの場においても、いろいろ、もし変わるようなことがあれば、最終的にはご報告をさせていただいた上で、教育委員会で決めていくという段取りになろうかと思います。","id":"exchange-024"}]},{"id":"topic-02","title":"平成３０年特別区および東京都人事委員会勧告の概要","agenda":"平成３０年特別区および東京都人事委員会勧告の概要","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"最後に説明があったと思うのですけれども、改めてそこのところを、どう変わったのかを教えていただきたいです。業務委託、非常勤採用の方々等々についても、公務員本人以外に影響がどのぐらいまで広がるのかというところを伺いたいです。","respondent":"熊谷指導課長","answer":"今回、平成３０年４月より実施した行政系人事・給与制度の見直しに伴う改正に伴って、職員構成に変化があったことによる影響と聞いております。これにつきましては、給料表によるものではございませんので、そちらについては今回の影響を受けるものではございません。","id":"exchange-025"},{"speaker":"南委員","kind":"確認","question":"その辺について伺ったのですけれど、もう一度、確認したいと思います。消費拡大が見込まれるときに、来年は消費税が１０％に増税されるという点で、そういう心配についてはどういうふうに受けとめているのか伺います。","respondent":"熊谷指導課長","answer":"１番目のご質問ですけれども、今回のこの改正とは異なるものですので、今の段階では影響ないです。それから２番目なのですけれども、非常に厳しいですけれども、公務員としていたし方ない部分もあるとしか申し上げられないと思います。","id":"exchange-026"},{"speaker":"南委員","kind":"意見","question":"やはりそういう状況の中で、本当にこれは、私としては承服しかねる。報告ということであっても、かなりひどいのではないかと思っていることはお伝えしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"渡部委員","kind":"質問","question":"どう考えても、「十何万、給料が下がります」、「はい、そうですか」とならない。今日は文教委員会ですから、１２月の賞与で一括、大変な人は大変だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-03","title":"平成２９年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"平成２９年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"所管ごとに違うのか、どういう聞き方がいいかわかりませんが数字的なものを教えてください。本来であればここに載せていただきたいと毎回言っているのですけれど、聞かないとわからない中身なので説明を求めました。","respondent":"横山品川図書館長","answer":"職員数ですが、品川図書館の職員数は３０名だけです。細かな数字、日々動いているような形になってしまいますが、ご用意できたらお届けするような形にしたいと思います。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"委託の部分は、ではわかったら数字で教えてくださるということで、ぜひ司書の方がどの程度なのかという中身もわかるのか尋ねました。","respondent":"横山品川図書館長","answer":"指定管理の条件としまして、半数程度以上、確保してほしいという要望を出しております。それに対応しまして、指定管理の提案で、５割、６割という提案をいただいておりますので、今現在もそれ以上を確保しています。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"とにかく司書を中核とした運営が大事であると求められているので、その辺はやはり大事にしていただきたい、確保してほしいと求めました。多分、品川区はずっとないと思うので、ぜひこの設置を求めたいのですが、いかがか尋ねました。","respondent":"横山品川図書館長","answer":"ご要望いただきまして、検討が適切かどうか、また品川区の土地柄に合うかどうかも含めまして検討中です。この間、地域の方とのかかわりも持っている状態なので、委員会という形が適切なのかどうかは引き続き検討していきたいと考えています。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問・要望","question":"平成２９年度は苦情の申し入れはなかったということなのですが、どういう構成で委員会が設置されているのか、中身を教えてください。やはりここの施設の特有なところが含まれているのですかね。","respondent":"高山子ども育成課長、廣田子ども家庭支援課長、吉田保育施設調整担当課長","answer":"私から、家庭あんしんセンターの表記上の、いわゆる独自事業としてというような注書きの補足をします。養育支援訪問事業につきましては… 各施設について苦情が上がってきたものに対し苦情解決第三者委員会というものが設けられていると、理事会等で説明されていました。メンバーにつきましては… 検討している最中でございまして、まだはっきり、いつからなるというところは決定している事項ではございません。","id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"機関ではないかと思っているのですが、まずそういう認識でいいのかどうかということを、１つ伺いたいと思います。","respondent":"横山品川図書館長","answer":"図書館の幾つかの機能の中で重要な一つだと思っています。","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"利用者協議会というのですか、土地柄必要なのかどうかということも含めて研究したいとおっしゃったのですけれども、設置を求めている。少なくとも２年にわたって、そういう指摘がされてきている中で、どういうふうに改善しているのかという認識を持っているのか伺いたいと思います。","respondent":"横山品川図書館長","answer":"利用者協議会については図書館法で一応、望ましいという形で表記されておりますので、品川区においても引き続き検討は進めします。先ほどご説明したように、それをわざわざ委員会に持っていくことが適当かどうかも含めまして、引き続き検討させていただきたいと思います。","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"早急にどういうものかというのを、できるだけ早期に利用者協議会を設置していただきたいということは、強く求めておきたいと思います。そういう中身で事業を運営していくべきだということを、所属長としてどういうふうに認識を持っているのか、改めてそこも伺っておきたいと思います。","respondent":"横山品川図書館長","answer":"平成２７年度の導入時点で既に、それであれば、指定管理を進めたという経緯があったように私は聞いております。先ほどもご説明しましたように、また、どういう状況で蔵書管理していったほうがいいのかというのを引き続き検討していきたいと考えています。","id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"働いている職員の図書に関する知識、司書の状況も６割から７割いるという話なのですけれど、ずっと長く指摘が出るような事態になっているということ。改善を求める点についてはきちんとレベルアップしていけるようにしていただき、指定管理にこだわらずに、やはり住民サービスというところをとって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"石田（し）委員","kind":"質問","question":"図書館ですけれども、これは利用者数が減っている中で、このシートには、その点に関して何も記載がない。地域に根づいた活動をしたりと、利用者数について各指定管理者たちはどのように捉えているのか、把握していたら説明を求めました。","respondent":"横山品川図書館長","answer":"全体の状況なのか、はっきり数値では確認できませんが、おそらくはＣＤから別の媒体へ移っているということのあらわれではないかと考えています。そういう意味で、図書の読み方が全然変わってきているというのを感じておりまして、そちらが原因と判断しております。","id":"exchange-037"},{"speaker":"石田（し）委員","kind":"質問","question":"このシートにも出てこないですし、図書館長のお話の中でも、研究をするというのにとどまっている。利用者のニーズをそこまで把握しているにもかかわらず、なぜ、いまだに検討段階にも入ってこないのか説明を求めました。","respondent":"横山品川図書館長","answer":"今まで所蔵していたというのと財産の考え方が違ってしまうので、やはり詳細な検討が必要ということがありますので、いまだ検討段階です。","id":"exchange-038"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"数字と合っているかどうかわからないですけれども、私のイメージでは、母子家庭というのは年々増えているのかなと思います。違ったら違うと言っていただきたいのですが、このシートを見る限りだとわからないので、担当課として把握されていたら説明を求めました。","respondent":"廣田子ども家庭支援課長","answer":"見学に来たのが３６件のうち３世帯で、入ったのが１件というような状況で、今後どうしていくかという課題があります。来館者数については、各種事業については利用は減っていないのですけれども、ふらっと訪れる人が少し減っているというところです。","id":"exchange-039"},{"speaker":"石田（し）委員","kind":"質問","question":"どこまで対応するべきかというのは、いわゆる指定管理の方たちと話をしていただきながら、工夫できるところは工夫してほしいと求めました。運営費が減っている理由というのが、もしあるのであれば、そこだけ説明を求めました。","respondent":"廣田子ども家庭支援課長","answer":"平成２８年度だと、３年に１度の定期点検であるとか、人がたくさん入っても入らなくても同じ金額は指定管理者に渡している内容です。ですので増減は、工事であるとか、特殊な、その年度にやらなければならない要因です。","id":"exchange-040"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぷりすくーる西五反田のほうでお尋ねしたいのですが、具体的にどこをどう検討し、どこに問題があって社会福祉法人化できないのか。認定こども園の前にそれができて、平成３１年に社会福祉法人化ができるのかというところの準備状況を含め、ご説明ほしいと求めました。","respondent":"吉田保育施設調整担当課長","answer":"今の具体的なスケジュール、社会福祉法人化に向けた具体的な内容の点のご質問かと考えています。平成３１年度からの社会福祉法人化を予定とご説明申しあげたところではありますが、現在、平成３２年からの社会福祉法人化を予定としています。","id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"質問","question":"平成３２年に社会福祉法人化するということは、もう社会福祉法人化の申請をしなければいけないのではないだろうかと思うのです。ということは、１カ月で社会福祉法人化ができるというのではないと思うので、現状の社会福祉法人化の準備はどういう感じなのかを伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"現在、社会福祉法人につきましては、新しい社会福祉法人ということで考えているところです。それと、社会福祉法人の申請の時期などにつきましては、今のところ、平成３１年度の中ほどで予定しています。","id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"認定こども園化を進めて、ぜひスピーディーにやっていただきたいという趣旨でお話をしています。プロポーザルあるいは指定管理の選考をしていくのかと思うのですが、そのあたりの来年度以降の指定管理の話についてご説明をほしいと求めました。","respondent":"吉田保育施設調整担当課長","answer":"現行のぷりすくーる、これで１５年目になりますけれども、指定管理、第３期目は今年度で終わります。第４期目につきましては、選定委員会を新たに開きまして、その中で選んでいくという形を、予定しています。","id":"exchange-043"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"この先どうなるのだろうといった面で、先が見えるような形で区も支援して、バックアップしてほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これはグループに分かれているから載せにくいのかどうか、次回からぜひ、ここに載せていただきたいという要望が１点です。先ほど職員の人数をお伺いしたら、品川図書館は３０人ということでした。","respondent":"横山品川図書館長","answer":"品川図書館で司書資格を持っている人は、実質１人になります。休職等で出入りが激しいものですから、申しわけないです。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"半分以上ですか、専門職がとても大事という意味で、ぜひ司書の役割をきちんと位置づけた図書館運営をしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（博）副委員長","kind":"質問","question":"だから、何が入っているかわからないものに関しては、食物アレルギーに関して何が起こるかわからないという点も考慮されているのでしょうか。その２点をお伺いします。","respondent":"熊谷指導課長、篠田学務課長","answer":"２点目のご質問でしたが、英語で日本の文化を紹介するということは、発達の段階にもよりますけれども、検討しております。着て終わりではなくて… グローバル給食につきましては、実施に当たりまして事前にさまざまな形で勉強会等を開いています。こういったアレルギー対応が必要な子どももいるので… 一番最初のご質問ですけれども、ＡＬＴについては、Assistant Language Teacherの略です。","id":"exchange-047"},{"speaker":"鈴木（博）副委員長","kind":"質問・要望","question":"ですから、その辺はしっかりと対応をよろしくお願いします。要望ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"南委員","kind":"質問","question":"グローバル人材のほうの背景の４点目に、すごく気になるところなので、どういうふうに捉えているか教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"楽なところを選んでしまう。挑戦していこうというチャレンジ精神といったものが、なかなか育っていない若者が多いのではないかというところが１つの要因ではないかと思われます。","id":"exchange-049"},{"speaker":"南委員","kind":"質問","question":"その辺はどういうふうになっているのかと、島国という表現がいいかどうかは別としても、本当に大事なのではないかと思うのです。果たしてそれがいいかどうか、言い得ているかどうかは別としても、教育委員会としてはどういうふうに見ているのかを教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"２年生から９年生まで９０.８％いるのですけれども、半数ぐらい、４５.６％というところがあります。４７.６％の子どもが、外国に留学してみたいと答えていますので、そういった底力を子どもたちにつけていくことが大事ではないかとは考えます。","id":"exchange-050"},{"speaker":"南委員","kind":"質問","question":"そうですね。やはり子どもですから、そこを本当に重要に考えているので、改めてそういう方向性もお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１年生と２年生、ＡＬＴの元気な先生のもとで、すごく活発なやりとりをやっていました。内容を教えていただきたいのと、どうやって探していらっしゃるのか、どこから来ているのかというのを説明を求めました。","respondent":"熊谷指導課長","answer":"１・２年生について、１・２年では学ばせたいということで、ＡＬＴをティーチングの相手としてお願いしています。これは非常に人気がありまして、私どもが面接を行って採用しています。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問","question":"ＡＬＴのさまざまな人種ということで、私が伺ったときは東南アジアの方だったのです。どういう授業というか時間帯、市民科もかなり入っていますが、どういう時間を使ってこういうものを取り入れているのか説明を求めました。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"オリンピック・パラリンピック教育ですが、全ての教科の中で行っています。品川区で言うと、品川区立学校教育要領に準じて、その内容と関連づけて行ってきております。 プログラミング教育におきましても、さまざまな教科の中で扱う場面があります。あるいは市民科の中でステップ５として、自分の取り組んだ内容を発表したり、そういった場面で使うような場合もあります。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問","question":"私たちの育った環境と違うので、やはりある意味では学校で誰もが触れられるというのはとても大事かと思いますけれども、苦手な子もいるのでしょうか。みんな、ついていけているのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"意図的に、無意識の段階からやっていて、とても私たち大人よりも子どものほうがうまいというのが正直なところです。比較的いろいろな場面で、教員も使いますし、子どもたちもグループで実際に触れるという場面はとても多いと感じているところです。","id":"exchange-054"},{"speaker":"つる委員","kind":"質問","question":"その教科や授業を行う目的観みたいなものというのを最初にきちっと理解していることが、学習意欲の向上にすごく大きいと思うのです。どういう目的観、授業の中でどういうふうに教員の方が上手に工夫して伝えているのかというのを、まず説明を求めました。","respondent":"熊谷指導課長","answer":"特に７年生から９年生に関しては、ただ繰り返し、それはしっかり板書をするように教員には伝えているところです。なかなか１・２年生のＡＬＴとの授業のときには、そういったことも含めて指導を行っていきたいと思います。","id":"exchange-055"},{"speaker":"つる委員","kind":"質問","question":"決算特別委員会などで活用をどういうふうにしていくのかと伺おうと思ったら、これは一般利用もある中で、非常にいい機会だと思いました。主だったもので結構なので、いわゆる品川区の伝統として児童・生徒が学んでいるものというのはどのようなものがあるのか説明を求めました。","respondent":"大関教育総合支援センター長","answer":"実際、本年度より各学校では、地域の方を招いて地域の文化と伝統について教えていただくなどというところも取り組みを始めたところです。","id":"exchange-056"},{"speaker":"つる委員","kind":"質問","question":"具体的な内容が欲しかったのですけれど、今のは多分、歴史みたいなイメージで私は理解したのですが、品川区の各地域でいわゆる伝統と言われているもの、どういったものを皆さんに伝えていただいているのかというのを説明を求めました。","respondent":"大関教育総合支援センター長、熊谷指導課長","answer":"歴史以外に、例えば地域の、連合体育大会で子どもたち全員で踊ったりというような取り組みもしております。そのほか、いろいろあろうかと思いますが、今すぐに浮かばず申しわけありません。ノリを使っているので品川巻き、それを英語で伝えるというようなことも、おもてなしの一つとしてオリンピック・パラリンピック教育で行っています。","id":"exchange-057"},{"speaker":"つる委員","kind":"質問","question":"ぜひ別の機会で品川区の伝統を、ちょっと具体的にいろいろ伺えればと思ったので、また改めてこれについてお聞きしたいと思います。どういうふうにしてやっていくのかということを含めて、どういう形で検証等をしていくのか、その辺を説明を求めました。","respondent":"大関教育総合支援センター長","answer":"実際にそういった対応力というところと、また別の課題があるのかもしれません。そのような意見も踏まえて、それぞれの各校の取り組みを今後、情報共有して、取りまとめてまいりたいと考えております。","id":"exchange-058"},{"speaker":"つる委員","kind":"質問・要望","question":"今ご答弁いただいたとおり、先ほど申しあげた、人間の心というのはプログラムしてやれるものではないわけですよね。本来の趣旨といいますか目的感をしっかり達成しつつ、そういったところにもきちっと対応した活かし方をやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"どのような評価がされているのかというのを教えていただきたいのと、ここでも出ている、改めてお聞かせほしいと求めました。もちろん物によって全然違うのだとは思うのですけれども、どういったマニュアルというか方針みたいなものがあるのか説明を求めました。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"それから、先ほどお伝えした４技能のテストの中で９年生で実施したスピーキングなのですけれども、珍しい状況ですとお声をいただいているところです。… そのほか、例えばプログラミング関係ですと、そこに加入していただいている企業というのが１つの目安になっております。情報共有をして… 本区開催・応援競技の３競技については、私ども指導課でご紹介して、そして予算もつけているところです。ですので、さまざま、そういった状況です。","id":"exchange-060"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"要は授業ではないところで、どうやってその子どもたちを教えていくかというところで、そういった部分というのはどのように考えているのでしょうか。それはさっき私が１つ言った、どういった習熟度別の、区としてやられているものがあれば教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"そうした中で、習熟度別といったご質問がございましたけれども、７・８・９年は習熟度別で、２学級３展開を中心に授業を行っています。１つのそういった苦手部分を克服する、あとは、どういったことでつなげていくのが望ましいのか研究してまいりたいと思います。","id":"exchange-061"},{"speaker":"石田（し）委員","kind":"質問","question":"初めの質問にもつながってくるのですが、いろいろな方が講師として来られる中で、やはり学校というのはいろいろ複雑なものがあると思うのです。１つのツールとして活用できるのであれば、その点は、いいものを導入してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"渡部委員","kind":"質問","question":"英語をしゃべることもできる委員の質問の後で英語のことを話したくないのですけれども、５年になるのですかね。それと、何年かやってきて、何か変更点があったのかというところを教えてほしいのと、これは１年間を通してではないか尋ねました。","respondent":"熊谷指導課長","answer":"変更点なのですけれども、７年生がわからないということがあって、ドロップアウトしていく人数が毎年２０人ぐらいいたのです。ですので、平成２９年度からはスタート時期を９月から翌年の７月までというふうに変更しまして、年間２５回にしました。","id":"exchange-063"},{"speaker":"渡部委員","kind":"質問","question":"先ほどの質問なり課長の答弁を聞いていると、聞いてわかるとおりですので、引き続きお願いしたいのです。私は優先するべきだという意味で、質問しようと思っているのですけれども、何か接続しているのであれば説明を求めました。","respondent":"熊谷指導課長","answer":"毎年１名ずつ、校長推薦で行かせておりますが、直接的にグローバル人材育成塾に入っている子どもを優先ということにはなっていません。あくまでも校長推薦という形で行っているところです。","id":"exchange-064"},{"speaker":"渡部委員","kind":"質問","question":"品川区はこれだけのことをやってきているわけですから、こういうプログラムもあるよみたいなのが、私は一緒でいいのかなと思います。これは答えは出ないでしょうから、意見として申し上げておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"なかなかキャリア教育をするのも難しいところがあるのですけれども、小学校でぜひそういった動機づけをしていっていただきたいという気がします。そういうイメージしかないので、本当にいっぱいあるのだということを教えていっていただけるとありがたいのですが、そのあたりはいかがか尋ねました。","respondent":"熊谷指導課長","answer":"市民科を中心としたキャリア教育の中で行っていくというのも１つだと思いますし、または非常に英語が好きで、夢を持って活躍しようとされている方。そうしたところで、まずは紹介していく、伝えていくということが重要であると考えます。","id":"exchange-066"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"やはり教えていってあげるといいと思うので、ぜひ、今お話があったようなところで進めていってほしいと求めました。企業のかかわり方で、聞き漏らしてしまったのですが、プログラミングの何に加盟している企業などにいろいろご協力していただいているのでしたか。","respondent":"大関教育総合支援センター長","answer":"今年度より２年間行うに当たって、プログラミング教育推進企業の企業体連盟というものを、東京都教育委員会が組織しております。そこに加盟していただいている企業です。","id":"exchange-067"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、その中で品川区でやられていると、品川区にある、現状、今、品川区にかかわっている企業が多くなるのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"品川区だけではなく、東京都内の企業が加盟されておりまして、区内に本社がある企業だけではありません。平成２９年度に、今回、東京都のモデルを受けるに当たって加盟していただいたという経緯があります。","id":"exchange-068"}]},{"id":"topic-05","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"職を求めていない人、中には、もうずっと落ちて落ちて、諦めて、４月１カ月に申請しなかっただけで待機児童から外されてしまうのです。これ自体を見直していかなければいけないという、大もとの、今、２点を私はすごく思っているのですが、この点は品川区はどう考えているのか尋ねました。","respondent":"大澤保育支援課長","answer":"待機児童ではないかというお考えですけれども、今、入園のご意思があって申し込みをされているとは見られないのではないかと認識しています。区として独自の数え方というのはできないものだと考えていますので、国の考え方、定義に沿って数えていくしかないと考えています。","id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問・要望","question":"分母は何の３割か、もう一度教えていただきたいのと、一人ひとり当たって確認しているのでしょうか。入れたら職場に復帰するという人は絶対含まれていないのか、そこのところを説明を求めました。","respondent":"大澤保育支援課長","answer":"不承諾者のうちの３割は、１園しか希望されていない方です。５月に申し込みをされた方は、入れればすぐに復帰したいという意思表示だと思いますので、その方たちは待機児童です。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問・要望","question":"仕事を求めている活動を休止している場合についても、５月に申し込んだ人だから、寄り添う支援をという求め方をしているのです。０・１・２歳の人数を教えてほしいのと、３,５５４人の中の０・１・２歳の希望の数、できたら数字を教えてほしいと求めました。","respondent":"大澤保育支援課長","answer":"申し込み数が２,９５９人、入園者数が２,３４７人、従って不承諾数は６１２人と予測しております。なお、新規園の開設ですけれども、０から２歳児の定員数は３８７人を予定しているところです。","id":"exchange-071"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今の教えていただいた数字によると、入れないお子さんが６１２人で、これの繰り返しをどう改善していくのかという立場にぜひ立っていただきたい。待機児童はゼロが続いていますという発言自体は、やはり実態に目を向けていないのではないかと思いますが、いかがか尋ねました。","respondent":"大澤保育支援課長","answer":"保育園の利用者数ですけれども、そういった意味では、認証保育所等と既存の施設を活用して対応していくことが必要だと考えております。","id":"exchange-072"},{"speaker":"飯沼委員","kind":"質問・要望","question":"定員より１２０％近くも入れている部分を考えると、子どもが減っても、よい環境で育てる。やはり子どもにとって最善の利益を求めていくという保育園が必要だと思いますので、質の保てる方向に行ってほしいと、これは意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"南委員","kind":"質問・要望","question":"２回だけなので、簡潔に質問させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"石田（し）委員","kind":"質問","question":"どうやって子どもたちを増やしていこうと言っているのだし、皆さん、保育支援課は感じているのでしょうか。その辺はどういうふうに思っているのかというのが１点と、保育園に子どもを預けている家庭というのは、現在でも約半数ぐらいですよね。","respondent":"大澤保育支援課長","answer":"５％以上の伸びがあったのですけれども、平成２８年から平成３０年は１７％前後で推移していて、もうここで高どまりではないかと思っています。保育園に入れないから、０歳で無理して復帰して保育園に入れるというようなことはなく、一番望ましい形だと考えております。","id":"exchange-075"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/971992?Template=document&Id=4956#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":81606,"voices":229}},{"id":"h30-20181030-5","meetingId":"h30-cm10","date":"2018年10月30日","dateIso":"2018-10-30","committee":"総務委員会","time":"午前１０時００分～午後 ４時５９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件整理しています。","topics":[{"id":"topic-01","title":"「議案審査」を行います。 第７４号議案、平成３０年度品川区一般会計補正予算","agenda":"「議案審査」を行います。 第７４号議案、平成３０年度品川区一般会計補正予算","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"建築課長に確認をとったら、この助成金は該当する方向でというお話を伺った中で、どうお考えになっているのか。なぜなら、これは２項道路も該当するという話になってくると、構造物ですから、壊せばセットバックしなければいけないわけです。","respondent":"秋山選挙管理委員会事務局長、品川財政課長","answer":"皆さんがそろいで持つバッグ、あと学校において出前模擬選挙というのをやっておりますので、それに使う本物の投票記載台を買う予定でおります。部局のほうで検討していくとは思いますが、太陽光パネルを設置するとき、同時に蓄電池も学校のほうで入れているような動きがあります。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"学校環境整備事業というのは今後、小学校、中学校、義務教育学校に、順次設置をしていくという解釈でいいのでしょうか。全部の設置が終わるのは何年を目途とお考えなのか、最後に説明を求めました。","respondent":"品川財政課長","answer":"今回の学校体育館の冷暖房化につきましては、基本的には区立学校全校を対象として、やっていく方向で考えています。改築校に設置するのに少し時間もかかったりしますけれども、おおむね２年から３年ぐらいで全校に設置していきたいと考えております。","id":"exchange-002"},{"speaker":"いながわ委員","kind":"質問・要望","question":"それもぜひ頭に入れて、学校改築なり、こういった空調の設置をしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"いつから検討を始めたのかということを伺いたいのですけれど、そしてどのような検討が行われて補正予算の計上につながったのか、伺いたいと思います。当時は考えておりませんという状況だったので、今回の実施に至ったことは歓迎していますが、その議論の経過をご説明ほしいと求めました。","respondent":"品川財政課長","answer":"コンクリートブロック塀等安全化支援のほうですけれども、先ほどもご説明したとおり、対応はとってきていた状況です。そういった経過のもとで、今回学校環境整備事業を補正予算で上げているです。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"パワーアップさせることは十分わかるのですけれども、生垣助成の方もしっかり継続していただきたいと思うのですが、この点伺いたいと思います。災害時の対応も含めて、エアコンの設置を進めていく必要があると思うのですけれど、その点のお考えを伺いたいと思います。","respondent":"品川財政課長","answer":"学校のほうを全校やっていくということで、今回補正予算を出しておりまして、ほかの施設についても今後検討していきたいと考えています。","id":"exchange-005"},{"speaker":"須貝委員","kind":"確認","question":"私は行わなければいけないと思うのですが、やっているのでしょうか、またやっていくのでしょうか。そういう意味でも早目に協力して改善してくださいと言うことも、私は進めるべきだと思うのですが、その辺について説明を求めました。","respondent":"品川財政課長","answer":"この石を除去しながら、ということで当初は考えていたのですけれど、なかなか効率が良くない。そして、個別にお宅に行って啓発をすることが大事だというところも十分認識しておりますので、その考えを持ちながらやっていきたいと考えています。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"今まで皆さんのご質疑を伺っていたのですけれど、だから危険なブロックかどうかを判断するところまで、この中に含まれるのか。その辺のことも今後、今後の見通しや電力規模はどれぐらいまで想定されているのか、その辺について教えてほしいと求めました。","respondent":"品川財政課長","answer":"安全なものまで壊して、また建て直すということはしませんので、その時点ではやる予定です。なかなか難しいところであると思います。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"こうして議事録に残る形で伝わっていくという感じでしょうか、いつの間にかほかの何かに紛れてしまわないようにしてほしいと求めました。とても求められていることだと思いますけれど、東京都の動きとも連動しながら、ぜひそこは検討してほしい。","respondent":"品川財政課長、小林施設整備課長","answer":"基金につきましては、当然こういうご寄附をいただいたということがわかる形で、今後使っていきたいと考えておりますので、よろしくお願いします。目視になりますけれども、確認はできると思いますので、よろしくお願いいたします。非常に難しいところがありますけれども、建築基準法の見方のパンフレットは建築課にありますので、それを見てある程度の判断はできると思います。","id":"exchange-008"},{"speaker":"吉田委員","kind":"意見","question":"何かその思いが、このはざまに落ちてしまうような気がいたしますので、ご検討ほしいと求めました。そのようにお伝えしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ブロック塀が危険かどうかというチェックシートが、というところをまとめて、改めてまたわかりやすく啓発をしてほしいと求めました。今後２０件埋まったということになれば、次の動きとしてはさらにまた上乗せで助成の追加できるのかどうか、いかがお考えか確認したいと思います。","respondent":"品川財政課長","answer":"今回の助成枠ですが、どれぐらい申請があるか見えないところでの２０件という枠ですけれども、また今後の状況を見て、その辺について予算をつけていくかどうか、考えていきたいと考えています。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問","question":"本当に４月にできるのか、わりと最近までそういう方たちへのお答えというのが、４月に開設ですということだったのです。人の手当もつけて４月開設を目指していて、わかる範囲でお答えいただければお願いしたいのですが、いかがか尋ねました。","respondent":"品川財政課長","answer":"利用者に対する件ですけれども、これは来月、説明会を行う予定で考えております。そういった部分で対応しているということで、今回、債務負担行為の追加を行うです。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"例えば事業者の事業的には、もう４月分から事業計画に入っていると思うのですが、そういうところまで考えられているというふうに理解してもよろしいか尋ねました。","respondent":"品川財政課長","answer":"事業者の人件費につきましては、これはまた今後、どのような方向でいくかは考えていきたいと思ってあります。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどやりとりがあったように、ご本人の気持ちをしっかり生かしていただきたいということと、金額以上の思いが私はこもっていると思うのです。そういう意味も含めて、しっかりと取り扱ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"その辺のこともぜひ配慮して、考えてほしいと求めました。結論としては賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-02","title":"」を聴取いたします。 まず、(1)「品川区長期基本計画策定委員会の設置","agenda":"」を聴取いたします。 まず、(1)「品川区長期基本計画策定委員会の設置","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"その点を伺いたいのですけれども、まず委員は全員で３１名程度ということですので、確保していただきたいと思っています。以上のことを一言でまとめると、時間と回数を増やしていただきたいと思っているのですけれども、いかがか尋ねました。","respondent":"大野計画担当課長","answer":"やはり委員会の時間は２時間程度のところで、可能な限り多くの皆様がご発言できるようにということで、調整してまいりたいと考えています。全部で９回で予定しておりまして、最終の答申で１回ということで、２回を予定しているものですけれども。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"次に、委員会傍聴について２点伺いたいのですけれど、１つは傍聴です。審議されている内容に関する資料を持ち帰ることができるようにしていただきたいと思うのですけれども、この点もいかがか尋ねました。","respondent":"大野計画担当課長","answer":"２点ご質問をいただきました。委員会運営の中で原則は決めていくことと考えていますけれども、こういったご意見をいただいたということで、検討させていただきたいと思います。","id":"exchange-016"},{"speaker":"中塚委員","kind":"提案","question":"事務局としての品川区からの提案として、そして資料の持ち帰りも認めるということを事務局の意見を挙げていただきたいと思うのです。事務局として先ほどの２点についてを、委員長含めて提案してほしいと求めましたが、再度いかがか尋ねました。","respondent":"大野計画担当課長","answer":"やはり一定程度、審議会その他をオープンにしていく、また資料もオープンにしていくという流れがありますので、そういったご意見をきちっと委員長、副委員長に、事務局としてお伝えしていくという形で、対応させていただきたいと思います。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"障害者の自立支援協議会も、傍聴が可能になってきましたし、そうすると関心を持つ方も増えてきますので、ぜひそのようにお願いしたいと思います。区内団体関係者が１６名程度ということですけれども、大体１６団体ぐらいを想定しておられているのか、その辺を教えてほしいと求めました。","respondent":"大野計画担当課長","answer":"区内団体関係者１６名程度ですけれども、前回の策定時、改訂時等を参考にいたしまして、大体の数をまず出した上で、できるだけ多くの関係者の方からお声を聞きたいということで、１６名程度といったところで現在調整しています。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問・要望","question":"今現在、どういう団体があるかという目で見ていって、いろいろな方に参加してほしいと求めました。その辺、ぜひご検討ほしいと求めました。","respondent":"大野計画担当課長","answer":"前回の策定は１４名で、今回は１６名程度にいたしましたので、必ずしも前回を踏襲したものではございません。幅広く声を聞くにはどの団体を選べばよろしいのかといったところも含めて、よく検討してまいりますので、よろしくお願いいたします。","id":"exchange-019"}]},{"id":"topic-03","title":"品川区将来人口推計結果（速報）について","agenda":"品川区将来人口推計結果（速報）について","exchanges":[{"speaker":"いながわ委員","kind":"確認","question":"平成３０年４月１日現在の数字を式に入れて、出てきた数字だと思うのですが、これは１０年に１回行うものなのか確認したいのですが。私は推計とか統計に詳しくないのですが、誤差が生じてくるではないか尋ねました。","respondent":"大野計画担当課長","answer":"今回、平成３０年で人口推計を行いましたけれども、前回行ったのが平成２７年に人口ビジョンというものを作成したときに行いました。平成２７年に行った人口推計から見ますと、今回の人口推計は人口が増加するといった形で推計しているというものです。","id":"exchange-020"},{"speaker":"いながわ委員","kind":"質問","question":"そういうものを決めていくものだと思うのですけれど、平成２５年のときに要は誤差があった、全然違ったわけではないですか。今回平成３０年４月１日のデータは、俗に言う将来値に当て込んで出てきた数値という、要は反映されているということでいいわけか尋ねました。","respondent":"大野計画担当課長","answer":"こういったものは全て最新の値を用い、誤差等の調整されて、新しいものを出しているという認識で結構です。やはりこういった人口推計を出すということは、将来の人口増といったものをしっかり見据えて、長期基本計画の策定をしてまいりたいと考えています。","id":"exchange-021"},{"speaker":"いながわ委員","kind":"確認","question":"今後の品川区はどうなるのだろうと、当たり前のことですけれど、確認の意味も含めてお願いします。","respondent":"大野計画担当課長","answer":"年齢３階級別人口推計も踏まえ、政策をどう打っていくのかといったところを、長期基本計画策定委員会の中でしっかり議論してまいりたいと思っているところです。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"そして、この人口推計、私の実感では調査のたびにピークの時期が先に、先に伸びていると思うのですけれども、その理由をご説明いただきたい。２０１８年の総人口に戻るのは、２０４８年よりも先のデータがあれば、ご説明ほしいと求めました。","respondent":"大野計画担当課長","answer":"そういった要素を加味して人口推計を行いますと、総人口のピークがだんだん後ろにずれていっているです。２０１８年の総人口に戻る年数は、はっきりいつということはわからないのですけれども、相当先であろうということは見込まれるところです。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"単純に３０代、４０代の人口のところから出てくると、計算上の問題なのでしょうか。そこだけ伺いたいと思います。","respondent":"大野計画担当課長","answer":"やはり２０４８年に関しましては、３０年後といったところまでなかなか、こうなっているというものです。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問・要望","question":"目黒線も３両編成が、今は７両、８両、それでもいっぱいになっている。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-04","title":"男女共同参画のための品川区行動計画等素案パブリックコメントの実施","agenda":"男女共同参画のための品川区行動計画等素案パブリックコメントの実施","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"区民の意見が言いやすい環境づくりを進めてほしいと求めましたけれども、この点、改めて伺いたいと思います。このプランの中でも位置づけて、具体化していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"翌年１月１８日に策定検討委員会を予定しておりますので、そこまでにはホームページ上で公表することができるかもしれません。この件に関しまして、こちら側の検討の段階を踏まえた報告ということは、なかなか難しいかと考えられると思います。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"こうした社会の変化にしっかり対応できるように、５年後の見直しのときにはさまざまな要素をぜひ加えていただきたいと、要望しておきたいと思います。共生という男女共同参画の理念はぜひ、長期基本計画にも位置づけていただきたいと思うのですけれども、現状においてはどのようにお考えか尋ねました。","respondent":"島袋人権啓発課長","answer":"初めて意味があるものと考えておりますので、来年度の４月に計画公表し実施する予定でおりますので、発信していきたいと考えています。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"私も第２回定例会の一般質問で、ぜひ今度の計画に入れてほしいということを要望しましたので、検討の結果。この名称だけがいろいろなところで使われていくようになることについて、大変危惧しておりますので、その辺についてお考えをほしいと求めました。","respondent":"島袋人権啓発課長","answer":"他区の計画を見ますと３年計画だったり、５年計画だったりするものがあります。私ども品川区は１０年の計画で、今後の取り組み等がわかるようなところを書きましたので、こちらもあわせて宣伝してまいりたいと思ってあります。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"それからもう１点、最低３週間でしたっけ、もう少し長くてもいいのではないかと思ったのですけれど。その期間について、お考えを説明を求めました。","respondent":"島袋人権啓発課長","answer":"平成２７年度に改定いたしました配偶者暴力対策等対策基本計画のパブリックコメントが、２週間という期間でした。１カ月という長い期間を設定しても、年末の忙しい時期なので、３週間とさせていただいているところです。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"１２月２１日から延ばしても、確かに年末になってしまうかもしれません。期間を長くとれない分、パブリックコメントの広報をぜひ強めていただきたいのですが、それについてお考えを説明を求めました。","respondent":"中元広報広聴課長","answer":"こちらはホームページ等も工夫させていただきまして、区民の方に周知が行き渡るように、続けていきたいと思っているところです。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"現状はどのようになっているのでしょうか。説明を求めました。","respondent":"島袋人権啓発課長","answer":"１１月１２日から２５日の女性に対する暴力をなくす運動も、昨年度はホームページを使ったり、いろいろ活動させていただいているところです。わかっていただくような発信の仕方、啓発の仕方を考えているというところが、今の現状かなと思っているところです。","id":"exchange-031"},{"speaker":"須貝委員","kind":"質問・要望","question":"相談したいというとき、身近に相談できる場所の確保、また区のほうも他の事業部とも連携して支援できるような、そういうことはなかなか難しいと思いますけれど、区民を助けるということで、動いてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"１１月１日から始まる健康ポイントが、フェイスブックに上がったとき、一気に増えたというお話も伺ったので、やはり効果があるのかなと思うのです。この１２月１日から２１日という、ＳＮＳの活用も効果があるのかなと思うのですが、いかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"ツイッターといったＳＮＳで広報させていただいたところ、そちらからご参加いただく方も多うございました。今後は今の委員のご意見を参考に、そちらでも発信していきたいと考えております。","id":"exchange-033"}]},{"id":"topic-05","title":"平成３０年職員の給与等に関する報告および勧告の概要","agenda":"平成３０年職員の給与等に関する報告および勧告の概要","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"ただ、区民感情と照らし合わせてみれば、公務員の給料は高いから減らして当然だという考え方もありますので教えていただきたいのです。徐々に上がっているという記憶はあるのですけれど、多分２回ぐらい上がっていたと記憶しているのですが、その辺も教えていただきたいです。","respondent":"黒田人事課長","answer":"説明の中で少し触れさせていただきましたが、この４月に行政系人事・給与制度の改正を行いまして、６つの階層に変えました。制度の切り替え時の勧告としてどうなのかという意味では、今、交渉が行なわれているというような状況です。","id":"exchange-034"},{"speaker":"いながわ委員","kind":"質問","question":"これは聞いていいのかわからないですけど、平成２６年度から４年間、ずっとプラス改定で来ていて、総額としてはどれぐらいプラスになったのか尋ねました。","respondent":"黒田人事課長","answer":"総額ということではちょっとわからないですが、単年度の改定率でいいますと、大体率にして０.１３％から０.１５％ぐらいということですので、微増で来ているという状況でございまして、マイナスからプラスに転じて、毎年少しずつプラス改定になっていたという状況です。","id":"exchange-035"},{"speaker":"いながわ委員","kind":"質問","question":"まず１点が、今回は景気、不景気で下げるわけではないではないですか。年間で１２万円減るというのは、いろいろな福利厚生もしっかりしている公務員ですから、うまく減らしたほうがいいのではないかと。","respondent":"黒田人事課長","answer":"少し改正した人事制度が目指している構成と違う中で、過渡期というところでは、そういう較差が出たというところが人事委員会の見解です。平均で１２万円でも、約３０万円近く減額になる階層の職員もいますので、そういった意味ではかなり厳しいという受けとめはしています。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"管理職と一般職に分けると、この平均の影響額というのは幾らになるのか、そこをご説明ほしいと求めました。それと、今回の人事委員会勧告について、特別区長会はどういう態度というか、コメントが発表されているのか伺いたいと思います。","respondent":"黒田人事課長","answer":"全体の平均の改定率はマイナス２.６％となりまして、係員のところでは平均でマイナス１.９％、改定率は０％です。主任ではマイナス３.１％、係長ではマイナス２.６％です。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"職員の等級というか、いずれにしても月１万円以上をこれから賃下げしていくわけですから、その生活への影響があるのは明らかだと思います。現時点では見通しを持つのは難しいとは思いますけれど、現在のところ労使の交渉具合はどういう状況なのか、ご説明ほしいと求めました。","respondent":"黒田人事課長","answer":"期末勤勉手当の基準日が１２月１日ということなので、１１月中に改正条例を提案申し上げるのですが、全く見通しが立たないです。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"例年ですと１１月中に妥結というのが、この間の傾向だったのかなと思いますけれども、内容が内容だけに、特別区長会と特区連との交渉になると思うのですけれど、組合からの要求に対して真摯に話し合いを、丁寧に進めるように、特別区長会にも働きかけてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"須貝委員","kind":"意見","question":"ですけれど、それはそれ、今回の人事委員会勧告に関しては、私はやはりきちんと受け入れるべきだと考えます。意見だけですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"疑問だと思うので、それは何かしら考えていただいて、区民の皆さんのためにもっともっと意欲を持つ職員の人材育成に向けてほしいと求めました。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"新妻副委員長","kind":"質問","question":"１点だけ教えてください。今回こういう人事委員会勧告を受けて改定された場合、退職金への影響というのはあるのかどうか。","respondent":"黒田人事課長","answer":"この勧告どおりに給与が改定されますと、退職金の算出方法は月例給掛ける支給月数という中で、定年退職の今、支給月数が４７.７月ですから、その月数だけ減ということになりますと、退職金には大きな影響があるのかなと認識しています。","id":"exchange-042"}]},{"id":"topic-06","title":"かむろ坂公園改修工事請負契約","agenda":"かむろ坂公園改修工事請負契約","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"工期は平成３１年３月２０日と書いてありますが、３月２０日に終わって、公園が一般開放される日と思っていいのでしょうか。それに間に合うようにぜひお願いしたいというのが１点です。","respondent":"立木経理課長","answer":"開設日に関しましては、３月２０日までに工事を全て終わらせた上で検査を受けて、全てが終了するというのがこの工期ということになっています。所管のほうから聞いておりますのは、３月２０日の工期終了日にあわせまして開設をするです。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問","question":"この公園は、できるだけ子どもたちの意見を反映して改修するという姿勢を持つことができないかなというのが、２つ目の質問です。都会にいるとなかなか木と触れ合う機会もないですから、木製のよさというのもやはり強調したいと思うところもあるのですけれど、いかがか尋ねました。","respondent":"立木経理課長","answer":"遊具の素材につきましては、詳細の資料がございませんのでわかりかねますが、今の委員のお話につきましては、所管のほうに申し伝えるようにいたします。","id":"exchange-044"},{"speaker":"吉田委員","kind":"質問","question":"資料には「洋式化およびだれでもトイレ」と記載されておりますが、洋式トイレとだれでもトイレなのか、どうなのか教えてください。だれでもトイレという以上、ベビーベッドは当然だと思いますけれど、ユニバーサルベッドの設置はあるのかも説明を求めました。","respondent":"立木経理課長","answer":"所管のほうから聞いてありますのは、洋便器化にあわせまして男子洋便器とだれでもトイレの設置ということで、オストメイト、ベビーチェア等を設置するというようなことで聞いてあります。","id":"exchange-045"},{"speaker":"吉田委員","kind":"質問","question":"トイレは１つですか。男女があって、だれでもトイレがあるということなのか、それとも１つのトイレが、本当に誰でも使えるという感じになるのか、説明を求めました。","respondent":"立木経理課長","answer":"大変失礼いたしました。男子、女子、それぞれ別のトイレに加えて、だれでもトイレがさらに設置されるということで、３種類という形になります。","id":"exchange-046"},{"speaker":"吉田委員","kind":"確認","question":"確認ですけれど、先ほどのご答弁だと、ベビー用はあるけれどユニバーサルベッドまでは難しかったということか尋ねました。","respondent":"立木経理課長","answer":"私が聞いている範囲では、ベビーチェアまでということで聞いております。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問・要望","question":"私も高齢者介護のほうの仕事をしておりますけれど、散歩先を探すのにまずトイレを確認することが、すごく大事なことなのです。もしご見解があれば伺いたいと思います。","respondent":"立木経理課長","answer":"今いただきました視点につきましては、所管のほうにしっかり伝えします。","id":"exchange-048"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それで新しくフェンスをつけるので、同じように多目的広場とキャッチボールという、両方できますよということでいいですか。安全面とか考えた上か尋ねました。","respondent":"立木経理課長","answer":"すみません、運用の仕方につきましては、私どもではわかりませんので、その件に関しましては所管のほうにお伝えいたします。","id":"exchange-049"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"今後、考え方としてそういう暑さ対策ということも、公園の中にしっかり取り入れて、設計を考えてほしいというのが要望です。ぜひ取り入れていっていただきたいと思うのと、そういうものをご検討いただきたいと考えていますが、いかがか尋ねました。","respondent":"立木経理課長","answer":"改修計画図にはないのですが、パーゴラも設置されるということになっております。暑さ対策につきましては、今いただきましたご意見をまとめまして、所管のほうに伝えします。","id":"exchange-050"}]},{"id":"topic-07","title":"ふるさと納税寄附金の返礼品追加（品川区限定シナモロールぬいぐるみ）","agenda":"ふるさと納税寄附金の返礼品追加（品川区限定シナモロールぬいぐるみ）","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"もしそうなると、これは地場産品というふうになるのですか。国の動向はもちろん見なければいけないですが、それはどうなのか尋ねました。","respondent":"伊東税務課長","answer":"我々の考えとしては、品川区がサンリオの許可を得てオリジナルにつくったものですので、そういう意味では大意の地場産品と考えているところです。","id":"exchange-051"},{"speaker":"いながわ委員","kind":"質問","question":"ぬいぐるみは、原産国証明ではないですが、何でつくられていますというタグがついているではないですか。半分に減るのかわからないですけれど、お考えほしいと求めましたが、どうか尋ねました。","respondent":"伊東税務課長","answer":"明確にだめだという話は総務省が示しているのですけれども、こういう形のものというのは別かなと、思っているところです。確かに、タグにどこでつくったかと明記され、商品自体を品川区でつくっているわけではございませんけれども、そういう考え方で進めします。","id":"exchange-052"}]},{"id":"topic-08","title":"品川区長・品川区議会議員補欠選挙結果","agenda":"品川区長・品川区議会議員補欠選挙結果","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"確認団体のポスターに張った証紙のことを今、それにも証紙を張るわけですから、時間を争うわけです。その中で、一回一回剥がすごとに、ペリペリ破れてきれいに剥がれないような状況はよろしくないので、紙質を変えてほしいということです。","respondent":"秋山選挙管理委員会事務局長","answer":"お伺いしたところによると、証紙を台紙から剥がすときのことですか。","id":"exchange-053"},{"speaker":"いながわ委員","kind":"確認","question":"再確認ですが、区長選挙のときは確認団体ということで、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"中塚委員","kind":"質問","question":"期日前投票なので、後半になればなるほど結構、混雑というか列をなしている状況で、何とかならないかというご意見を伺いました。後半になったら列で並んでいたという話も聞いたので、何か改善策を打てないものかと思うのですが、いかがか尋ねました。","respondent":"秋山選挙管理委員会事務局長","answer":"今回も混雑する可能性もあるということで対応はとったのですけれども、実際に最終日、土曜日の昼過ぎが一番混んでいたという報告は受けてあります。対応として考えているのは、設置レイアウトを変えて、こちらとしてもアイデアがありますので対応をとって。","id":"exchange-055"},{"speaker":"吉田委員","kind":"確認","question":"実際どうなのだろうと思い、こういうのがあるはずだから見に行ってね、確認してねというふうにお願いしたのです。見解があれば伺いたいと思います。","respondent":"秋山選挙管理委員会事務局長","answer":"あのＡ４判のものをどこかに張るということは想定していなかったはずです。それにしても、必要とされる方が使える状態に確実にするということで、次回はしっかり注意していきたいと考えています。","id":"exchange-056"},{"speaker":"吉田委員","kind":"意見","question":"私も記憶が定かでないのですが、たしか裏面には机の上に置くか、近くに掲示するようにというような表現があったかと思います。掲示されると確かに小さいので、やはり受付のところに置かれるのが一番正しいかなと思いますので、その辺は徹底をとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"}]},{"id":"topic-09","title":"の５の「その他」を行います。 まず(1)、所管質問","agenda":"の５の「その他」を行います。 まず(1)、所管質問","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"メモとか音声で記録とかをすると思われるのですけれども、それと実際に公文書とされるものの線引きについて、お聞かせほしいと求めました。","respondent":"米田総務課長","answer":"特にメモという定義はないのですけれども、議事録を作成した段階で、一定程度役割は終えるだろうというふうに考えてあります。それが最終的に、それはいわゆる公文書の範疇に入ってくるのではないかと、このように理解しているところです。","id":"exchange-058"},{"speaker":"吉田委員","kind":"質問","question":"公文書として扱うというような規定が、既にあると考えていいのか、その辺をもう一度お聞きします。","respondent":"米田総務課長","answer":"より正確にということでしたら録音して、それと実際に起こしたものを聞き比べて、それで扱うというようなことだろうと思います。もう必要ないということであれば、それぞれの所属の判断のもと、廃棄されていくものであろうと考えております。","id":"exchange-059"},{"speaker":"吉田委員","kind":"質問・要望","question":"誰々が確認したものを文書としていくとなると、情報公開の対象でなくなるということを、私たちはとても危惧しております。難しいかもしれませんが、ご見解があれば説明を求めました。","respondent":"米田総務課長","answer":"情報公開というのは、区としていわゆる公文書として残しているものに対して、請求があったときその具体的なものを特定して、公開していく、それが基本的であることは、今までも変わりございません。","id":"exchange-060"},{"speaker":"中塚委員","kind":"質問","question":"２種類、同じ議事録作成でどういうふうに、どういう物差しで分けているのでしょうか。そこをご説明いただけますか。","respondent":"米田総務課長","answer":"それは行政でも同じで、やはり録音してそういうものを残していく必要があろうかと思いますし、それは中身によってまちまちなのだろうと思います。必ずしも、その辺のところは所属の判断だろうということで、申し述べておきます。","id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/147246?Template=document&Id=2122#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":58736,"voices":200}},{"id":"h30-20181031-14","meetingId":"h30-cm10","date":"2018年10月31日","dateIso":"2018-10-31","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ３時４５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"改めまして、区有施設・公有地等活用に関することのうち、庁舎のあり方","agenda":"改めまして、区有施設・公有地等活用に関することのうち、庁舎のあり方","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"どうするのか、どうだろうか、新設に向けてこの委員会で討議するほうが行財政改革特別委員会のふさわしいあり方ではないかと思うのです。皆様、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"渡部委員","kind":"質問・要望","question":"品川全体のことを考えたときにどうなのかというのは、場所の選定を進めていただきたいという思いは、抱いています。ですから、経理課長からご説明いただいたことは、まさにそのとおりの話ですので、私たちとしましても、その話し合いはどんどん進めていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"松永委員","kind":"質問","question":"私たちの会派としても、こうした場で早い段階から話し合いを進めていくことはとてもいいことだと考えております。検討を進めていくとあるのですけれども、区民の意見を聞くということは、どのような方法でその声を拾っていくのか説明を求めました。","respondent":"立木経理課長","answer":"現段階では、例えば何か検討組織を立ち上げるところまで、内部での議論は詰まっていない状況ですけれども、ただ、さまざまな手法があると思います。さまざまな区民に声を聞く形、手法をいろいろな可能性を視野に入れながら、これから検討することになろうかと思います。","id":"exchange-003"},{"speaker":"松永委員","kind":"質問・要望","question":"区民がご利用になる施設になると思いますので、世田谷であった方法などをぜひ取り入れていただきたいと考えています。この庁舎がどうなっていくのか、そうした対策も入れていただければと思うのですけれども、いかがか尋ねました。","respondent":"立木経理課長","answer":"前面の１６３号線の道路が時間帯によりまして大変渋滞するということで、第二庁舎、お客様の駐車場の出口が詰まることは執務にも影響するという中では、例えば道路の導入路、地面へのマーキングは、警察など道路所管ともお話は引き続きさせていただきたいと考えております。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"一般質問で言ったように、１８年もありますので、どういう区庁舎であるべきかを議論していくことは必要だということ。詳しくは、また後ほど、うちの会派からも質疑します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"意見","question":"雑駁にはわかるのですが、イメージがつき辛いですけれども、複雑なレイアウトとあるのですけれども、区が具体的にどう思っているかを聞きたいのです。駐車場、駐輪場の不足、業務用エレベーター等の設備の不足というのは、どういうところからそう思われているのかを具体的に説明を求めました。","respondent":"立木経理課長","answer":"これから検討する中で、そういった場合には、一旦、動く場合の経費とか場所が必要になる部分も考えていきたいと思います。その有効活用等も図れるということであれば、非常に効率よくできるとの考えも含めて、今後のあり方のご説明をさせていただきました。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういった課題を明らかにして、区民も職員もみんなで納得した上で、こういう庁舎をつくっていくことが必要だと思います。引き続き、課題抽出、声を聞くところを徹底していただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"職員間で連携を図るにしても、渡り廊下を考えただけでも距離があるわけですから、トータルでみれば、本当に無意味な時間を過ごしている。一言だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"大沢副委員長","kind":"質問","question":"先方のあることですけれども、そんなことも行政内部ではイメージとして抱かれているものなのですか。どうなんか尋ねました。","respondent":"立木経理課長","answer":"限られたスペースの中で大変厳しくなってきている中で、新しい庁舎なりができるまでは、ある程度の機能分散等も必要なのかと少し考え出しています。そういったものも１つ、検討材料として、いろいろな可能性を含めて検討をするべきだろうとは考えてあります。","id":"exchange-009"},{"speaker":"こんの委員","kind":"質問","question":"地方は車社会ですから、駅から離れて駐車場が確保できているかというと、品川区の庁舎ではなかなかそれも難しかった。ひろまち再開発を１つ視野に入れながら一緒にやるというところでは、こうしたものはもう既にお考えとしてあるのか、お考えを説明を求めました。","respondent":"立木経理課長","answer":"広町のまちづくり計画の検討が進んでいる中では、まちにとって望ましいのかという部分をしっかりと考えた上で、計画を進めていく。当面、区有地の建物等の再配置計画につきましても、そういったことをいろいろ勘案しながら検討をするという方向で、今、進めてあります。","id":"exchange-010"},{"speaker":"こんの委員","kind":"提案","question":"確かに、これまで一般質問でこの課題について何度か質問に上げられているたびに、改めて確認をさせていただきました。こちら側から提案したのをどうですかと言うのもそうですけれども、区民の方からの提案によって、いかがか尋ねました。","respondent":"立木経理課長","answer":"庁舎の建て替えとなりますと、かなり大きな事業になりますので、そういった面では、私どももご意見に応えられる形で、アンケートを含めて、これからいろいろ手法は検討させていただきたいと思います。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"こういった方々は、初めて行く場所では、まずトイレの場所を確認してから行動すると伺うのです。多く見られますが、こうした配置も重要かと思いますけれども、いかがか尋ねました。","respondent":"立木経理課長","answer":"今いただきました３点、新しく庁舎を検討するにあたって必要とされる機能の項目として、そういったお話も検討させていただいた中で。現段階でどうするということはお答えできないのですが、何が必要なのかを取り上げた上で、アンケートなどを進めてまいりたいと思います。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"今、ここで我々が個別にどんどん出したら、山ほど出るのではないですか。終わらないと思うのですが、いいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"防災センターの３階ですとか、学習会をやったり、そういうときに開放されていないことに対する改善の要望も届いているのです。いかがか尋ねました。","respondent":"立木経理課長","answer":"これからも非常に重要になってくると考えていますので、そういったものも含めて、検討の１つの材料とさせていただければと思います。","id":"exchange-014"},{"speaker":"安藤委員","kind":"提案","question":"その上で、再開発主導での庁舎建て替えはやめるべきと質問して、まちのシンボルとなる庁舎とは超高層を目指すということなのでしょうかと伺いました。この区長の答弁について、どういう意味なのか伺いたいと思いますとの意見を述べました。","respondent":"立木経理課長","answer":"会議体等のこれからの検討組織につきましては、やっとこれから検討を始めようですので、検討させていただきたいと思っています。一定程度、そういったことで答弁していますので、そういうことで検討を進めていくことになろうかと思います。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、区長答弁ですけれども、庁舎のあり方は区にとっても非常に重要なことで、再開発と切り離して考えることを求めたいと思います。こうした意見を述べさせていただいた上で、それぞれ現時点での区の考え、答弁を求めたいと思います。","respondent":"立木経理課長","answer":"再開発にはそれぞれ条件がございまして、今回はそれには合っていないということで、現段階で再開発ではないという答弁をさせていただいたところです。そういった形で答弁していますので、１つの方向性としては、そういったことで検討をすることになると思います。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"純粋に自治の拠点、区民の皆様への行政サービスの提供場所、そして防災の拠点での検討を求めていきたいと私は思います。超高層ではなく、停電時などでも円滑な防災活動ができる低層にするべきと私は思いますけれども、区の考えを伺いたいと思います。","respondent":"立木経理課長","answer":"超高層ビルがだめということではないとは思っておりますが、防災拠点として、より高い防災機能を持つ庁舎として、どのような形がいいのかも含めて、検討課題とさせていただきたいと思います。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"改めて意見を述べさせていただいた上で、こういった防災面からも庁舎は低層にすべきだと思いますが、いかがでしょうか。伺います。","respondent":"立木経理課長","answer":"防災拠点としての機能は、役所の建物としては非常に重要な役割の１つです。品川区が今、総合的に判断をさせていただいた中で、計画を進めていくように検討していきたいと考えております。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"そういった理由から低層型を選択している先進区があるわけですから、私は、防災面から低層型にすべきだと思いますけれどもいかがかと伺ったのです。考え方をもう一度、伺わせてください。","respondent":"榎本総務部長","answer":"そういうさまざまな機能を検討しながら、最終的にどういう形にしていくのかが必要と思います。機能を全部詰め込んで、そういうことも総合的に考えながら、最大公約数的なものを選択せざるを得ないと考えています。","id":"exchange-019"},{"speaker":"安藤委員","kind":"提案","question":"先ほどから提案している区民の皆様も入った検討会を立ち上げて、ぜひ、一緒に検討をしていってほしいと求めました。区民の関心は高いと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"高橋（伸）委員","kind":"質問","question":"この数年の間にやらなければいけないことがあるのかどうか。お聞きしたいと思います。","respondent":"立木経理課長","answer":"昨年度ベースですと、大体、補修の部分で年間２,０００万円以上の費用がかかっています。ご利用の皆様にとってはご不便がかかる部分もありますので、そういったことも考えながら検討していかないといけないと考えております。","id":"exchange-021"},{"speaker":"こんの委員","kind":"質問","question":"私は、区民の方が行きやすい、立ち寄りやすい庁舎のあり方は非常に大事と思うのです。その点についてはいかがお考えか尋ねました。","respondent":"立木経理課長","answer":"まちの方にも愛されるような建物となるようにといった面も今後、新たに検討するのであれば、加味されるべき条件だとは思います。そういったことも含めて検討をさせていただければと考えています。","id":"exchange-022"},{"speaker":"こんの委員","kind":"質問・要望","question":"必要だから来る方ばかりではなくて、必要ではないのだけれども、庁舎に何か情報を求めて、何か情報があるかと思って来る方もいる。まちのにぎわいとともに、ソフト面なのかハード面のレイアウトなのかは両面と考えるのですけれども、何かございましたらお願いします。","respondent":"立木経理課長","answer":"区がどのようなサービスをさせていただいているかを知っていただく部分と、あとは、来ていただくことで私ども職員が知ることができる部分もありますので、ソフト、ハード両面で、立ち寄っていただける空間も検討材料として入れさせていただければと思います。","id":"exchange-023"}]},{"id":"topic-02","title":"国・都有地等の有効活用","agenda":"国・都有地等の有効活用","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"林試の森公園は今は公有地ということで、私たちも、一般質問等々、何度も区民の要望を実現させていく場にということを求めてきているのです。３、４階建てを想定し検討と書いてあるのですけれども、ここはマックス何階まで建てることができるのかを伺いたいと思います。","respondent":"柏原企画調整課長","answer":"４階建てとしておりますのは、今後の検討のところはあるのですけれども、更地ということで何もない状況になっています。先ほども申し上げたように５階建て程度はいくだろうと想定はありますが、引き続き、区の行政ニーズも考えながら検討できればと思ってあります。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それはもうその方向で検討が進んでいるということでいいのでしょうか。定員が２９名以下となってくると思うのですけれども、それぞれの定員なども、もし検討をされているのであれば教えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"先日の本会議におきましてもご答弁申し上げたところでございまして、今、委員がご案内いただいた内容の部分についての検討を進めてあります。その辺は１つ、定員等を考えていきたいということで、今はそのような感じです。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"２３区で最低を抜け出す一歩にしていただきたいというところでは、さらに多くのベッドを確保できる特養ホームにしてもらいたいというのが思いです。どういうものにしていくか検討を進める中でというお話もあったので、グループホームもできないかと思うのですけれども、区の考えを説明を求めました。","respondent":"柏原企画調整課長","answer":"ですので、考え方としては、地域の交流とか防災を基軸に置きながら、その中で行政のニーズに対応できる施設をということです。施設構成を検討はしておりますが、確定している部分ではありませんので、どういう形がよいのかは検討を進めながらといったところです。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"検討されている福祉施設というのは、本当に区民も求めているものですし、こうやってひとまずつくっていくことになったのはうれしいのです。こういうところで１つ、２３区で最低レベルの障害者福祉ですので、ぜひともグループホームを要望していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"ですから、住宅街における消防署、出張所の設置は住民の理解を得ながら進めるべきだと思います。今の時点で移転の計画や大まかな配置などはかたまっているわけですから、また、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"その際、当然、ここには何があるというお話がありますので、区道の拡幅も含めた説明会、話が地元の方には公の形で出てくると思います。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうした機会の中でも、こうした説明ができるような体制をとっていただくように都にも働きかけてほしいと求めました。そうした独自の説明会も開くよう求めてほしいと求めましたけれども、この点について、最後にお伺いします。","respondent":"柏原企画調整課長","answer":"都市計画の説明会、解体に対する説明会等々がありますので、そういった機は必ず捉えるようにと考えています。個別の説明会等々につきましては、そういったご意見があるということで、消防の方には改めて伝えさせていただきたいと思います。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/237826?Template=document&Id=6060#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":26720,"voices":72}},{"id":"h30-20181101-18","meetingId":"h30-cm11","date":"2018年11月1日","dateIso":"2018-11-01","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ３時０７分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件整理しています。","topics":[{"id":"topic-01","title":"の２の特定事件調査","agenda":"の２の特定事件調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そこだけ教えていただきたいなと、スタッフがどのようにいるのかということがわからなかったので、教えていただきたいということが１つです。一致できたらそういう方向での議論が当委員会でできたらいいかなと少し思っています。","respondent":"いながわ委員長","answer":"基本的に山口氏にご説明をいただいて、トレーナーが１人いらっしゃったのと、受付に２人女性がいたのが本日でした。もし理事者のほうで何かそういったことを個人的に聞かれていればと思うのですが、特になさそうですね。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"トレーナーらしき人が１人いらっしゃったけれども、あそこの施設で働いている方ではなくて、ちょっとそういうことを知りたかったなと思うのです。もう少し施設を中身的に知りたいなと思ったのが１つで、そういうことも含めた情報を提供していただけるようにお願いをしておきたいと思いました。","respondent":"いながわ委員長","answer":"あくまでも障害者スポーツ、車椅子スポーツなどの強化選手の強化をするという説明を現地でも受けて、利用できる人も限られている。ホームページは開設していると説明がありましたので、ぜひ後ほどご覧いただければと思いますので、ご理解いただければと思います。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１つ理事者の方にお伺いしたいのは、あそこを宣伝というか、広報の場として何か使用をされているのかどうかというところを伺いたいのが１つです。この２点、伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"東京２０２０大会に向けても、日程的なものもあると思いますが、そちらはこれからいろいろ考えていきたいとは思っております。その東京２０２０大会以後にどうなるかというのは、情勢を注視しながら、何か行動に移していきたいと思っています。","id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"我々の会派でずっと政策要望でも出させていただいているのですけれども、障害者スポーツセンターというものが、今全国の中で少しずつできてきた。「いいですよ、健常者の国立オリンピック記念青少年総合センター、あのオリンピックセンターというのは国立なわけではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問","question":"やはりそのような企業チームを持っているところや上場企業というのは、全部今そういうものをやろうとしているではないですか。考えを持ってやれば私はできると思っていて、その辺の意識がないと多分できないと思うので、その辺の感覚だけは教えてほしいなと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"とりあえず東京２０２０大会までは、交流というものは非常に大切ですので、そういう道があるのかどうか今後模索をしていきたいなと考えています。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"２３区は１つ２つか、もう１つはやろうとしてやらなかったけれども、笹川スポーツ財団とつき合いができるではないですか。障害者の部分でそのようなものからスタートしたのなら、やったほうがいいのではないかなと思うのですけれども、その辺のところはどうお考えか尋ねました。","respondent":"池田スポーツ推進課長","answer":"一応来年もこのような障害者スポーツチャレンジデーのようなことはやりたいと考えているところです。よろしくお願いします。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もうすぐ２年とか過ぎるわけですから、その間におつき合いができるようになれば、いろいろな話も品川区はしやすいのかなと。それは気持ちがないとできないので、それは行政の立場でぜひやっていただきたいなという意味で申しあげました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"大倉委員","kind":"質問・要望","question":"１個、「あすチャレ！このようなものとの連携、取り組みを一緒にやっていくというようなことはできないのかなと思っているところなので、何かあればお願いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"School」、車椅子バスケや陸上関係等のいろいろな取り組みがあるということです。パラの競技者を呼んで個別では行っていると聞いておりますが、こういった日本財団がやっているものもまたご紹介しながら進めていけたらと思います。","id":"exchange-008"},{"speaker":"大倉委員","kind":"質問","question":"１点、これは質問なのですが、つながりがあるといいのかなと思います。アスリートとしての道筋もあるのだというような、その辺は多分うまく連携できていると思うのですけれども、どのようにされているのか説明を求めました。","respondent":"池田スポーツ推進課長","answer":"青少年、支援金としまして１回当たり１万円の支援をさせていただいている制度が、まず１つあります。水泳大会のほうにも参加することができますので、そういったいろいろなところでご参加いただけるようなご案内はさせていただいているところです。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"ですからやはりこれから区の施設でも、当事者の声をきちんと聞いてバリアフリーを進めていってほしいと思ったのと、何か少し残念だなと思ったのです。一緒に呼びかけたり、あと子どもたちが参加できるようになどできたらいいなと思ったのですけれども、どうか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"バリアフリーのことを考えるときには当事者の声をきちんと聞いて反映しながら今までもやってきましたし、今後もさらにやっていきたいと考えています。これからは向こうから要請があったり、私どもで気づいたときはうまく連携がとれるところはとっていきたいと思います。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"あれは世界に１６人しかいないレゴビルダーのうち、日本でたった１人のレゴビルダーの方がつくったものだそうです。何かそれだけでもすごいと思ったので、いろいろな人に見てほしいなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"今までも周知をどのように行っているかという質問をしたときに、ぜひこのような機会があるのだということを伝えていただきたいと思っていて、団体に属していない方たちにも伝わる工夫を何か今されているのか伺わせてください。","respondent":"池田スポーツ推進課長","answer":"最近では東京都に障害者用のイベントのホームページもございましたので、そちらのほうにも掲載を依頼いたしまして、載せられるものは載せているような形になっています。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひその当事者の方たちに届く周知の方法というものを、今もされているのですけれども、それ以上にもっと広がるように、ぜひ、考えていただきたいし、工夫できたらと思っている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"この間も出ている普段の練習というのでしょうか、みんなで楽しもうよという、そのようなレベルになっていると思っているのです。４年か５年ぐらい続いているのですけれども、どのようになっているのかということをご報告いただけたらと考えていますので、その２点です。","respondent":"池田スポーツ推進課長","answer":"来年度につきましても、これを踏まえてまた新たなことを考えていきたいと思っているところです。大変申しわけないのですが、私ども東京都のほうに要望はさせていただいているというところまでです。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"そういう状況、条件、環境をさらに整えていただけないかというところは要望をしておきたいと思います。城南何区かで一緒になって取り組むということも含めてやっていただきたいと思っているのですけれども、最後に伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"今の施設につきましては、引き続き東京都のほうに要望するようにしてまいります。区のできる限りのところで、これからも障害者のスポーツについていろいろなことを企画していきたいというふうに考えているところです。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問","question":"質問ではないのですけれども、ふれあい作業所についてです。公園清掃についてなのですが。","respondent":"いながわ委員長","answer":"その写真が載っているのであえてこのパンフレットをお持ちいただいたというところで、ふれあい作業所で障害をお持ちの方でもしっかりクラブ活動をやっていますというご説明をしていただいたので、クラブ活動や障害者スポーツの推進に関してお願いします。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問","question":"その現在の区の考えている課題について伺いたいと思います。企画の段階から当事者の参加を位置づけることで、より参加しやすいものになっていくのではないかと思いますが、いかがか尋ねました。","respondent":"池田スポーツ推進課長","answer":"そして、特に大きな会場でやる必要はなく、そこをまずはやって体を動かす習慣をつけていただくということだと思っているところです。そのような形で障害をお持ちの方ができるものは当然そうですし、また楽しんでいただけるもの、そういったものを考えながら教室を企画しています。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"その中で、今の課題としては、それをどうすればより進められるかというところの課題の意識をぜひお聞きしたいと思います。今具体的に答弁がなかったように感じましたので、ぜひ企画のときから当事者の方の意見を入れていくというところをお願いしたいと思います。","respondent":"池田スポーツ推進課長","answer":"そちらについては障害者の対象を毎年変えながら競技を行っているということでご説明をさせていただきました。今後の課題としましては、まず先ほどから申しあげておりますように、障害をお持ちの方にスポーツをしていただき体を動かしてもらうです。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"当事者の方へのアンケート調査などを行っていくことが、より具体的につかむ力になるのかなと思いますが、その実施について伺いたいと思います。障害者のスポーツ振興計画を策定し、普及啓発をさらに推進していくことが必要かと思いますが、いかがか尋ねました。","respondent":"池田スポーツ推進課長、安藤文化スポーツ振興部長","answer":"区ではただいま長期基本計画を策定しています。そのような大きな計画の中で、こういったことやアンケート等を含めて、障害者の方のスポーツについて研究していきたいと考えています。 そして特別支援学校なり、いろいろな情報を通じまして、参加を求めたり、拡大をしたりしていこうと。これは強力にスポーツ推進委員をはじめ、我々と協力してやっているところです。","id":"exchange-019"},{"speaker":"のだて委員","kind":"意見","question":"ぜひ強力に進めるためにも、長期基本計画でも計画するというお話でしたけれども、やはり具体的に進めていくには障害者スポーツ振興計画、仮にですが、こういったものをつくっていくということが力になると思いますので、これは意見として言っておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そのような中で、例えば、そのようなものをきちんと理解をしてくれるチームのようなものを紹介していただけないでしょうかというご相談を受けて。例えば同じ質問が区民の方から来たときに、今だったらどのようにお答えになるのか、もう一度お伺いをしたいと思います。","respondent":"池田スポーツ推進課長","answer":"情報については多少ですけれども、持っているものはあるのですが、ただ、お答えできるほどの情報量ではまだないということが事実です。その辺については今後もいただける情報というものは集めて、お答えできるような形にさせていただきたいというふうに考えているところです。","id":"exchange-021"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ですから、やはりそのような、精神論ではないですけれども、そのような思いを持っていただきたい。繰り返しになってしまいますけれども、何年か前にそれを質問したので、また改めてご要望させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問","question":"ちょっとしたボール遊びなのか、ボール蹴りなのか、何かそのようなものがあるではないですか。サポート体制はどのような人がいますよとか、１つの例だけでいいから、そのようなお勧めを説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長、松山障害者福祉課長","answer":"その中でホッケーのミニゲームを、本当にミニゲーム、２対２で小さなゴールをつけてということで行いました。スペース的にも狭いところでもできますし、器材も貸し出しできますので、お勧めです。 団体ということですから、恐らく委員おっしゃられるとおり、育成会のほうもご自分たちの団体で運動会をやっておりますので、そういった運動会でやられるような種目でしたら、ご一緒に活動できるかと考えています。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もしあるのであればどのようなスポーツで、何団体ぐらいあるのかということを把握されていたら教えてほしいと求めました。そのような団体に対しての支援の制度というものは、区のほうとしてはあるのかどうかについても説明を求めました。","respondent":"池田スポーツ推進課長","answer":"障害をお持ちの団体の活動ですけれども、定期的に活動しているものについては、特段、私どもでは把握していないというような状況です。４カ月前の抽選という形でやっておりますので、そういった把握の仕方をしているところでございまして、そこまでは把握していないところです。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ区としても把握もしてほしいと求めましたし、ぜひしていただきたいと思うのですけれども、その点１つお聞かせください。そのようなところにこの障害者スポーツというものも位置づけていただいて、その点についてもお聞かせほしいと求めました。","respondent":"池田スポーツ推進課長、松山障害者福祉課長","answer":"障害者のお子さんの水泳教室について、貸し切りの支援ですけれども、個人利用の場合に障害をお持ちの方は無料ということで今やっているところです。料金設定した金額もありますので、そこまでということでよろしくお願いします。 その中でスポーツについてという項目、あるいはどのようなことを聞くかということにつきましては、また関連部署と協議しながら検討を進めていきたいと考えています。","id":"exchange-025"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"先月２０日の日に、障害を持った方と障害のない方がいらっしゃったのかなと思うのですけれども、その一般の方にはどの程度アピールをしたのか。殊に子どもさん向けに考えたときに、学校などにそのようなことをアピールしているのかなということを感じたのですがとの意見を述べました。","respondent":"池田スポーツ推進課長","answer":"実を言いますと、１０月２０日の日はあそこの近隣の学校はたまたま運動会と重なってしまいまして、一般の方というのはちょっと少なかったです。今後は気をつけてします。","id":"exchange-026"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"それを感じたのです。何かもったいないなと思って日程調整をどうされているのかということが疑問だったので、小学生、ぜひこれからもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"伊藤委員","kind":"確認","question":"品川区のお考えを確認したいのが、恐らく陸上競技をはじめとして、いろいろなスポーツをやりたい障害者の方がいらっしゃる。だけれども、それからこれからどうそれを展開していくのかということについて説明を求めました。","respondent":"池田スポーツ推進課長","answer":"これは研究材料といいますか、企画するところであると考えているところです。そちらのほうにも載せるような形で、力を尽くしているといいますか、やっているところではあります。","id":"exchange-028"},{"speaker":"伊藤委員","kind":"質問・要望","question":"全ての方々のご要望をかなえることが理想ではあるのだろうけれども、介助のことやら、それから使う用具も当然変わってくるのでしょうから。新たにこのような企画を展開していくとか、そのことを品川区独自で考えてもいいのではないかと思ったのですが、いかがか尋ねました。","respondent":"池田スポーツ推進課長","answer":"短期的なものにつきましては、それぞれ私ども毎年目標を立てているところですけれども、長期的なものにつきましては、ただいま長期基本計画を策定しているところでございまして、そちらの中できちんとやっていきたいというようなことは考えているところです。","id":"exchange-029"},{"speaker":"伊藤委員","kind":"質問・要望","question":"パラリンピックがこれから開かれていくと、より多くの方々がこのようなスポーツをやりたい、もしくはそれに出たい方がたくさん出てくる可能性がある。さまざまなワークや制度を検討していただいて、そのような方々の意向がくじけることがないような体制をつくっていただきたいというお願いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"つる委員","kind":"確認","question":"障害者スポーツ。当然２０２０年に向かい、過去にそのような方がいらっしゃったかということの確認と、ちょっと確認で説明を求めました。","respondent":"池田スポーツ推進課長","answer":"以前は品川区に住んでいらっしゃいましたが、品川区から越してしまったので、現在のところパラのアスリートの方は把握していないところです。実を言いますと、そういった選手がいることは、全国大会出場支援の申請というもので把握しているところではあります。","id":"exchange-031"},{"speaker":"つる委員","kind":"質問・要望","question":"そうしたところの連携などということがもう少ししっかりしているといいのかなというところで、今お聞きしたのです。なければぜひそういう連携だとかというところをしっかりとやっていただきたいと思うのですが、このあたりについて説明を求めました。","respondent":"池田スポーツ推進課長、安藤文化スポーツ振興部長","answer":"私どものほうもパラアスリートに対する支援というものについては、そこまでやっていなかったのが現状です。そういったことで支援なり… 品川区内にそのようなアスリート、パラのアスリートではなくても障害者アスリートがいるか、そういうものをとにかく見つけようとして発見する。","id":"exchange-032"},{"speaker":"つる委員","kind":"提案","question":"そういったものをやってみてはどうですかと提案したところ、前向きに検討しますと当時の課長からのご答弁をいただいて２年がたつのです。ですから、まだオリンピックまで１年ちょっとあるので、その辺の経過などあれば説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"テレビ等で非常に興味深いお話をしていらっしゃるところです。これからも啓発講演会等行いますので、その辺も含めまして、皆様に興味を持っていただけるような企画に活かしていきたいと考えています。","id":"exchange-033"},{"speaker":"つる委員","kind":"意見","question":"ぜひよろしくお願いしたいと思います。これはこのオリンピック・パラリンピックの視点からも絶対できると思うので、ぜひよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"}]},{"id":"topic-02","title":"オリ・パラ公式ＳＮＳアカウント新設","agenda":"オリ・パラ公式ＳＮＳアカウント新設","exchanges":[{"speaker":"大倉委員","kind":"質問","question":"品川区のほうでもあると思うのですけれども、そこにこのように新しくＳＮＳ始めましたよというようなものは、出ているのでしょうか。出ていればいいのですけれども、出ていなかったら出したほうがいいのではないかと思ったのですが。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"区の特設のアカウントのほうですね。そちらのほうではまだ載せていなかったと思いますので、ぜひ宣伝ということでお願いしたいと思います。","id":"exchange-035"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"巨大手形アート、たしか前に聞いたところですと５,０００人を目指すのでしたか、ギネスですからね。それでそのめどはつきそうなのかどうかというところが心配で、大丈夫なのか、ちょっと質問させていただきました。","respondent":"立川文化観光課長","answer":"現在、この世界記録ですけれども、韓国のソウルで４,６７５人だったと思うのですが、そういった記録があります。通常これだけの大々的なイベントを実施いたしますと、今のところ新記録達成につきましては楽観しています。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これは冗談ですけれども、ギネスということで、たしかこれ職員の方の発案ということで聞いていますので、しっかり達成をしていただきたいなと。文化プログラム、オリンピック・パラリンピックの大きな大きな、１つの大きなステップになるイベントだと思いますので、ぜひ期待をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"石田（秀）委員","kind":"確認","question":"以前オリンピアンなどを呼んで、こういうものをやるときというのは、映像を使って何とかアートをやっているではないですか。名前を忘れてしまったのですが、このようなことが今できるようになったのか確認だけしたいのです。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"委員の今のお話は記録映像を流してということだと思います。恐らくそれは、やはり大会組織委員会なりに確認をとって許可を得ないと、できないような仕組みになっているというふうに認識しております。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問","question":"公園にいる方たちが中で何をやっているか知らず、中の方たちも来てほしいのだけれども、公園にいる方たちには声をかけられない。何といいますか、やはり中のイベントの様子が全然見られない状況があるので、その周知方法についてどうされているのかということをお聞きしたいです。","respondent":"立川文化観光課長","answer":"通常一体的には運営はしていないところですが、この日のイベントに限りまして、全体を１つの会場と見立てて実施いたします。事前に全小学校にもチラシを配布しておりまして、そういった意味では、区内全域から皆さんお越しいただけるというふうに考えているところです。","id":"exchange-039"},{"speaker":"田中委員","kind":"確認","question":"では、公園の遊具の部分は、テープがされたりする状況となってしまうのかという確認をさせてください。","respondent":"立川文化観光課長","answer":"その辺は、まだ確認はしていないところですけれども、一般的な利用はできないですので、通常、例えばしながわ中央公園をフェスティバル等で利用する場合と同じように、一般的な利用はできないというようなことで実施をする予定です。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"休みの日は親子が結構長い時間滞在している状況なので、ぜひ公園部分は遊べるように開放されているといいなと思うのですけれども、いかがか尋ねました。","respondent":"立川文化観光課長","answer":"委員ご指摘のとおり、遊ぶ場所があまりないですので、いわゆる区主催のイベントですので、その辺については事前に調整をしっかり実施いたしまして、また、もし仮にその辺が使えないということでございましたら、事前に周知をしっかりいたしまして、開催したいと考えております。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/125111?Template=document&Id=6546#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":39199,"voices":127}}]);
